window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["22994632"]={"book":{"id":22994632,"title":"成功，动机与目标","author":"海蒂•格兰特•霍尔沃森 (Heidi Grant Halvorson)","translator":"汤珑","publisher":"译林出版社","pubdate":"2013-3","isbn":"9787544735506","tags":["心理学","自我管理","个人管理","目标设定","思维","成功","方法论","励志"],"memCount":5},"np":1,"pb":[21],"idx":[{"i":19788,"t":"灵活采用不同的思维模式，提升目标实现的可能性","l":"TF2-3","c":"沐阳蕾绽","g":1,"p":1},{"i":18774,"t":"一个人只有立下清晰的目标，才不容易屈服于眼前的困难，总能对生活保持热情，充满能量的稳步前行。 想知道以上问题的答案，请来","l":"TF1-1","c":"深蓝～","g":1,"p":1},{"i":17548,"t":"心理对照","l":"TF2-2","c":"刘阳","g":1,"p":1},{"i":16854,"t":"执行意图","l":"TF2-3","c":"黄艳","g":1,"p":1},{"i":13376,"t":"制定简单有效的计划","l":"TF1-1","c":"包包大人","g":1,"p":1},{"i":13172,"t":"如何达成目标","l":"TF2-3","c":"林露","g":1,"p":1},{"i":11805,"t":"成功，动机与目标","l":"TF2-3","c":"shanhua","g":1,"p":1},{"i":11089,"t":"学会做计划","l":"TF1-1","c":"shanhua","g":1,"p":1},{"i":10858,"t":"相同目标不同阶段的策略","l":"TF3-3","c":"天一","g":1,"p":1},{"i":10668,"t":"“如果…就…”的力量","l":"TF2-3","c":"yangzhuanfu","g":1,"p":1},{"i":9562,"t":"如何达成目标","l":"TF2-4","c":"斑驳阳光","g":1,"p":1},{"i":9524,"t":"如何让愿望达成","l":"TF3-2","c":"天一","g":1,"p":1},{"i":9238,"t":"“表现”与“进步“","l":"TF3-3","c":"慎蓓","g":1,"p":1},{"i":7983,"t":"目标实现1","l":"TF3-3","c":"赵自力","g":1,"p":1},{"i":7923,"t":"明确目标制定行动","l":"TF3-3","c":"王蒙","g":1,"p":1},{"i":7879,"t":"目标实现。","l":"TF3-3","c":"王蒙","g":1,"p":1},{"i":7551,"t":"目标实现~","l":"TF3-3","c":"赵自力","g":1,"p":1},{"i":4015,"t":"真诚赞美四要素，你会吗？","l":"TF1-2","c":"张溶冰","g":1,"p":1},{"i":2832,"t":"学会使用whatterms和Whyterms走出困境","l":"TF1-1","c":"李明","g":1,"p":1},{"i":2831,"t":"行动前使用心理对照的方法，促使行动更易成功","l":"TF1-2","c":"李明","g":1,"p":1},{"i":1111,"t":"让目标带来正能量","l":"TF3-2","c":"瑞雪","g":1,"p":1}],"ms":[{"id":19788,"topic":"灵活采用不同的思维模式，提升目标实现的可能性","learn_goal":"","remark":"对于目标，你是不是经常感觉到要么心力不足，要么行动力不足，导致总是半途而废，对自己充满自责？这本书从心理层面解读了成功、目标与动机之间的关系，被称为最硬核的“成功学”，或许能在这里找到你想要的答案，让目标心想事成。\n","level":"TF2-3","duration":20,"status":30,"type":0,"chaishujia":{"username":"沐阳蕾绽","city":""},"club":{"name":"青岛五月风分舵","city":"青岛"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>大家好，我是红蕾，接下来用三个标签介绍一下自己。\u003c/p>\u003cp>第一个标签：持续探索自我，喜欢读书和运动。\u003c/p>\u003cp>第二个标签：企业财务管理工作人员。\u003c/p>\u003cp>第三个标签：一位小学生的妈妈。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>在跟随我完成本次RIA现场学习后，学习者能够明白两种思考模式的差异，掌握具体场景下应该用什么样的模式更加有效。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>\u003c/p>\u003cp>今天参与学习的一共有3位小伙伴，一会儿将分小组讨论，请大家积极参与讨论。\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【F 特征】\u003c/strong>\u003c/p>\u003cp>《成就，目标与动机》由哥伦比亚大学社会心理学博士霍尔沃森撰写，他多次在权威杂志以及BBC、《哈佛商业评论》等重量级媒介发表学术成果。\u003c/p>\u003cp>这本书主要研究了关于制订计划和实行计划的相关问题，给出了非常具有可操作性的解答。\u003c/p>\u003cp>当你开始阅读这本书，你或许就会发出这样的赞叹：这不就是在说我么？\u003c/p>\u003cp>如果你在计划制订和目标管理方面存在诸多问题，我相信这本书会给你想要的答案。\u003c/p>\u003cp>\u003cstrong>【A 优势】\u003c/strong>\u003c/p>\u003cp>这本书与其他成目标管理等方面的书籍相比，有如下优势：\u003c/p>\u003cp>首先，大多数目标管理方面的书籍会从表层告诉你各种制订目标、拆解目标的方法，而这本书分析了人的心理动机对制订目标与实行目标的影响，并给出具体的操作性方法。\u003c/p>\u003cp>其次，这本书虽然是作者经过大量的学术研究、实际调查的研究成果，却与我们的个人生活息息相关，读起来非常顺畅，不拗口，不学术。\u003c/p>\u003cp>最后，这本书被研究目标、成功等方面的书籍多次引用，被称为最硬核的“成功学”。\u003c/p>\u003cp>\u003cstrong>【B 利益】\u003c/strong>\u003c/p>\u003cp>【B1本书】\u003c/p>\u003cp>在这本书里作者主要探讨了思考目标时可以采用不同的框架，以及如何最优地设定目标以增加成功的机会。对目标采取乐观或悲观的态度什么时候会有所帮助？应该思考为什么要实现某个目标，还是思考实现它需要哪些步骤？我们是否应当设想一下实现某个目标后可能会获得什么，或者如果未能实现目标可能会失去什么？\u003c/p>\u003cp>通过了解动机、目标与成就之间的关系，我们可以识破那些看似合理的建议，发现阻碍目标实现的原因，掌握简单有效的方法，改善自己的处境。\u003c/p>\u003cp>【B2拆页】\u003c/p>\u003cp>对于目标，我们有时会半途而废、迷失方向；而有时又会行动力不足，茫然失措，从而导致我们的目标无法实现。本次学习的主题就是当我们面对不同的事情和目标时，如何灵活选择不同的思考模式，也就是“为什么”和“是什么”，帮助我们解决心力不足与行动力不足在目标实现过程中的两大拦路虎。\u003c/p>","ratings_count":1,"texts":[{"id":24216,"quote":"\u003cp>当人们用“为什么”理解行为时总是会想得更宏观些——那些小的、日常的举动都变成更重大的目标的一部分。他们对长期目标更有概念。所以用“为什么”而非“是什么”想问题的人更少冲动，更少被诱惑，还更常会为行动提早做准备。（好吧，也许当“为什么”人群是酗酒者时这样说不太恰当，但是你懂我的意思。）思考“为什么”会让他们更确定自己是谁，想要什么。他们也不太会感觉到外界力量对他们的影响（比如说其他人或命运）。\u003c/p>\u003cp>当人们用“是什么”理解行为时，他们会聚焦在细节上——从A到B点的机械过程。他们有时没那么有斗志，也更容易为了一棵树而失去整个森林，但他们对在崎岖石路上行使特别在行。当你所做的事情特别复杂时，先放下全景而聚焦于手上的活儿是值得的。\u003c/p>\u003cp>这么说来，西瓜和芝麻的思考模式各有优劣，所以最好的策略就是根据目标的不同在两种模式中转换。有时这种转换会自然发生，有时不会。确定自己启用了最佳模式是非常重要的。如果没有，要赶快转换。你如果想更有干劲儿、增强自制力，则需要启动“为什么”模式。想想行为背后更大的意义和目的。当你在一盘甜点的诱惑前想要“守住贞操”时，请记得“为什么”你要减肥；当你的职员业绩惨淡时，提醒他们“为什么”业绩是最重要的——不光是为了公司，还是为了他们自己。\u003c/p>\u003cp>另一方面来讲，若要解决一件棘手的事，则用“是什么”思考更为恰当。学习一套新体系时需要把它拆成几个具体步骤。第一次滑雪吗？那么弯曲膝盖、对齐滑雪板的前端。别想着让谁对你的速度和优雅的姿态刮目相看——这样想往往导致滑雪新手牢牢地贴在书上。\u003c/p>","explains":"\u003cp>\u003cstrong>【WHAT】\u003c/strong>\u003c/p>\u003cp>本片段介绍了“为什么”和“是什么”这两种思维模式，它们分别适用于不同的场景和目标。当我们灵活运用这两种思维模式时，能更有效地实现目标。\u003c/p>\u003cp>\u003cstrong>【WHY】\u003c/strong>\u003c/p>\u003cp>如果我们在处理日常琐事时不思考“为什么”，可能会失去对生活的意义感；而面对宏大的目标时，如果不关注“是什么”，就可能停留在空想，难以将想法付诸实践。\u003c/p>\u003cp>我们在想实现一个目标的时候，往往直接着手去做，或者是做一个简单的步骤拆解，但这样做其实并不能保证目标的实现，我们容易半途而废、容易迷失方向。这是因为忽略了一个非常关键的问题“我为什么要实现这个目标”以及“我要怎样做才能保证这个目标能够实现”。\u003c/p>\u003cp>\u003cstrong>【反例】\u003c/strong>\u003c/p>\u003cp>当学习到这个拆页的时候，我意识到我在制订远期目标时存在的一个很大的问题。\u003c/p>\u003cp>我一直想在财务管理方面有所建树，成为一个有影响力的专家。\u003c/p>\u003cp>但我却迟迟未开始行动，也不知道我该去做什么，这样的一个目标就变成了我的一个想法，迟迟未能迈出实质性的一步。\u003c/p>\u003cp>我心里放不下这个目标，又不知道我该启动这个计划。\u003c/p>\u003cp>当我学习到这个拆页的时候，我发现了我的问题所在。\u003c/p>\u003cp>首先，我对这个目标的描述是不够具体的。\u003c/p>\u003cp>其次，对于这个目标我应该构建的是具体行动步骤，而不是它可以给我带来什么。\u003c/p>\u003cp>\u003cstrong>【HOW】细化步骤\u003c/strong>\u003c/p>\u003cp>\u003cstrong>那我们看看这个拆页片段是怎么做的呢？主要有以下四步：\u003c/strong>\u003c/p>\u003cp>第一步，明确自己想要实现的目标。\u003c/p>\u003cp>第二步，根据目标选择适合的思考模式，是用“为什么”还是“是什么”。\u003c/p>\u003cp>①如果需要提升动力或抵抗诱惑，就启动“为什么”模式，追问行为背后的意义和目的。\u003c/p>\u003cp>②如果遇到棘手或复杂的问题，则启动“是什么”模式，把目标拆解成具体、可执行的步骤。\u003c/p>\u003cp>第三步，定期检查自己的思维模式。如果越做越乱，或者效果不明显，要静下心来觉察是否需要调整思考方式。\u003c/p>\u003cp>\u003cstrong>【案例】\u003c/strong>\u003c/p>\u003cp>结合这四个步骤，我会调整如下：\u003c/p>\u003cp>第一，目标具体化。在三年内输出有深度思考的专业文章50篇，建立自己的影响力。\u003c/p>\u003cp>第二，匹配思考模式。这对于我来说是一个复杂的问题，我应该启动“是什么”模式，去构建具体的行动步骤。\u003c/p>\u003cp>第三，定期复检。也许在执行过程中我会遇到诱惑、困难而想放弃，那么我就要想想“为什么”，当目标实现的时候，它会给我带来什么好处。\u003c/p>\u003cp>\u003cstrong>【WHERE】\u003c/strong>\u003c/p>\u003cp>这两种思考模式适用于我们制订与个人有关或个人可以控制的生活或工作目标。\u003c/p>\u003cp>对于规则要求我们“必须”去做的事，我们没有选择权时是不适用的。\u003c/p>\u003cp>【异议预防】\u003c/p>\u003cp>你可能会问，这两种模式只能分开用吗？其实不是。我们在思考问题时可以交替使用“为什么”和“是什么”模式。如果动力不足，就用“为什么”模式，帮助自己确认价值和意义，提升心力；如果感到迷茫，就用“是什么”模式，把大目标拆解成可以立刻行动的最小计划。\u003c/p>","interaction":"\u003cp>通过以上讲解，大家已经了解了这两种思考模式的应用场景和步骤。\u003c/p>\u003cp>接下来，我们以场景《读书路上的“为什么”与“是什么”》来练习这两种思考模式的具体应用。\u003c/p>\u003cp>\u003cstrong>核心目标\u003c/strong>：通过模拟读书过程中的典型困境（动力不足、选书纠结、阅读拖延、理解卡壳），直观展示“为什么”模式与“是什么”模式的切换逻辑，让学员理解“何时用意义锚定方向，何时用细节攻克难关”。\u003c/p>\u003cp>角色A（小林）和角色B（小陈）是同事，小陈年初立下“一年读50本书”的flag，但半年过去只读了几本，还总说“读书没用，不如刷手机”。小林作为读书爱好者，用“为什么/是什么”思维帮他梳理，两人通过协作完成3个月读书计划，过程中自然切换两种模式解决问题。\u003c/p>\u003cp>本次练习一共4分钟，练习完毕后我将邀请一组伙伴做一下简要分享。\u003c/p>\u003cp>\u003cstrong>【A3现场演练】学习者案例：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小陈：哎，我今年年初立了一年读50本书的flag，结果小半年过去只读了两三本，现在完全没动力了，你说这怎么办呀？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小林：先说说你当初为啥立这么大的目标呀？本来就不爱读书吗？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小陈：那倒不是，我本来就一直看书，就是去年年底加了个读书社群，看大家都晒读了多少本，感觉自己太差了，脑子一热就定下目标了。而且我现在读的都是别人榜单推荐的，要么根本没那么好，要么看着看着就没兴趣了，总觉得读了也没用，还不如刷手机开心。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小林：原来你是跟着别人的推荐走，不适合自己呀。那你想过怎么调整不？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小陈：我想了，我不该乱扒网上的书单，应该去找我感兴趣领域里我喜欢的博主，他们推的应该跟我相关性更高，起码我能看进去，说不定还真有用。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小林：那如果真这么调整了，你觉得能有啥收获呀？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小陈：首先看得下去了，阅读量肯定能上来呀，而且哪怕只涨知识呢，读书总归是看了就比不看强，有用没用多少都有收获，比拿着手机浪费时间、看完还自责强呀。你说这样是不是就能解决动力不足的问题了？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小林：其实本质就是从最开始&quot;随大流凑数量&quot;，变成&quot;精准选适合自己的书&quot;——如果你当下有困扰，就读能解决问题的书，读到就能立刻用，自然就能体会到读书的用处，动力也就回来了。而且这个沟通里用提问引导思考的方式，不光能找读书动力，放在生活和工作其他沟通里也都好用呢。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【结语】\u003c/strong>\u003c/p>\u003cp>当你觉得心力不足时，想想当初为什么决定做这件事；当你行动拖延时，问问自己现在能做的最小一件事是什么。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1774621336000,"updated_at":1774781850000,"ria":true},{"id":18774,"topic":"一个人只有立下清晰的目标，才不容易屈服于眼前的困难，总能对生活保持热情，充满能量的稳步前行。 想知道以上问题的答案，请来参加我的拆书课！","learn_goal":"","remark":"一个人只有立下清晰的目标，才不容易屈服于眼前的困难，总能对生活保持热情，充满能量的稳步前行。\n想知道以上问题的答案，请来参加我的拆书课！","level":"TF1-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"深蓝～","city":"台州市"},"club":{"name":"宁波幸福虚度分舵","city":"宁波"},"prologue":"\u003cp>\u003cstrong> 一、【自我介绍】\u003c/strong>\u003c/p>\u003cp> 大家好！我是李梨花，李世民的李，樊梨花的梨花，也是唐代诗人诗句里“忽如一夜春风来，千树万树梨花开”的梨花。我来自美丽的海滨小城浙江玉环。我是一名财务工作者，也是一名钩织爱好者，有对钩织感深兴趣的伙伴可以一起探讨。我是一个积极乐观的有爱心有耐心的人，也是朋友口中的知心姐姐，因为我总是充满能量。我希望通过这次拆书活动，与大家一起学习一起成长。\u003c/p>\u003cp>\u003cstrong> 【过渡语】\u003c/strong> \u003c/p>\u003cp>我的个人介绍就到这里，现在我想和大家聊一聊我们拆书帮。\u003c/p>\u003cp>\u003cstrong> 二、【拆书帮介绍】\u003c/strong>\u003c/p>\u003cp>拆书帮是基于拆书法爱好者组建的学习社群，分舵分布在全国各地，比如说我们宁波幸福虚度分舵，我们的使命是帮助更多学习爱好者成长为拆书家，所以欢迎大家加入我们宁波幸福虚度分舵。我在之前也并不知道有拆书帮这个组织，而是通过朋友才了解到拆书法进而加入宁波幸福虚度分舵。以前看书就是为了打发时间，看过的书并没有留下什么太多印记，更不要说通过阅读来提升自己，直到了解到拆书法，我才开始思考如何把看过的书拆为己用。拆书法用三个便签（RIA）就能很好的帮助我们这些学习者将书中的知识与自身经验相结合，促进对知识的深度理解和吸收，提高我们的学习效果，让知识更好地转化为我们的实际能力。\u003c/p>\u003cp> \u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>关于拆书帮我就介绍到这里，接下来就由我来带领大家拆解一下今天的片段《“如果…就…”的力量，制订简单有效的计划》，下面我们花3分钟时间看一下原文片段，看完后大家扣1示意我一下。\u003c/p>","ratings_count":2,"texts":[{"id":23102,"quote":"\u003cp>\u003cstrong> 三、【R阅读原文拆页】\u003c/strong>\u003c/p>\u003cp> 原文片段《“如果…就…”的力量，制订简单有效的计划》，电子书103－104，片段来源《成功，动机与目标》。\u003c/p>\u003cp> 你找不到更简单更有效的策略来捍卫目标了，它能解决错失机会的问题。我总想把建立这种计划的方式及原因做成小册子插入市面上所有的减肥和励志类的书籍和光盘里。我还想放一打在诊所和学校办公室里。我甚至想寄几本给国会议员。总之，无论你想达成什么——减肥还是其他自我提高的目标，或是任何具有挑战性的目标——如果你能从这样一个简单的计划开始迈出第一步，成功的可能性将大大提高。\u003c/p>\u003cp>实践性总结\u003c/p>\u003cp>☆制订计划。我们在为目标打拼的途中遇到的很多问题都能被简单的“如果……就……”计划解决。不论你是想抓住当前的机会、抵抗诱惑、应对焦虑与自我怀疑，还是在困难中坚持不懈，这种计划都能助你一臂之力。\u003c/p>\u003cp>☆决定具体行动。你首先要决定达标所需的具体步骤。避免模糊不清的内容，例如“少吃点”“多学点”——你需要清晰、精确的目标。建立类似于“每晚至少学习四个小时”的清晰计划，你便对自己需要做什么以及达标与否一目了然了。\u003c/p>\u003cp>☆决定时间和地点。接下来，决定做每个步骤的时间和地点。请尽可能做到详细。这可以帮助你的大脑探测并抓住行动时机——即便是在你的意识无暇顾及时。\u003c/p>\u003cp>☆整理出“如果……就……”计划。把上述几步整理成一句“如果……就……”式的陈述。“如果是平日晚上，我就在我的房间里学习至少四个小时。”如果你愿意，可以把这些陈述写在笔记本里，或者重复说给自己听，让自己消化它。\u003c/p>\u003cp>☆瞄准障碍。想想达标路上有可能出现的障碍与诱惑。你要如何应对？为你想到的每一点制订一条“如果……就……”计划。（“如果平日晚上朋友叫我出去玩，我就拒绝并告诉他们周末见。”）这使你提早制订出最佳计划，不论遇到何种情况都能保证你不偏离达标的轨道。\u003c/p>","explains":"\u003cp>\u003cstrong> 四、【I便签重述知识】\u003c/strong>\u003c/p>\u003cp> 没有目标的人生就像一堆零碎的拼图，而有目标的人生才是可以描绘的蓝图。一个人只有立下清晰的目标，才不容易屈服于眼前的困难，总能对生活保持热情，充满能量的稳步前行。用“如果…就…”的条件式方法就能制定出简单有效的目标计划。我们可以将计划细分为具体的行动步骤，设定清晰的目标条件。比如“如果每天晚上7点我完成了工作，就跟着直播视频跳30分钟有氧操”“如果每天早上起床后，就学1小时英语”。这样的计划明确了在什么情况下做什么，大大提高了我们的行动力。\u003c/p>\u003cp> 以往我们想要达成目标时，总会陷入模糊的计划中，比如“我要减肥”“我要学游泳”，但这种计划没有具体的执行条件与方法，容易让我们在行动时感到迷茫而难以坚持。\u003c/p>\u003cp> 制订简单有效的计划有助于我们解决在实现目标的过程中的诸多困难，提高达成目标的可能性。\u003c/p>\u003cp>具体做法可以分为5步：\u003c/p>\u003cp>1.制订目标计划，在为目标努力的途中我们会遇到诸多困难，而这些困难都能运用“如果…就…”的条件式方法的来解决。\u003c/p>\u003cp>2.明确具体的行动，要明确达成目标所需的步骤，避免模糊不清的内容，例如：将多阅读细化为“每天晚上8点至10点在书房阅读60页心理学书”，这样制订的目标计划能让行动清晰而可执行。\u003c/p>\u003cp>3.明确时间地点：为目标规划具体的时间和地点。比如“每周二、四、六的晚上7点至8去瑜珈馆学瑜珈”。\u003c/p>\u003cp>4.整理有条件式的计划：把上述两步整理成“如果…就…”的句式。比如“如果每天晚上7点完成工作后就在书房阅读60页心理学书”，并记录下来再重复陈述加深印象。\u003c/p>\u003cp>5.针对障碍计划：思考实现目标可能遇到的阻碍与诱惑，为想到的每一步制定“如果…就…”目标计划，比如“如果上班日晚上朋友叫出去玩，我就拒绝并告诉她周末见。”确保制订出最佳计划，使行动不受干扰。\u003c/p>","interaction":"\u003cp> 五、【A1联系自己的相关经验】\u003c/p>\u003cp> 我一直有为了提升自己而增加阅读量的目标，但总是三天打鱼两天晒网的。去年夏天参加了一场线下读书会活动，使我又一次想起我那夭折的阅读目标，为了督促自己而跟伙伴们建了个阅读陪伴群，规定每天群里打卡，但是坚持了差不多两个多月，因为工作忙没时间等等各种原因各种借口也是三天打鱼两天晒网式的打卡，没能坚持当去年建立阅读陪伴群的初衷。现在想想就是因为没有制定可行的计划，没有清晰明确的目标，也没有具体约定一个月阅读几本书，只是约定每天打卡看书，而没有具体清晰的目标计划。如果当时按上面的方法制定详细的阅读目标计划那么现在我的阅读量也肯定明显提高。接下来要跟阅读陪伴群里的小伙伴一起重新按“如果…就…”这种条件式的方法来制定阅读目标计划，相信用这种方法一定能使我不受干扰的坚持达成我的目标。\u003c/p>\u003cp> 六、【A2具体应用】\u003c/p>\u003cp> 目标：在接下来的两个月内，运用“如果…就…”这种条件式方法制定阅读目标计划。\u003cbr>行动：1.先跟阅读陪伴群里的小伙伴分享我学到的这个方法，\u003cbr> 2.跟她们一起讨论并记录下为达成这个目标所需的相关行动，例如“如果是周一到周六的晚上8点，就开始阅读所定的书籍60页”。\u003cbr> 3.制定好相关行动后在其基础上完善具体的目标计划，明确制定具体的行动。比如“如果是周一到周六晚上8点，就开始在书房阅读所选书60页，如果在阅读过程中遇到知识盲区，就将其记录在笔记本上，并查阅相关文献”\u003cbr> 4.制订好详细目标计划后，再跟大家约定要互相监督确保大家都落实好用这个方法来完成我们每天的阅读量。\u003cbr> 5.建立反馈意见，跟伙伴们约定“如果看完一本书后，能够准确概括出主要意思和重要细节，就可以有一个奖励，如获得群里伙伴的小红花，两个月后看哪位伙伴的小红花多，奖励一本喜欢的书籍”。\u003cbr>在执行这个计划的过程中如果发现存在的问题，就要及时调整。比如发现晚上8点阅读时间太早也可根据实际情况调整到8点半，或者感觉每天阅读60页太少也可相应的调整。\u003cbr>我相信用“如果…就…”这个方法制定的目标计划一定会大大提高我的阅读量。\u003c/p>\u003cp> 七、【总结】\u003c/p>\u003cp>今天给大家分享了用“如果…就…”的条件式方法做计划目标，我们通过这种方法可以解决目标在实现过程中的诸多问题，使我们不再迷茫，大大提高了我们达成目标的可能性。大家过后可以试试用这种方法来制订我们的目标计划。非常期待大家来与我分享。\u003c/p>\u003cp> 我今天的分享就到这里，非常感谢大家的陪伴，谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1744123751000,"updated_at":1744439347000,"ria":true},{"id":17548,"topic":"心理对照","learn_goal":"","remark":"《成功，动机和目标》","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"刘阳","city":"沈阳"},"club":{"name":"沈阳海棠分舵","city":"沈阳"},"prologue":"\u003cp>\u003cstrong>介绍：\u003c/strong>\u003c/p>\u003cp>爱学习的伙伴们，大家好！欢迎来到今天的拆书课，我是拆书家刘阳。我们今天学习的内容来自“成功，动机和目标”这本书。\u003c/p>\u003cp>本次学习目标是运用“心理对照”的方法列出达成目标后的美好情景和过程中的障碍。\u003c/p>\u003cp>由于后续需要讨论，我们先提前分组，右手边的2人一组。\u003c/p>\u003cp>\u003cstrong>图书介绍\u003c/strong>\u003c/p>\u003cp>我们先了解《成功，动机和目标》这本书以及它能帮助我们解决哪些问题？\u003c/p>\u003cp>F这本书的作者海蒂·格兰特·霍尔沃森。他是美国哥伦比亚大学社会心理学博士。多次在权威学术以及BBC等重量级媒体发表学术成果。本书主要讲述“如何理解目标，定位目标以及达成目标”\u003c/p>\u003cp>A:与其他目标书籍相比，本书有两点优势：\u003c/p>\u003cp>1比较权威，本书所有建议均来自国际顶尖心理学家们的研究报告。\u003c/p>\u003cp>2对目标的讲述的比较全面：有放之四海皆准的制定目标的重要原则，还有达标过程中失败的常见原因和避免踏入陷阱的策略。\u003c/p>\u003cp>B：你设定目标时，满怀信心，成果却不尽人意。如果要想成功达成目标，你需要理解目标究竟是怎么一回事，在何处容易失败，以及怎么做才能帮助自己成功。无论什么目标这本书都能给你合理的建议。B2今天的拆页将引导你，在设定目标的过程中，通过“心理对照”的方式，提前感受成功，并预估行动中可能面临的障碍，避免盲目乐观的自信，而没有做好充分准备迎接挑战。\u003c/p>\u003cp>接下来，大家阅读原文拆页，给大家2分钟时间。\u003c/p>","ratings_count":1,"texts":[{"id":21735,"quote":"\u003cp>《成功，动机与目标》\u003c/p>\u003cp>正面思考P24\u003c/p>\u003cp>那么，树立并实现目标，而不是陷入白日梦中不能自拔，最好的方法是什么呢？最好的方法是在设定目标时积极地思考你已经实现目标时的情景，同时切合实际地思考在实现目标的过程中需要做些什么。厄廷根把它叫作心理对照（mental contrasting），意思是说，你首先设想你已经达到了自己的目标，然后再周全地思考妨碍目标实现的障碍。如果你大学毕业后想找份报酬丰厚的工作，首先设想自己被一家顶级公司录用的情景，然后再考虑你在实现此目标时会存在什么障碍，比如，和你一样申请了该职位的其他优秀的应聘者，他们是你的竞争对手。这种思维将使你不得不寄出很多份求职申请，不是吗？心理学家将其称为“必须行动”的感觉，这是实现目标所需的至关重要的心理状态。尽管幻想找到一份好工作或者与心仪已久的某个人坠入爱河也许是一件有趣的事，但幻想无法让你取得任何实质进展。心理对照可以引导我们把关注点放在必要的行动上，从而将愿望和白日梦转化为现实。\u003c/p>","explains":"\u003cp>\u003cstrong>I复述\u003c/strong>\u003c/p>\u003cp>\u003cstrong>Wha\u003c/strong>t这个拆页主要讲的内容是运用“心理对照”设定目标，所谓的“心理对照”先想象一下实现目标时的美好情景，然后在反思其中的障碍。\u003c/p>\u003cp>\u003cstrong>where\u003c/strong>这个方法只适用你真心相信可以实现的目标，同时也能帮助你对目标进行“决策”，抛开无法实现的幻想。\u003c/p>\u003cp>\u003cstrong>Why：\u003c/strong>因为目标并不是想想就能实现。达成目标最好的策略是用乐观的方式看待目标，同时思考具体需要做什么才能实现目标。\u003cstrong>“心里对照”方法，\u003c/strong>能让你在心理感受到“行动的必要性”。帮助我们感受成功的同时，引导我们聚焦行动，为了达成目标，我要做些行动。\u003c/p>\u003cp>如果不这样做，你可能陷入到盲目乐观的陷阱里，“相信自己能轻而易举成功”而没有做好充分的准备去迎接未来的挑战，导致目标没有实现。\u003c/p>\u003cp>\u003cstrong>How：\u003c/strong>运用“心理对照”制定目标的具体步骤：\u003c/p>\u003cp>1写目标——在纸上写下一个你最近想实现目标（比如，我想阅读完非暴力沟通一本书）\u003c/p>\u003cp>2想象美好情景——愿望实现后，会有哪些美好情景发生（读完这本书，我将与同事沟通顺畅，工作效率更高）\u003c/p>\u003cp>3思考障碍——思考你和美好结局之间会有哪些障碍。（读书时，可能看几分钟就会发困）\u003c/p>\u003cp>4按照上述方法列出3组障碍与目标。\u003c/p>\u003cp>列举一个我减重的例子\u003c/p>\u003cp>1在纸上写下一个你最近的愿望（我最近的愿望是减重6kg）\u003c/p>\u003cp>2成功后的美好情景：身体变得更加轻盈，精神状态也会更好。\u003c/p>\u003cp>3达成愿望的障碍：吃饭的时候会忍不住多吃，导致能量摄入过多。\u003c/p>\u003cp>4第二组：好处——穿衣服会更帅。障碍——每天都会面临一段挨饿的时候\u003c/p>\u003cp>5第三组：好处——不用担心会因肥胖产生的疾病。障碍——运动累的时候，想放弃。\u003c/p>\u003cp>\u003cstrong>预防异议\u003c/strong>：在座的伙伴可能会产生这样疑问：\u003c/p>\u003cp>1这个方法真的有效吗？只是把达成目标障碍写出来，就能更有助于完成目标？有效，加布里埃尔做个一项调查，一些肥胖女士参加一个减肥计划，调查他们“认为怎样才能实现减肥计划”。结果相信自己能减肥成功但不认为是件容易得事，并且为之准备的女士多减掉10斤。\u003c/p>\u003cp>2第二个疑问是，美好情景与障碍要一一对应吗？多写一些达成目标后的美好情景或障碍不可以吗？这个没有明确具体的研究。但是每一好处会给你信心，增强动力，每一个障碍可能会让你提前准备。\u003c/p>","interaction":"\u003cp>【场景描述】\u003c/p>\u003cp>通过这个拆页的讲解，大家清晰了运用“心理对照”的方式制定目标，能为达标过程中出现挑战做准备，防止盲目乐观。\u003c/p>\u003cp>A2\u003c/p>\u003cp>接下来请大家思考一下，现在或者是接下来你想要实现的目标，可能是工作目标，学习目标，生活目标，健康目标。例如一年阅读50本，一个月减重3kg，通过**考试等。给大家计时一分钟思考，稍后邀请一位伙伴分享他的目标。\u003c/p>\u003cp>参与者A:用10年的时间，成为MCC(教练技术的一种能力评价）\u003c/p>\u003cp>\u003cstrong>接下来，大家运用“心理对照”的方法，为自己刚刚确定的目标，写出三组，达成目标后会美好情景与过程的障碍。给大家5分钟思考，稍后我会邀请一位伙伴进行分享他的心理对照是怎样写的。\u003c/strong>\u003c/p>\u003cp>参与者B：\u003c/p>\u003cp>目标：在小红书上用汉语，英语，日语，发表内容\u003c/p>\u003cp>第一组：美好情景——浏览的人会更多，会有大量粉丝。障碍——粉丝可能对我的内容不感兴趣，没达到预期效果\u003c/p>\u003cp>第二组：美好情景——可以接广告赚钱。障碍——广告不会吸引粉丝，对粉丝是个伤害。\u003c/p>\u003cp>第三组：美好情景——可以浏览很多优美文章。障碍——需要很多词汇量积累，虽然以前学过，但是不用很多年。\u003c/p>\u003cp>对这个拆页做个总结：“相信自己能轻而易举成功”和“相信自己能成功”不是一回事，它属于盲目乐观。为了达成目标的，提高成功概率，你要学会运用“心理对照”的方式设定目标。避免因为盲目乐观，导致无法达成目标。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1714307045000,"updated_at":1714533961000,"ria":true},{"id":16854,"topic":"执行意图","learn_goal":"","remark":"无","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"黄艳","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>\u003cstrong>请问观察家老师拿到记录表、准备表和拆页了么？\u003c/strong>\u003c/p>\u003cp>大家好，我是黄艳，感谢各位参加今天的拆书练习。\u003c/p>\u003cp>我要成为拆书家的纪律委员，抱团晋级；\u003c/p>\u003cp>同时我也是一名道德经爱好者；\u003c/p>\u003cp>欢迎大家下来交流！\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>根据现场人数进行分为两组。\u003c/p>","ratings_count":1,"texts":[{"id":20972,"quote":"\u003cp>R原文片段：\u003c/p>\u003cp>摘录来自:《成功，动机与目标》P166-P167.\u003c/p>\u003cp>“如果……就……”的力量\u003c/p>\u003cp>这些计划的美好在于简单。你找到一个想去实现的目标，说清达成它的具体时间、地点和方式。比如，就拿之前的减肥目标举例。第一步，应该把“少吃”改为“每天摄入热量不超过1500卡路里”；第二步，“多运动”应该变成“每周一、三、五上班前去健身房锻炼一个小时”。戈尔维策把这类计划叫做“建立执行意图”，听上去挺拗口，实际就是指一种“如果……就……”的计划方式：如果已经吃了1500卡路里的食物，我就不能再吃了；如果现在是星期一早晨，我就要上班前先去运动。\u003c/p>\u003cp>在听到圣诞作文这个例子的几年后，我有幸与彼得和他的妻子——纽约大学博士后研究员——加布里埃尔·奥丁根一起工作。参与研究的还有宾夕法尼亚大学的安杰拉·达克沃思。我们想对“执行意图”进行彻底测试。我们用了出名的缺乏纪律和自制力的人群进行实验——正在放暑假的十年级学生。这些学生在即将开始的学期里都将面对“学业能力倾向初步测验”（PSAT）的考验，而他们每个人的目标都是在暑假里为测验做准备。5月时，我们给了每个学生一本模考题——其中有10套题，让他们在暑假中完成，9月份开学时上交。我们让一半学生决定了暑假做题的时间和地点（比如“平日早餐后，在我的屋子里”)。学生们在暑假期间没有得到任何提醒，那些写下了时间地点的人也把纸片上交了，自己没有留底。9月份我们把习题收回来时发现，没有做时间地点计划的学生平均完成了100道习题，而做了计划的学生平均完成了250道题！我们再次看到了成倍的效应，尽管过程持续了一整个暑假。而这成效仅仅来自我们的干预实验占用学生的一点点时间。\u003c/p>","explains":"\u003cp>图书介绍：\u003c/p>\u003cp>【F】:今天的拆页来自《成功，动机与目标》，\u003c/p>\u003cp>作者格兰特·沃尔霍森是美国哥伦比亚大学心理学博士。\u003c/p>\u003cp>豆瓣评分8.8分\u003c/p>\u003cp>全书围绕：“制定目标、认识目标以及落实行动”展开\u003c/p>\u003cp>【A】:与其他同类书籍不同，本书不仅向我们揭示了成功和目标的关系，同时提出了一系列切实可行的落地方法，帮助我们实现目标。\u003c/p>\u003cp>【B1】:这里我想请大家思考一下，过去我们在实现目标的过程中遇到了哪些困难？为什么我们的目标往往难以实现呢？本书将为我们答疑解惑。\u003c/p>\u003cp> 学习目标：\u003c/p>\u003cp>当我们想养成某种新习惯困难重重难以实现时，运用\u003c/p>\u003cp>“执行意图法”后，目标不再是一句空话，而是具体的，清晰地知道自己**时间要做什么\u003c/p>\u003cp>I便签：\u003c/p>\u003cp> 【WHAT &amp; WHY】：\u003c/p>\u003cp>what执行意图法是一种自我调节的策略，可以理解成“如果 X 发生了，那么我就做Y”的力量，清晰地知道自己**时间要做什么。\u003c/p>\u003cp>why运用执行意图法后，行动将变得迅速、有效，且不需要有意识的参与\u003c/p>\u003cp>【WHERE】：当准备养成一种新习惯的时候\u003c/p>\u003cp>【HOW】\u003c/p>\u003cp> 1. 明确目标：是什么？\u003c/p>\u003cp> 2. 关键要素：我在具体时间、具体地点、做什么\u003c/p>\u003cp> 3. 标准：做到什么程度/标准，可衡量\u003c/p>\u003cp> 4. 行为指令：“如果……就……”\u003c/p>\u003cp> 接下来呢，我举个自己运用这个方法的例子\u003c/p>\u003cp>1.目标：我想要养成的习惯：坚持锻炼身体\u003c/p>\u003cp>2.关键要素：\u003c/p>\u003cp>时间：晚上 08:00； 地点：客厅；人物：我\u003c/p>\u003cp>做什么：用瑜伽垫，跟着KEEP视频练习有氧操\u003c/p>\u003cp>3.标准：\u003cu>每天30分钟\u003c/u>\u003c/p>\u003cp>4.行为指令：时间如果来到了每天晚上的8:00，我就会在客厅，用瑜伽垫，跟着KEEP视频练习30分钟有氧操。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>大家可能会问：这里的“目标”可以随便定吗？\u003c/p>\u003cp>当然不是，这里的目标必须是有持续的行为才能完成的目标，比如：戒烟、减肥、健身等等\u003c/p>","interaction":"\u003cp>\u003cstrong>【场景描述】\u003c/strong>\u003c/p>\u003cp>我们刚刚学习了“执行意图法”，现在我们一起来做个演练，请大家认真听一下要演练的场景： \u003c/p>\u003cp>重阳节公司组织所有管理者爬山，上山途中年龄最小的王经理晕倒了，被担架抬下山的过程中，他觉得丢脸死了，下决心通过 跑步锻炼身体！制定目标后，时间过去了整整一周，他只跑了一天，现在他特别烦恼：希望可以“持续跑步”这个行为，却不知道如何才能做到？突然他想起来：朋友李总擅长“执行意图法”，可以让行动变得迅速有效，所以今天他来向朋友李总寻求帮助！\u003c/p>\u003cp>\u003cstrong>【A3指令】\u003c/strong>\u003c/p>\u003cp> 现在，请每两个人一组，在组内进行演练。一个人扮演王经理，一个人扮演李总。李总在听完王经理的困扰后，应用这个“执行意图法”，帮他梳理出他的目标，提高他的行动力和目标完成率。\u003c/p>\u003cp>演练时间4分钟，4分钟后，我会邀请一位小伙伴扮演“王经理”，一位小伙伴扮演“李总”，大家一起听听他们是怎么应用执行意图法，养成持续跑步这个习惯的？\u003c/p>\u003cp>王：李总，我知道你擅长“执行意图法”，所以今天我来向你寻求帮助\u003c/p>\u003cp>李：发生的什么啊？\u003c/p>\u003cp>王：重阳节公司组织所有管理者爬山，上山途中最为年龄最小的我晕倒了，被担架抬下山的过程中，真是觉得丢脸死了，所以下决心通过 跑步锻炼身体！制定目标后，时间过去了整整一周，我只跑了一天，现在特别烦恼：希望可以“持续跑步”这个行为，却不知道如何才能做到？（目标：锻炼身体）\u003c/p>\u003cp>李：哦哦，这样啊！那你一般什么时间方便呢？\u003c/p>\u003cp>王：周五、周六的晚上\u003c/p>\u003cp>李：那时间定在周五、周六晚上7:30，方便吗？\u003c/p>\u003cp>王：可以\u003c/p>\u003cp>李：确定是选择跑步的方式吧？\u003c/p>\u003cp>王：是的\u003c/p>\u003cp>李：计划到哪里跑步呢？\u003c/p>\u003cp>王：楼下健身房\u003c/p>\u003cp>李：每次跑多长时间呢？\u003c/p>\u003cp>王：40分钟\u003c/p>\u003cp>李：好的，结合你刚刚的描述，你的意思是：时间如果来到周五、周六晚上7:30，我就在楼下健身房跑40分钟的步！\u003c/p>\u003cp>王：哦哦，明白了，这样的行为指令就很有力量，到这个时间，我就在楼下健身房跑步40分钟！谢谢你！\u003c/p>\u003cp>感谢今天所有人的参与，通过大家的实践，我们更加清晰的掌握 “执行意图法”\u003c/p>\u003cp>以上就是我今天TF2-3拆书分享的全部内容，感谢观察家，感谢各位小伙伴。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1699190028000,"updated_at":1699287511000,"ria":true},{"id":13376,"topic":"制定简单有效的计划","learn_goal":"","remark":"你的计划做的对么？\n为什么你计划写了一堆还是无法实施？\n怎样做计划能帮我们实现目标？\n让我们一起学习如何制定最简单有效的计划来实现目标吧！","level":"TF1-1","duration":18,"status":30,"type":0,"chaishujia":{"username":"包包大人","city":"北京市"},"club":{"name":"北京城市之光分舵","city":"北京市"},"prologue":"\u003cp>\u003cstrong>【自我介绍】1分钟\u003c/strong>\u003c/p>\u003cp>大家晚上好!我是拆书家包包大人，非常感谢大家今天来参加拆书帮线上的活动。今天我的流程是这样（注：展示PPT目录页）\u003c/p>\u003cp>首先用三个标签介绍一下我自己:\u003c/p>\u003cp>第一个标签：我是一名财务工作者，主要就是干所有一切跟钱有关的活儿，跟钱有关的事儿太多了，所以经常加班。\u003c/p>\u003cp>第二个标签：我是一名瑜伽爱好者，瑜伽可以缓解身心疲惫，又不需要太多肺活量儿，对我这种肺活量不够的人来说比较友好，有喜欢瑜伽的朋友我们可以私下里交流。\u003c/p>\u003cp>第三个标签：我是一个间歇性奋斗者，努力的时候在忙也能学习健身，比如加班到11点我回家也会健身打卡40分钟左右，不努力的时候我就躺平了，所以加入分舵2年多了一直都没拆书。\u003c/p>\u003cp>\u003cstrong>【拆书帮介绍】【2分钟】\u003c/strong>\u003c/p>\u003cp>为了便于还不了解拆书帮的小伙伴了解我们这个组织，接下来我来介绍一下拆书帮。\u003c/p>\u003cp>首先，拆书是什么：\u003c/p>\u003cp>“拆书”不是说把一本书拆开，也不是以这本书的知识为重心，而是以我们学习者为中心，它要求我们将知识关联到个人的经验，并且能够运用它去规划和行动，就是一种最能够“学以致用”的学习方法论。主要适用于我们成年人，目标是为了提升我们的能力、解决问题。\u003c/p>\u003cp>落到实处即分为个人学习的“便签法”和组织学习的“拆书法”，个人学习就是让人读一本书就能达到参加同主题培训的效果；组织学习就像我们今天的活动，由一位拆书家拿一本书加工出一场现场学习，引导和促进学习者将书中的内容拆为己用。从学习者的学习效果来衡量的话，一位拆书家的价值不亚于一位培训师。\u003c/p>\u003cp>那么我们经常说的拆书帮又是什么：\u003c/p>\u003cp>“拆书帮”，是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵（也叫称拆书帮俱乐部），比如我们就叫做北京城市之光分舵。拆书帮分舵是一种公益性“青年自发组织”，使命是为了帮助更多学习爱好者成长为拆书家，所以特别欢迎大家加入我们分舵。\u003c/p>\u003cp>\u003cstrong>R原文片段【1.5分钟】\u003c/strong>\u003c/p>\u003cp>今天我分享的是美国一位社会心理学博士写的《成功，动机与目标》中的一个片段，大概需要12-15分钟的时间。首先我们先来阅读原文片段，请大家用1分钟左右的时间阅读，原文片段我会用PPT展示给大家，读完后请大家在讨论区打个1，谢谢。\u003c/p>","ratings_count":1,"texts":[{"id":17388,"quote":"\u003cp>\u003cstrong>【R】拆解片段《成功，动机与目标》110页\u003c/strong>\u003c/p>\u003cp>“如果……就……”的力量\u003c/p>\u003cp> 这些计划的美好在于简单。你找到一个想去实现的目标,说清达成它的具体时间、地点和方式。比如,就拿之前的减肥目标举例。第一步,应该把“少吃”改为“每天摄入热量不超过1500卡路里”；第二步,“多运动”应该变成“每周一、三、五上班前去健身房锻炼一个小时”。戈尔维策把这类计划叫做“建立执行意图”,听上去挺拗口,实际就是指一种“如果……就……”的计划方式：如果已经吃了1500卡路里的食物,我就不能再吃了;如果现在是星期一早晨,我就要上班前先去运动。\u003c/p>","explains":"\u003cp>\u003cstrong>I拆书家讲解引导：【4分钟】\u003c/strong>\u003c/p>\u003cp>【2分钟】\u003c/p>\u003cp>What：这个片段讲述了如何能够制订简单有效的计划，运用此方法计划能够顺利实施。\u003c/p>\u003cp>Why修改版：我们经常给自己制定各种目标，为了实现目标又要制定行动计划，然而并非所有的计划都能顺利实施，有的时候我们错失了行动的机会，有的时候我们完全忘记了目标，还有可能我们惧怕困难而不愿付诸行动，不论是什么原因，我们经常性地让机会白白流失，如果我们想行动起来达成目标，必须学会抓住当下的时机，而“如果……就……”计划恰恰是为此量身设计的。\u003c/p>\u003cp>我给大家举个例子，比如我的目标是在4月26日拆完1-1，我的行动计划是16日写完拆书稿，但是那几天我突然变得特别忙，最终在23号才写完拆书稿。后来当我知道因为疫情不能举办线下活动，窃喜不用继续改稿子之后，我就把这个事儿抛到脑后去了。接下来我有机会在4月30日参加线上拆书活动，把1-1拆完顺便积累线上拆书经验，但是我惧怕重头修改一遍稿子我就没有报名。结果就是大家看到的情况，我从4月26号拖到5月10日。这一次我机智的采用了“如果……就……”制定计划，成功的在今天与大家一起参加这次活动。如果你也有我这样的情况，接下来就跟我一起学习如何让自己迅速的行动起来吧！\u003c/p>\u003cp>【2分钟】\u003c/p>\u003cp>How:\u003c/p>\u003cp>具体步骤如下：\u003c/p>\u003cp>第一步：制定清晰的具体行动。我们首先需要更清晰、更精确的目标。\u003c/p>\u003cp>例如“多学点”是不行的，我们要把它变成“每晚至少学习一个小时”这样的清晰计划,这样就能对自己需要做什么以及达标与否一目了然。\u003c/p>\u003cp>第二步：尽可能做到详细，决定做每个步骤的时间和地点。\u003c/p>\u003cp>例如晚上8：00开始，坐在家里桌子前学习一个小时。\u003c/p>\u003cp>第三步：将上述几步整理成“如果……就……”式的陈述。\u003c/p>\u003cp>例如：“如果是平日晚上，8：00到了，我就坐在我的房间桌子前学习一小时。\u003c/p>\u003cp>第四步：瞄准障碍。想想达标路上有可能出现的障碍与诱惑，要提早制订出最佳计划,不论遇到何种情况都能保证不偏离达标的轨道。\u003c/p>\u003cp>例如：如果平日晚上朋友叫我出去玩,我就拒绝并告诉他们周末见。\u003c/p>\u003cp>Where: 无论目标是什么，是谁的，都可以运用这个计划。不要仅仅只是把需要的行动做出概括，把所有重要的细节一股脑地忽略了。而是要安排达标所需的时间、地点、方式，这些才是提高计划成功率的决定性关键。\u003c/p>","interaction":"\u003cp>\u003cstrong>A学习者拆为己用：【3.5分钟】\u003c/strong>\u003c/p>\u003cp>A1:【2分钟】\u003c/p>\u003cp>故事：“三月不减肥，四月徒伤悲”，3月初的时候我就跟同事约定好，要一起减肥，于是我们决定少吃多动，可是遇上加班的时候我就饿了大喊脑子不动了，必须点外卖吃饭，有时候同事中午叫我出去吃饭不好拒绝我就去了，回家太晚就觉得太累不想运动想休息了。结果到了3月底，我的体重依然没变，减肥失败了。\u003c/p>\u003cp>反思：后来我读到了这个片段，少吃多动原来根本不是一个计划，于是我把它改成了：\u003c/p>\u003cp>第一步：首先制定具体的行动，每晚要练一节瑜伽课；\u003c/p>\u003cp>第二步：然后规划时间和地点变成“晚上8：00，在家里瑜伽垫上做一节瑜伽课。”\u003c/p>\u003cp>第三步：把这个计划改成“如果……就……”式的陈述：如果晚上8：00了，就打开课程，跟着课程在家里的瑜伽垫上做一节40-45分钟的瑜伽课。\u003c/p>\u003cp>第四步:想一想运动路上可能出现的障碍，比如同事叫我去吃饭，“如果同事叫我去吃饭，就拒绝她并告诉她我在减肥”，比如晚上加班饿了想点外卖，“如果晚上加班饿了，就点一份减脂餐”，比如回家太晚不想运动，“如果回家太晚，不够做一节40-45钟的课程，就练一节10-15钟的短时间课程。”\u003c/p>\u003cp>这次我成功的在4月份减掉了4斤。\u003c/p>\u003cp>接下来我的目标：\u003c/p>\u003cp>A2:【1.5分钟】\u003c/p>\u003cp>目标：本周五之前，为我的会计考试制定学习计划。\u003c/p>\u003cp>行动：\u003c/p>\u003cp>第一步：制定清晰的具体行动，即每天晚上至少学习一个小时会计；\u003c/p>\u003cp>第二步：尽可能决定做每个步骤的时间和地点，即每天晚上9：00，坐在家里书桌前，打开会计课程，听一节50-60分钟的课程。\u003c/p>\u003cp>第三步：将上述几步整理成“如果……就……”式的陈述。\u003c/p>\u003cp>如果到了晚上9：00，就打开会计课程，听一节50-60分钟的课程。\u003c/p>\u003cp>第四步:想一想学习路上可能出现的障碍，比如朋友约我出去玩，“如果平日晚上朋友约我出去玩，就拒绝她并告诉她周末再见。”比如晚上9：00还在加班，回家很晚了，“如果平日晚上加班超过了9：00，没有时间学习了，就把前一天学习的内容回顾一遍。”\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1652188715000,"updated_at":1652189268000,"ria":true},{"id":13172,"topic":"如何达成目标","learn_goal":"","remark":"本书通过严谨可靠的科学依据和大量极具启发性的关系，同时提出了一系列切实可行的方法，帮助我们实现目标。","level":"TF2-3","duration":23,"status":30,"type":0,"chaishujia":{"username":"林露","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>\u003cstrong>分组\u003c/strong>：\u003c/p>\u003cp>请问观察家拿到我的准备表了吗？小伙伴们拿到我的拆页了吗？\u003c/p>\u003cp>由于今天涉及到讨论，在开始学习之前，我先给大家分个组，由于之前的小伙伴已经分好组了，我将延用刚刚的分组。\u003c/p>\u003cp>\u003cstrong>自我介绍\u003c/strong>：\u003c/p>\u003cp>大家好，我是林露，用三个数字来介绍我自己。这三个数字就是520。5代表这是我来成都的第5年，2代表我这次是第2次晋级2-3，0代表我好几个月没晋级，现在得从头开始找晋级感觉了。我就是520，林露。\u003c/p>\u003cp>\u003cstrong>学习目标\u003c/strong>：\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，大家能够运用今天学到的【行动促进法】的四个步骤“量化目标、优化内容、设置触点、催化行动”,现场进行一次演练。你们有没有期待呀!\u003c/p>\u003cp>\u003cstrong>图书介绍：\u003c/strong>\u003c/p>\u003cp>【F】:我今天要分享的片段来自《成功，动机与目标》，作者格兰特·沃尔霍森是美国哥伦比亚大学心理学博士。本书的内容来源成百上千篇学术报告，全书分为三个部分：如何制定目标、如何认识目标以及如何落实行动。豆瓣评分8.8分。\u003c/p>\u003cp>【A】:相比于其他同类书籍，本书通过严谨可靠的科学依据和大量极具启发性的实验，向我们揭示了成功和目标的关系，同时提出了一系列切实可行的方法，帮助我们实现目标。\u003c/p>\u003cp>【B1】:相信每个人或多或少都有过这样的经历：想拥有健康苗条的身材，却难以抗拒甜食；想认真读完一本书，翻了几页后却因各种事情搁置。为什么我们制定了这么多计划，却难以实现呢？本书将为我们答疑解惑。\u003c/p>\u003cp>【B2】而如果你在戒烟、减肥上经常反复，在早起、健身和坚持阅读等方面有行动困难症的话，学完本片段，你的行动力将会有所提高。\u003c/p>","ratings_count":1,"texts":[{"id":17154,"quote":"\u003cp>摘录来自:《成功，动机与目标》P166-P167.\u003c/p>\u003cp>“如果……就……”的力量\u003c/p>\u003cp> 这些计划的美好在于简单。你找到一个想去实现的目标，说清达成它的具体时间、地点和方式。比如，就拿之前的减肥目标举例。第一步，应该把“少吃”改为“每天摄入热量不超过1500卡路里”；第二步，“多运动”应该变成“每周一、三、五上班前去健身房锻炼一个小时”。戈尔维策把这类计划叫做“建立执行意图”，听上去挺拗口，实际就是指一种“如果……就……”的计划方式：如果已经吃了1500卡路里的食物，我就不能再吃了；如果现在是星期一早晨，我就要上班前先去运动。\u003c/p>\u003cp> 在听到圣诞作文这个例子的几年后，我有幸与彼得和他的妻子——纽约大学博士后研究员——加布里埃尔·奥丁根一起工作。参与研究的还有宾夕法尼亚大学的安杰拉·达克沃思。我们想对“执行意图”进行彻底测试。我们用了出名的缺乏纪律和自制力的人群进行实验——正在放暑假的十年级学生。这些学生在即将开始的学期里都将面对“学业能力倾向初步测验”（PSAT）的考验，而他们每个人的目标都是在暑假里为测验做准备。5月时，我们给了每个学生一本模考题——其中有10套题，让他们在暑假中完成，9月份开学时上交。我们让一半学生决定了暑假做题的时间和地点（比如“平日早餐后，在我的屋子里”)。学生们在暑假期间没有得到任何提醒，那些写下了时间地点的人也把纸片上交了，自己没有留底。9月份我们把习题收回来时发现，没有做时间地点计划的学生平均完成了100道习题，而做了计划的学生平均完成了250道题！我们再次看到了成倍的效应，尽管过程持续了一整个暑假。而这成效仅仅来自我们的干预实验占用学生的一点点时间。\u003c/p>","explains":"\u003cp>【WHAT &amp; WHY】：\u003c/p>\u003cp>该片段讲的是一种可以让目标更加容易实现的方法，即“行动促进法”。\u003c/p>\u003cp>【WHERE】：这个方法适用于我们心中已有了较清晰、明确的、可执行的、且愿意实现的目标。\u003c/p>\u003cp>【HOW】（细化原文步骤）：那我们具体该怎么做呢？\u003c/p>\u003cp>第一步：量化目标。定目标不能太泛，不能出现“少吃点、多运动...”等模糊的字眼。需要用数字来量化。例如：减肥5斤等。\u003c/p>\u003cp>第二步：优化内容。这个指的是加上时间期限、如何做以及需要做到什么程度、达到什么标准才算达到目标等相关内容。\u003c/p>\u003cp>第三步：设置触点。给这个行动设置一个启动器，也就是当出现什么样的情景时我们就能马上想到我该去做这件事了。就像灯的开关，触碰开关灯就会亮。\u003c/p>\u003cp>第四步：催化行动。使用“如果...就”的句式，催促自己行动起来。\u003c/p>\u003cp>【EXAMPLE】：下面我举个例子。\u003c/p>\u003cp>最近，我想改变爱感冒的毛病，准备锻炼身体，就想到去跑步。\u003c/p>\u003cp>首先，我们来看“跑步”这个目标就太泛了，需要细化，接着我会说那就跑一会吧，一会是指多久呢，5分钟还是50分钟，这个也需要拆解细化。最后决定每天跑15分钟。这个过程就是第一步：量化目标。\u003c/p>\u003cp>第二步：优化内容。于是我对自己说从明天开始跑步--慢跑，先跑2个月，那么要达到什么程度才算达成锻炼身体的目标呢？这里应该有个对比，例如，我以前1周感冒一次，通过2个月的坚持跑步，现在1个月才感冒一次，这就算达成目标了。\u003c/p>\u003cp>第三步：设置触点。放学路过操场就是触发点。\u003c/p>\u003cp>第四步：催化行动。于是我就对自己说“如果放学路过操场时，且当天没有下雨，我就进去慢跑15分钟”\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>有小伙伴可能会问，这个“触点”可以随意设定吗？\u003c/p>\u003cp>当然不行，我们设定时间地点是为了触发行动，要实现目标，我们要选择能经常性触发的时间地点，且这个时间地点能为触发行为提供“便利”条件。比如说，我放学回寝室肯定要经过操场，而且我每天都会经过操场，这就为我慢跑提供了条件。所以我们要选择能经常性触发行为的时间地点。\u003c/p>","interaction":"\u003cp>\u003cstrong>场景设计\u003c/strong>\u003c/p>\u003cp>通过以上的讲解，大家都清楚了解行动促进法的4个步骤，我们来回忆下，分别是：“量化目标、优化内容、设置触点、催化行动”。光了解还不够，接下来，我们需要学以致用，让小伙伴们现场做个场景演练，加深大家的理解，帮助大家熟练应用。请大家仔细听一下要演练的场景：\u003c/p>\u003cp>场景背景：小张是个爱学习爱看书的努力拼搏上班族，很想利用每天坐地铁上下班的时间来看一些书，却不知如何做才能促进自己这个行动。左思右想的他竟然在梦中遇见了《成功，动机与目标》的作者格兰特·沃尔霍森，小张知道沃尔霍森对这个行动促进法很有研究，所以就把自己的烦心事告诉了沃尔霍森，并寻求帮助。\u003c/p>\u003cp>\u003cstrong>小组讨论\u003c/strong>\u003c/p>\u003cp>现在，请每两个人一组，在组内进行演练。一个人扮演小张，一个人扮演沃尔霍森。沃尔霍森要在听完小张的困扰后，应用这个行动促进法，帮他梳理他的目标，提高他的行动力和目标完成率。\u003c/p>\u003cp>演练时间4分钟，4分钟后，我会邀请一位小伙伴扮演“小张”，一位小伙伴扮演“沃尔霍森”，大家一起听听他们是怎么应用行动促进法的。\u003c/p>\u003cp>\u003cstrong>角色扮演（现场完整案例）\u003c/strong>\u003c/p>\u003cp>任静扮演小张、欧思衡扮演沃尔霍森\u003c/p>\u003cp>小张：沃老师，我最近有个困惑、焦虑，我一直都比较爱学习开看书，我想利用每天坐地铁上下班来看一些书，但是我不知道怎样去促进我这个行动，所以想向您请教一下。\u003c/p>\u003cp>沃尔霍森：你说你想在坐地铁上下班的时候看一些书，那么“一些书”这个目标是不是太宽泛了，可不可以把它量化一下呢？比如说，你想看多少本书？\u003c/p>\u003cp>小张：今年差不多还剩下10个月的时间，我想在这10个月里看完10本书，一个月一本。\u003c/p>\u003cp>沃尔霍森：好，我们现在定的目标是10本书，那么我们来看看你要多久看完这些书呢？\u003c/p>\u003cp>小张：我想在2023.1.1前读完10本书，现在算下来还有10个月的时间，就是每个月一本书。\u003c/p>\u003cp>沃尔霍森：好，这一年内读完10本书，就是一个月一本。差不多一本书是四百页，那一天要读多少页书是不是可以量化下来？\u003c/p>\u003cp>小张：那这样算下来，一天差不多要读15页左右。\u003c/p>\u003cp>沃尔霍森：好，那你觉得什么程度算是读完呢？是逐字逐句的看完还是理解到大概？\u003c/p>\u003cp>小张：由于我现在还没有掌握很好的读书方法，所以我目前打算逐字逐句去读完。\u003c/p>\u003cp>沃尔霍森：好，我们刚听你说，你每天要坐地铁上下班。那我们在设置触发点地时候就可以把它设置在你坐上地铁那刻开始看书。可以吗？\u003c/p>\u003cp>小张：可以可以。\u003c/p>\u003cp>沃尔霍森：为了促进行动，我们现在来设置一个“如果…就…”的句式，来你尝试一下呢？\u003c/p>\u003cp>小张：“如果…就…”的句式，触点是上下班坐地铁。那么就是：如果我上下班坐上地铁，我就读15页书。\u003c/p>\u003cp>沃尔霍森：那我们现在是不是就是将你想要在上下班坐地铁看书落实成一个行动了。\u003c/p>\u003cp>小张：对，对。谢谢老师，我明白了。\u003c/p>\u003cp>沃尔霍森：好，好，不客气，再见。\u003c/p>\u003cp>感谢小伙伴们的分享。\u003c/p>\u003cp>我们再来回顾一下，刚刚小张说了，想在坐地铁上下班途中读一些书。首先第一步，量化目标。“一些书”是多少书呢，10本还是20本。刚刚小张同学说了，要读完10本书。这就是量化目标。第二步，优化内容。我们需要设置时间期限以及要做到什么样的程度算是达成目标。刚刚小张说了，要在2023.1.1之前，就是未来这10个月内看完10本书。那要看到什么程度呢？刚刚小张说了，他要逐字逐句地读算是读完。第三步，设置触点。将上下班坐上地铁作为这个行为的触发点。第四步，催化行动，我们设置一个“如果…就…”的句式，触点是上下班坐地铁，那么就是：如果上下班坐上地铁，我就读15页书。\u003c/p>\u003cp>我们在平时或多或少都有些因为拖沓而没有实现的目标，希望在未来的日子里，大家能运用今天学到的方法，促进目标达成！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1647778974000,"updated_at":1647839916000,"ria":true},{"id":11805,"topic":"成功，动机与目标","learn_goal":"","remark":"成功，动机与目标","level":"TF2-3","duration":30,"status":30,"type":0,"chaishujia":{"username":"shanhua","city":"宁波市"},"club":{"name":"宁波幸福虚度分舵","city":"宁波"},"prologue":"\u003cp>大家好。我是山花。本次拆书的目标是：通过识别-----满足人类对“关联感”、“胜任力”、“自主权”这三种基本需求的目标，带来我们想要的快乐和幸福。\u003cbr>\u003cstrong>F:\u003c/strong> 作者是海蒂·格兰特·沃尔霍森，她是美国哥伦比亚大学心理学博士。\u003cbr> 全书根据个人核心价值观确立目标、指导行动落地（如锻炼自制肌）、行为激励准则等诠释如何获取成功；\u003cbr> \u003cstrong>A:从人类底层需求出发，就打磨、提炼、确立正确的目标，相比于其他励志类的，人物传记类的书，具有更贴进平民、让“不闪光的金子”也能找到目标，生命的意义。\u003c/strong>\u003cbr> \u003cbr> \u003cstrong>B:\u003c/strong> 帮助防御型人士，将目标转化为自在动力的目标，获得幸福感；\u003cbr> 对于好立目标的进攻型人士而言，摒弃“关于自我价值感外在肯定的目标”。\u003cbr> \u003c/p>\u003cp>通过自驱式目标的建立，本书可以帮助我们找到“正确的”，可以帮助自己建立 正确的目标。\u003c/p>","ratings_count":3,"texts":[{"id":15748,"quote":"\u003cp> 我之前提过，不是所有的目标都能带来持久而真实的满足感和幸福感，因为并不是所有目标都能满足我们对\u003cstrong>关联感、胜任力以及自主权\u003c/strong>的需求的。哪些目标才能满足这些需求呢？总的来说，关于建立、支持和增强人际关系的目标可以，专注于发展自我、增强体魄以及自我接受的目标也可以（自我接受是指正视缺点，即便无法改善也需懂得）,那些有关回报社会以及帮助他人的目标也同样可以。\u003cbr> \u003c/p>","explains":"\u003cp>\u003cstrong>What:\u003c/strong>当那些未与自身产生关联，与经验获取能力成长无关的目标确立出来时，到底目标是否可能带来实现，给你带来幸福感。 我们今天来探讨下这些。\u003c/p>\u003cp>\u003cstrong>How\u003c/strong>:怎么做，可以让我们目标可实现，带来幸福感呢？\u003c/p>\u003cp>1）关联感 当你追求的目标是建立或巩固人际关系以回报社会时，你对关联感的需求会得到满足。\u003cu>即建立或巩固人际关系，有助于产生关联的目标\u003c/u>。\u003c/p>\u003cp>如：确立的目标要大声说出来，也是获得一种关联感，说出来时，即意味着期待获得周围人的监督。\u003c/p>\u003cp>【细化步骤】：1、\u003cstrong>自己选择目标\u003c/strong>。最强的动机和最大的满足感来自\u003cstrong>自己选择\u003c/strong>的目标。\u003c/p>\u003cp> 2、\u003cstrong>做目标的主人\u003c/strong>。当我们为\u003cstrong>自己做主\u003c/strong>时，内在动力会进一步增强。\u003c/p>\u003cp> 3、\u003cstrong>给奖励\u003c/strong>。意外的奖励和不与表现相关的奖励都是有效的。\u003c/p>\u003cp> 2）胜任力 \u003cu>核对目标是否与个人成长、从经验中学习及开发新技能有关\u003c/u>。\u003c/p>\u003cp>为了满足胜任力的需求，你追求的目标应与个人成长、从经验中学习以及开发新技能有关。如确立的目标，与个人成长有关，但不符合\u003cstrong>从验验中学习和开发新技能，\u003c/strong>可能目标会带来失败。比如HR 6环节与知识产权工作相关少，确立2020年获取知识产权代理资格这个目标，此即为考试未获得通过的原因之一.\u003c/p>\u003cp>3）自主权 \u003cu>确认：追求符合兴趣爱好，个人天性以及核心价值的目标能满足你对自主权的需求\u003c/u>。 每个人的价值观不太一样。如你在考虑孩子报考义务阶段教育报名时，就意向学校，不在学区房范围，你是先找关系，还是选择摇号等录取结果 ？倾听自己的需要在这个繁华、喧嚣的时代显得很奢侈。\u003c/p>\u003cp>\u003cstrong>Why\u003c/strong>【\u003cstrong>不这么做的坏处\u003c/strong>】： 很多家长在与孩子一起定学习目标、健身目标时，容易从家长自身的好处出发，和孩子沟通。这样往往会显得生硬，不易被孩子接受。原因就在于没有让孩子与自己的需求、关联感、胜任力联系起来。 \u003cbr> \u003c/p>","interaction":"\u003cp> A3 你是一家公司人力资源经理，因组织架构内部人员紧缺，你手头上有合同到期不续签的纠纷事宜、年度薪酬事宜需要往现有人员上进行分派任务。\u003cbr> a员工做事干练，性格外向，达成率高，对于基础模块熟悉；b员工刚来，还不太清楚能力水平。\u003cbr> \u003cstrong>您可以安排与其中1~2位员工面谈后，把任务往下派发\u003c/strong>。请在面谈前，做以下考虑，如何通过谈话了解员工的胜任力，如何了解员工的底层需求，核心价值观；请开始。\u003cbr> A2 有请其中一组来演绎一下。\u003c/p>\u003cp> 学伴甲（扮演经理，以下简称甲）：你好，**。本季度性任务较重，因新员工未到岗，你看一下，根据合同到期，不续签和年度薪酬设计，这两块，你根据自己的情况，认为有哪个可以接手，暂时缓解下部门压力吗？\u003c/p>\u003cp> 学伴乙（扮演老员工）：部门有压力，我很理解，也愿意接活。但是领导其他合适时间是否也考虑我们的奖励、激励这块。\u003c/p>\u003cp>什么脏活、累活都是老员工干的话，还有其他新人什么事啊。\u003c/p>\u003cp> 甲：我想你愿意主动承担困难性任务的工作，也是把自己往高标准在要求的。对自己有要求的员工，我当然都有看到。另外，你对于缺人手的这几份工作，以前是否有处理过呢？合同续签、年度薪酬，你对哪个模块更熟悉些？\u003c/p>\u003cp> 乙：我在前几年有接触过合同到期的协商谈话，也起草过几个协议。认为相对还是熟悉些的。可以着手这一块的工作。\u003c/p>\u003cp> 甲：你这样说，我就放心啦。等新员工到岗，可能也免不了需要带一段时间，但是后面会转移、交接给新人的。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1624545747000,"updated_at":1627219200000,"ria":true},{"id":11089,"topic":"学会做计划","learn_goal":"","remark":"使用四个步骤学会建立计划，并用如果...就形成计划的动作记忆","level":"TF1-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"shanhua","city":"宁波市"},"club":{"name":"宁波幸福虚度分舵","city":"宁波"},"prologue":"\u003cp>一、自我介绍\u003c/p>\u003cp>大家好，我是山花烂漫。就是给点阳光就灿烂的那颗野生土长的花。我目前在企业里任HR一职，是企业培训负责人。\u003c/p>\u003cp>二、拆书帮介绍\u003c/p>\u003cp>拆书帮是将一群有志向于通过学习、获取知识，并将知识、工具应用后通过拆书演练，分享给其他人。拆书的拆不是拆散，不是教你去精炼一本书的内容，而是转化和内化。拆书就是用RIA标签，把图书的知识拆页转化为学习者的能力。而内化即时将知识通过验证实践，形成具有客观价值的认知体系。\u003c/p>","ratings_count":2,"texts":[{"id":15010,"quote":"\u003cp>片段一（P166）：学业能力的倾向测验\u003c/p>\u003cp>这个试验是在出名的缺乏纪律和自制力的人群中进行的----正在放暑假的十年级学生。\u003c/p>\u003cp>这些学生在即将开始的学期里面对“学业能力倾向初步测试”（PSAT）的考验，而他们每个人的目标都是在暑假里为测验做准备。9月份，将答卷收回来时发现，那些做了时间、地点计划的学生平均完成的题量是未做计划的2.5倍。\u003c/p>\u003cp>片段二（P170）：养成：“如果…就…”速成习惯的建立-----建立“自动化程式”。\u003c/p>\u003cp>“如果…就…”实际上是把适合你个人的场景调用到你的具体计划中，比如学生时代，我们对于眼保健操的作用都不甚了了。当广播声响起时，我们经常偷眼看其他同学，以方便在一些动作上躺懒。但是成人了，我们知道那个戴眼镜的苦恼时，我们知道现在再来做些保持视力的习惯仍然重要。那么计划来了：“如果完成一项案头的工作，我们就起身滴眼药水，眯眼3分钟。然后看下窗外的绿色。”\u003c/p>\u003cp>① 制定计划\u003c/p>\u003cp>② 决定具体行动\u003c/p>\u003cp>③ 整理“如果┈就┈”计划\u003c/p>\u003cp>④ 瞄准障碍\u003c/p>","explains":"\u003cp>四、I便笺\u003c/p>\u003cp>原书的可提炼的工具为以下步骤实现：\u003c/p>\u003cp>① 制定计划\u003c/p>\u003cp>② 决定具体行动\u003c/p>\u003cp>③ 整理“如果┈就┈”计划\u003c/p>\u003cp>④ 瞄准障碍\u003c/p>\u003cp>Why\u003c/p>\u003cp>做什么事情如果能将最终的目的看清楚，那么做事情才会是有的放矢的。当目标没有结合个人实现计划的具体场合、时间，就有可能执行下去。\u003c/p>\u003cp>How\u003c/p>\u003cp>1）制定计划。当制定计划时，我们除了写下具体行动，采用SMART的原则，具体的、可衡量的、相关的、可实现的、有时间限制的。\u003c/p>\u003cp>2）决定具体行动。比如你希望挽回物件丢失的损失，你可能需要独自上山将丢失的玩具、衣物寻回。具体行动包括你确认上下车的行程、时间、需要带上的照明工具或一起壮胆的同伴等。\u003c/p>\u003cp>3）并整理出“如果┈就┈”计划，就能让事情看起来都能贴近目标。如同是在寻找一个触发动作执行的条件、开关。就像老鼠听铃外出觅食那样，只要我们大脑确认了执行动作的场景就容易形成潜意识的记忆。即一旦要实现社交计划，我就制定“如果周末有空，我就邀请同事打球”；假如制定培训反馈计划，我就写下来，“如果调查问卷完成，我将收回所有主观反馈的评价，一一回复。”；\u003c/p>\u003cp>4）瞄准障碍。\u003c/p>\u003cp>即事先识别计划执行过程中，会导致失败的因素。比如，培训反馈有时，学员主观性偏高，与培训组织的主旨相违背。则需要将培训的初衷再做宣传等。\u003c/p>\u003cp>如学员的反馈回收比率偏低，可能在活动组织方面尚有值得改进的方面。这主观性偏高、反馈回收率偏低，只能侧面反映培训意见不能统统收集的障碍，即指培训组织再提高的障碍。采用“如果培训中多使用互动，我们就能更清晰知道学员的需求。”“如果培训一结束就将调查问卷的二维码发给大家，则回收率就更高。”\u003c/p>\u003cp>Where 我们可以结合自己的计划执行的场景应用以上四个步骤，确保将个人的短期、长期目标执行下去。\u003c/p>","interaction":"\u003cp>五、A1便笺\u003c/p>\u003cp>我2020年制定了一个计划。考知识产权代理师。制定了一套具体的行动计划。在临近考试10个月以上的时间里，将1万字/本的书看上2遍，做近几年的习题等。3,4两个步骤就没有在我的计划里出现过。临考前一天，看书时间也已经超过了10小时。平常时间，2小时左右。\u003c/p>\u003cp>但是当我没有意识到自制肌失效时，学习的确是失效了。56分/门课程可以过关，我考了33分这样。\u003c/p>\u003cp>我的反思即是：我忽略了障碍。那么\u003cstrong>障碍1\u003c/strong>就是，科班出身的人应考，对于相关法中10种以上的法律细则有做了解和解读。我所有的时间用在3本应考为主的教材中；这个障碍需要依靠更多的时间去看书补足。\u003cstrong>障碍2\u003c/strong>即是，我考人资2时有一班线上的学生可以与讲师实时互动。此次考试，听的都是录播课程，实地线下课程4天因为10月中旬工作的原因无法安排就应考了。那么改进2021年确认好知识产权代理人的考试势必拿下的决心后，创建的执行开关1是：“如果周围的圈子缺少相关法的讨论话题，就去搜索相关法朋友群，参加他们的讨论。”创建的执行开关2，“专利法的实务环节，如果写专利文案已经有标准的制程，就需要加入线下的4天课程，请类似拆书家一样的老师手把手教。”\u003c/p>\u003cp>六、A2便笺\u003c/p>\u003cp>目标：2021年6月前，形成适用于HAPE公司的、适用的培训师等级评定制度。\u003cbr>规划行动：制定计划：对吉利、网上公开的培训师评级制度进行分析、研究。考虑与我司的异同。\u003cbr>决定具体体行动：1、吉利讲师评定的规则、讲师评定的标准、评委的来源等。2、2020年做过北仑周边非汽配行业的调研，未形成培训师制度。可以参考汽配行业、培训行业的制度。\u003cbr>整理如果就计划。2020年新开发课程1门以上的讲师存在8位以上，其中前三位是内训讲师，开课已经到达平均8小时/年。其他几位是开分享课的讲师。前三位讲师，通过制度和IDP需要，重新开课程的可能性是存在的。如果内部有新开课的需要，就会给内部讲师新编课程的机会。如果内部新开课程是按需要而激励大家成为中、高级、资深讲师，那么就制度就是按需设立了。\u003cbr>瞄准障碍。1、讲师领新课开发的机会，可能受讲师个人的知识水平、讲师的工作范围限制，新开课程无法机会均等。通过讲师\u003cu>评级制度足够地激励讲师去发掘自己的未知领域、并运用工作实践，将知识融会贯通\u003c/u>。\u003cbr>\u003c/p>\u003cp>2、\u003cu>通过个人的嗅觉感受到新开课程的可能性\u003c/u>。在制度中让讲师看到开发课程实际意义。如个人演讲水平的锻炼等。未来可能需要新课程的方向为：\u003cstrong>项目管理在工作中的应用、质量分析工具在工作中的应用、活动文案如何写吸引眼球、产品陈列课程\u003c/strong>如何适应各种商超、百货、潮流店的货架、地堆；还要通过制度再激励开发其他可能被需求，但未明确提出来的人群。3、在现有讲师队伍不足以被新制度激励到，或者课程开发受阻时，\u003cu>需要向现有讲师外部发掘更多的其他讲师\u003c/u>。则，需要让那部份潜在讲师，也能在2021年初也加入到TTT培训项目中，以提供他们的成长先决条件。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1614340280000,"updated_at":1620829036000,"ria":true},{"id":10858,"topic":"相同目标不同阶段的策略","learn_goal":"","remark":"学会定目标，成功无上限，没有达不成的目标，只有不合适的目标。","level":"TF3-3","duration":80,"status":30,"type":0,"chaishujia":{"username":"天一","city":"绍兴"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>大家好，我是天一，天天进步，知行合一。我是一个财富管理师，房产投资教练，我今天拆书内容来自于《成功，动机与目标》这本书。\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>\u003c/p>\u003cp>为了让大家的学习效果更好，我们先分个小组\u003c/p>\u003cp>\u003cstrong>【总目标】\u003c/strong>通过现场RIA的学习，学习者能够识别出进步目标，并且在达成目标遇到困难时，运用转换四步法把“表现”目标转变成“进步”目标。\u003c/p>\u003cp>【图书介绍】\u003c/p>\u003cp>日子过的真快，现在已经是12月份，回想一下年初定的目标，2020年要成为百万粉丝的网红，要自考本科毕业，一周拆一本书，这些目标，当初定的是时候雄心勃勃，相信自己一定可以做到，可现在，悄咪咪的没了声响.\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>\u003c/p>\u003cp>你们有没有类似的场景？起初定目标时是自己想要，也很认真的去做，可最后夭折了。\u003c/p>\u003cp>学习者：有\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>\u003c/p>\u003cp>一次两次就算了，可是年年定目标 ，年年没有达成，时间久了，不要说别人，自己心里都在打鼓，是不是我能力不行呀？是不是我不够聪明呀？开始怀疑自己，很焦虑，工作和事业停滞不前，做事情也提不起精神。\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>\u003c/p>\u003cp>这些状况能否解决呢？如何才能够更有效的达成目标？《成功，动机与目标》这本书给出了答案。没有达不成的目标，只有不合适的目标，什么阶段定什么样的目标，不同阶段的目标的策略应该如何制定，如何在遇到困难时灵活转换目标，这也是我们今天需要拆解的内容。\u003c/p>\u003cp>如何提升目标的达成率？首先我们需要了解自己定的是什么目标？有哪些特征，这是我们第一片段的内容。\u003c/p>","ratings_count":1,"texts":[{"id":14747,"quote":"\u003cp>\u003cstrong>【片段一目标】\u003c/strong>\u003c/p>\u003cp>通过现场RIA的学习，学习者能够列出（动作）自己的目标，并且通过三步法识别（澄清）出“进步”目标（界定）\u003c/p>\u003cp>现在请伙伴们看一下我发下去的拆页，时间是两分钟，可以划下关键词。看完的伙伴可以示意我一下\u003c/p>\u003cp>\u003cstrong>R原文片段：\u003c/strong>\u003c/p>\u003cp>心理学家把发展或增强某种技术和能力的意愿称作“精熟目标”。当人们在追求精熟目标时，他们不因是否达到特定结果而评断自己——比如成绩全A或超越销售目标。取而代之，他们用“进步”来评断自己。我有进步吗?我在学东西吗?我前进的速度适当吗?\u003cstrong>重点不是一次的表现，而是长期表现。\u003c/strong>这种目标是以完全不同的方式与自我价值关联起来的，因为它们着重于自我提升而不是自我肯定。这种目标关系到你是否做出了最大努力，\u003cstrong>成为最好最有能力的自己，而不是证明你已经是最好的了\u003c/strong>。\u003c/p>\u003cp>当我们追求精熟目标(“进步”)时，我们比较不会因为困难和差强人意的成绩而埋怨自己缺乏能力，因为这样做根本没有道理。我当然目前缺乏能力了一一我还没掌握它啊!我们会找更可控的原因。我学习够下功去吗?我是否应该换个战略?我是否应该找个高手请教一下?当人们在追求\u003cstrong>“进步\u003c/strong>”的路上遇到困难时，他们不会像追求\u003cstrong>“表现”\u003c/strong>的人那样沮丧和无助，他们\u003cstrong>会做出行动。他们问自己哪里出了错然后去修复\u003c/strong>。如果我的第一个考试只得了C，我会用双倍的时间并且换一种方式学习，比如用记忆卡或自己列大纲。如果我没有达到销售目标，我会认真向公司中资深的销售人员讨教。如果我的邻居对我不感兴趣，我会想想如何吸引他的注意并增强相互的了解。如果我第一次没有考进法学院，我会向法学院教授或招生办公室咨询意见，看看在重考时如何让自己更有竞争力。“进步”目标有时能带来最大的成就，因为把注意力集中在“进步”上的人很少会过早放弃。\u003c/p>\u003cp>心理学家在研究学习中一次又一次地发现追求“表现”的绩效目标和追求“进步”的精熟目标能带给人截然不同的面貌、感受和行为。\u003c/p>","explains":"\u003cp>\u003cstrong>【I】拆书家讲解引导】\u003c/strong>\u003c/p>\u003cp>我看大部分的伙伴已经阅读完了，接下来我们一同来解读下这个片段。\u003c/p>\u003cp>【简短互动】\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>请大家回答我，在片段一中我们看到了目标的哪两种类型？\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>精熟目标，进步目标，绩效目标、\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>是的，一种是追求表现，关注结果的目标是“绩效目标”，也称为表现目标，一种是追求进步，关注提升能力和技能的是”精熟目标“，也称为进步目标，为了便于理解和记忆，我们把他称为“表现”目标和“进步”目标。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>进步目标和表现目标没有好坏之分，进步目标用在对自己有难度，有挑战的时候，进步目标可以更好帮助达成你想要的结果，如果没有进步目标的出现，很多时候，对自己有挑战的目标，就很容易半途而废。\u003c/p>\u003cp>\u003cstrong>【强化概念，对比说明】+【简短互动】\u003c/strong>\u003c/p>\u003cp>我来说几个场景大家来区分下是什么目标\u003c/p>\u003cp>场景一\u003c/p>\u003cp>拆书家：慧慧学习很努力，成绩在班上名列前茅。她的目标是在班里保持前三，一直以来考试都能如愿，这次考试失误掉到了第9名，她觉得自己学习退步了，能力不行，这是什么目标？\u003c/p>\u003cp>学习者：\u003c/p>\u003cp>拆书家：是的，进步目标不是看一次的表现，而是长期的表现\u003cstrong>（关键点一）\u003c/strong>\u003c/p>\u003cp>场景二\u003c/p>\u003cp>拆书家：小王是一家医药公司的王牌销售，业绩一直遥遥领先，他的目标一直是销售冠军，三个月前公司新进了一个北大的高才生，三个月就超过了他。把它从销冠的位置拉了下来，小王觉得特别没有面子。小王是什么目标？\u003c/p>\u003cp>学习者：\u003c/p>\u003cp>拆书家:是的，进步目标不是证明自己是多么的厉害，而是在乎自我成长\u003cstrong>（关键点二）。\u003c/strong>比如：小王想，虽然这次没有成为销售冠军，但积累了新的客户资源，在新来的高才生那里学到了新的销售经验，思维和认知上也有了提升，小王的目标就成为进步目标。因为他在乎的不是自己多厉害，而是自我成长。\u003c/p>\u003cp>场景三\u003c/p>\u003cp>去年我的目标是6个月成为三级拆书家，去年年底最后一关没有过完，今年因为疫情，停了6个月，后面觉得3-3难度太大，一直往后拖，一动不动，这时候，我是什么目标？\u003c/p>\u003cp>学习者：\u003c/p>\u003cp>拆书家：是的，因为觉得难，就一直拖，也不去行动，是表现目标，一个月前，我想，我不能再这么继续下去了，我能做点什么？于是早上五点钟起来写预备表，去看其他拆书家的优秀实录，写写写，改改改，我又开始行动了，这时候，我是什么目标？\u003c/p>\u003cp>学习者：\u003c/p>\u003cp>拆书家:是的，这也是进步目标的\u003cstrong>第三个关键点\u003c/strong>，积极思考，持续行动。\u003c/p>\u003cp>关于进步目标的三个关键点。我们来看这张图。\u003c/p>\u003cp>见图示\u003c/p>\u003cp>进步目标（三个关键是长期，自我成长，积极思考，持续行动，先有表现目标，如果遇到障碍了，再有进步目标，进步目标是实现表现目标想要结果的迂回战术，是为了更好的达成，它们之间是互相关联的。\u003c/p>\u003cp>【难点和重点】\u003c/p>\u003cp>进步目标的重点是脚踏实地的去行动，难点是不管什么目标，都应该明确可衡量。这是容易被大家忽略的问题。\u003c/p>\u003cp>\u003cstrong>【正例】：\u003c/strong>三个月前，我想养成早起的习惯，闺蜜说\u003cstrong>，\u003c/strong>这不是件容易的事情，后面还跟了一堆的问题，这么早你起来干嘛？你为什么要早起？你天天都起得来吗？如果你想偷懒怎么办？\u003c/p>\u003cp>我说，是的，我知道养成一个习惯不容易，就算偶而一次没有起来没有关系，我是长期打算的。（长期）我早上五点起来可以看书，写稿等，提升自己的输出能力（自我成长）。如果有段时间特别想偷懒，我就把闹钟放到手够不着的地方，不起床就一直在那响，也请家人监督我，这样就不得不起来了（积极思考，持续行动），等时间久了，早起是自然而然的事了。\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>\u003c/p>\u003cp>知道了什么是进步目标？该如何识别呢？我们把如何识别进步目标定为以下三个步骤\u003c/p>\u003cp>\u003cstrong>1.列出目标\u003c/strong>\u003c/p>\u003cp>列出自己想要的是什么？\u003c/p>\u003cp>\u003cstrong>2.辨别特征\u003c/strong>\u003c/p>\u003cp>和上面关于进步目标的三个关键点一一去对应\u003c/p>\u003cp>\u003cstrong>3.确认目标\u003c/strong>\u003c/p>\u003cp>如果三个都符合就属于进步目标。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>可能伙伴会问，一定要三个关键点都符合才是进步目标吗？是的，尽量全部符合，但它们之间的顺序是可以调整的。\u003c/p>\u003cp>可能伙伴们又会问，既然目标没有好坏之分，为什么要识别进步目标呢？识别的意义是什么？通常来说，一些大的成就都不是一蹴而就的，需要有积极的心态，长期持续才能够达成，相同的目标，在不同的时段需要不同的策略，这样才可以提升目标的达成率！\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>进步目标适合有难度，有挑战，需要长期持续才能够完成时，如果相对简单，快速要出结果的是不合适的。\u003c/p>\u003cp>第一个片段的讲解就到这里。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A学习者拆为己用：编剧本】\u003c/strong>\u003c/p>\u003cp>我们知道学到不等于做到，那么如何从知道到做到呢，我们可以用一个方法来现场练习，这个方法就是编剧本。\u003c/p>\u003cp>\u003cstrong>【A2】催化应用\u003c/strong>\u003c/p>\u003cp>大家可以设想一下，现在已经是年底了，未来一周或者是一个月内，你会设定一个什么样的进步目标？可以是学习上的，职业晋升上的，或者是改善关系方面都可以。\u003c/p>\u003cp>【指令】：\u003c/p>\u003cp>我们以编剧本的形式来呈现\u003c/p>\u003cp>剧本要有故事六要素（时间，地点，人物，情节，经过和结果）时间（一定是未来），一定要有人物对话，如果不知道怎么编写的，我给大家的范本可以看下，（时间是3分钟）\u003c/p>\u003cp>不需要小组讨论，自己单独完成，等一下会请一个小伙伴分享下。\u003c/p>\u003cp>学习者分享\u003c/p>\u003cp>时间：年底\u003c/p>\u003cp>地点：家里\u003c/p>\u003cp>人物：闺蜜和我\u003c/p>\u003cp>闺蜜：年底了，胖了好多，天气太冷了，怎么办？(想要的结果：减肥保持体重）\u003c/p>\u003cp>我：是的，我也是呀要不动起来吧？\u003c/p>\u003cp>闺蜜：风那么大，我懒得动，健身房我也懒得去\u003c/p>\u003cp>我：我们可以试试室内的一些运动？比如跳绳\u003c/p>\u003cp>闺蜜：跳绳可以，跳绳比较简单，那一天要跳多少个？\u003c/p>\u003cp>我：刚开始我们可以先跳1000个，每天增加200个，\u003c/p>\u003cp>闺蜜：可以的，不过好像一天1000个还达不到减脂的效果，\u003c/p>\u003cp>我：那我们试试看加到3000-5000个？\u003c/p>\u003cp>闺蜜：怎么加呢？一下子加上去也不可能，定个目标吧\u003c/p>\u003cp>我：（目标）定每天加200个，一直加到3000-5000个\u003c/p>\u003cp>闺蜜：那如果我们不想动的话是不是就失败了？\u003c/p>\u003cp>我：并不一定要每天，每个星期打5天卡，2天休息\u003c/p>\u003cp>闺蜜：万一有人没有达到规定怎么办？\u003c/p>\u003cp>我：互相给对方买个小礼物，以示惩罚，下周再继续开始。\u003c/p>\u003cp>最后确定：每周5次跳绳，先跳1000个，慢慢加到3000-5000个，如果有没有做到的，就互相买小礼物，以示惩罚，下周再继续。一直稳定在3000-5000个，直到达到保持体型的效果。\u003c/p>\u003cp>【拆书家反馈+简短互动】\u003c/p>\u003cp>拆书家：谢谢汪恩伙伴的分享，来看下这三个关键点是否对应。首先你的目标是？\u003c/p>\u003cp>学习者：减肥（其实是想要的结果），目标是每天跳绳3000-5000个。\u003c/p>\u003cp>拆书家：特征我们来辨别下，减肥通过什么来实现，跳绳。如果有一天没有跳怎么办？没有关系一周五次就好。（不在乎一次的失败，长期）如果体重稳定，可以让自己心情愉悦，心智成熟（自我成长）如果遇到了困难，已经想好了对策，还有数据量化（积极思考，持续行动）。从1000个开始做起，慢慢增加，脚踏实地去做，看的出是进步目标\u003c/p>\u003cp>学习者：是的\u003c/p>\u003cp>拆书家：把热烈的掌声送给她。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":14748,"quote":"\u003cp>【过渡】\u003c/p>\u003cp>不以结果为目标的行为都是自嗨，只在乎结果，不在乎过程，大多数的人会卡壳在过程，导致进行不下去，当你定的目标过大，是表现目标的时候，我们需要改变策略，把表现目标转换成进步目标，如何转换？来到我们的第二片段。\u003c/p>\u003cp>\u003cstrong>【R原文片段：】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【片段2的学习目标】：\u003c/strong>\u003c/p>\u003cp>通过片段二的学习，学习者能够在达成目标遇到困难时，运用转换4步骤，把表现目标转换成进步目标。\u003c/p>\u003cp>\u003cstrong>【A1请大家自测】\u003c/strong>\u003c/p>\u003cp>在拆解第二片段前，我们先来做个自测题\u003c/p>\u003chr>\u003cp>\u003cstrong>【I解释自测题】（2分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【互动】\u003c/strong>\u003c/p>\u003cp>26分以上的请举手，有一个\u003c/p>\u003cp>11分以下的请举手，没有\u003c/p>\u003cp>剩下的都是在这个中间分值的。\u003c/p>\u003cp>\u003cstrong>自测题解释：\u003c/strong>\u003c/p>\u003cp>26分以上的，说明你在目标方面比较坚定，善于变通，目标的达成率会比较高，对于复杂且长期的目标，达成过程中，遇到困难时可以很好的应对。恭喜你，掌声。\u003c/p>\u003cp>11分以下的，说明你平常的目标达成率时有很大的提升空间。在场的伙伴一个都没有。\u003c/p>\u003cp>而我们大多数人是在11-26分之间，这很正常，我也是，希望今天的拆书可以大家带来收获，未来可以更好的达成你想要的结果。\u003c/p>\u003cp>我看到有伙伴有25分，分值也很高，相信你平常的目标达成率也是比较高的，做个说明，不要太在意这个分数，它不代表权威，只是个工具，用来自测摸底。\u003c/p>\u003cp>接下来，我想邀请大家用2分钟的时间，阅读手中的片段：\u003c/p>\u003cp>当我的第一个孩子，女儿安妮卡出生时，我第一次做家长的目标绝对都是“表现”型的。当然我读了很多育儿经，看了很多育儿节目、作为心理学家，我本身也懂得“依附理论”，懂得要积极回应孩子发出的信息。\u003cstrong>我本来想获得“世界上最伟大的母亲”的称号\u003c/strong>，我把前前后后上上下下都处理得完美无瑕。哈，我原以为如此。现实是如何给了我当头一棒啊!从一开始，安妮卡就被家人称作：“多事宝贝”(貌似现在产生了一种更官方更正确的叫法:高需求宝宝）。她从出生到18个月大的这段时间里，除了吃饭、睡觉(不常)以外都在尖叫。\u003cstrong>因为我太想当“世界上最伟大的母亲”了，我把她的种种需求和过激反应都当作我身为母亲无能和失败的体现\u003c/strong>。\u003cstrong>我什么都怪自己。我每天的心情在焦虑与抑郁中跌宕起伏。\u003c/strong>我梦到自己钻进车里踩足油门冲出悬崖，然后融入夕阳.......从所有的混乱与对自身能力的怀疑中解脱。\u003c/p>\u003cp>之后，让人欣慰的事发生了。就在绝望的边缘，我蜷在卫生间的角落里\u003cstrong>诚实地面对自己，\u003c/strong>我发现我完全搞错了，因为我的目标从头到尾都是错的。(令人非常尴尬的是，心理学家遇到自己的问题时有可能反应非常愚钝。)\u003cstrong>根本没有完美家长这一说\u003c/strong>。相信可以在摸索中把每件事做对，完全征服当家长这个挑战是愚蠢的想法。每个孩子都不同，在你迎接一个新生命降生时，你根本无法期待需要面对的事。\u003c/p>\u003cp>所以我振作起来了。我\u003cstrong>接受\u003c/strong>了我不是什么都懂，也不可能什么都做对的\u003cstrong>事实\u003c/strong>。我把我的\u003cstrong>目标从“表现”转变为“进步\u003c/strong>”。我不再想证明我是“世界上最伟大的母亲”，我的目标变成了“在做妈妈这个角色中\u003cstrong>不断进步\u003c/strong>”，并\u003cstrong>试着学习具体问题所需的技巧和耐心\u003c/strong>。随着不断地学习，我的焦虑和抑郁症状也减轻了。\u003c/p>\u003cp>我觉得跟刚开始比，我是个更好的妈妈了。我确实是更有耐心了每次出现状况时我不再觉得天要塌了。据我丈夫所说，跟我在一起更有趣了。同时我的女儿也从一个极难伺候的婴儿(她的外号叫刺儿头)转变成一个甜美、友善、相对随和的小女孩，我不知道其中有多少是因为我家长目标的改变，抑或这就是正常的儿童成长过程。不论我的转变对她是否有益，都着实改变了我的世界。\u003c/p>","explains":"\u003cp>【\u003cstrong>I拆书家讲解引导】\u003c/strong>\u003c/p>\u003cp>看到伙伴们都已经看完了，进入我们第二个片段的讲解。我们的第二个片段是个案例。\u003c/p>\u003cp>\u003cstrong>【互动精准控场】\u003c/strong>\u003c/p>\u003cp>拆书家:案例中的主人公刚开始是什么目标？\u003c/p>\u003cp>学习者:表现目标\u003c/p>\u003cp>拆书家：当时她的情绪是什么样的？\u003c/p>\u003cp>学习者;抑郁，焦虑\u003c/p>\u003cp>拆书家:后来她采取了哪些步骤转换成了进步目标？有哪些关键词？\u003c/p>\u003cp>学习者:接受事实，表现变为进步，学习具体的技能，症状减轻了，\u003c/p>\u003cp>拆书家：是的，做了这些动作以后，症状减轻了。\u003c/p>\u003cp>大家非常有智慧，基本上都找到了相关的关键词，也是我们转换目标的几个行为，反思自己，接纳事实，转换目标，学习行动。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>为什么要进行目标的转换，因为你的目标达成的过程中遇到了拦路虎，原来的策略已经是无效，为了达成目标，我们就需要改变策略，就好比是原先是战略，现在是战术，用新的战术去战胜它，来达到最初想要的结果。新的策略就是转换目标\u003c/p>\u003cp>为了更加清晰如何转换目标，为大家总结了几个步骤\u003c/p>\u003cp>\u003cstrong>【how】\u003c/strong>\u003c/p>\u003cp>第一:觉察自己：一切的根源在自己，静下心来，向内看，自己情绪状态是什么样？感受怎么样？先处理自己的情绪。因为解决问题的顺序是先处理情绪，再处理事情。\u003c/p>\u003cp>第二:接纳事实：当自己安静下来，去看看发生了什么？事实是什么？。事实是妈妈很在乎别人的评价，想获得世界上最伟大的母亲的称号，而事实和理想有差距。看看自己定的目标需要制定什么样的策略？需不需要转换。\u003c/p>\u003cp>第三:转换目标：如果发现自己此刻定的是进步目标，可能是方法和技巧上的问题，只需要改善和调整方法就好，当发现自己是表现目标时，把表现目标转变成进步目标。例：证明我是。。。。。转换成做这些是为了自我的成长和进步。\u003c/p>\u003cp>第四：学习行动：学习和尝试一些新的方法和行动。\u003c/p>\u003cp>当自己的目标达成有困难，发现了自己的行为有偏差，需要问问自己，我能够做些什么？有没有其他可以借鉴的？\u003c/p>\u003cp>【举例】\u003c/p>\u003cp>五六年来，花了很多的时间和金钱出去学习，有一天，突然就想成为演说家，站上舞台。有一次早会上台分享，自我感觉还挺好，老师给的反馈是罗里吧嗦，不讲重点，当时的感受非常不好，情绪低落。回家后，反思自己的问题，太急功近利了，一次的失败不能代表什么，我还是会坚定我的目标（长期），我问自己，我能够做些什么？加入拆书帮，从基础开始，一个技能点一个技能点去刻意练习（学习行动），虽然我现在还没有成为演讲大师，但是我的逻辑思维能力提升了。（自我成长），现在的我，可以自信的站上讲台。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>当你在实施一个长期的有挑战的目标，遇到困难时，及时的把表现目标转换成进步目标非常有必要，也能够帮助你更好的达成结果。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3促动参与】\u003c/strong>\u003c/p>\u003cp>现在请伙伴们回想下，对于目标转换的四个步骤，你们觉得最难的是哪一步？\u003c/p>\u003cp>学习者：第四步学习行动\u003c/p>\u003cp>学习者：第一步觉察自己\u003c/p>\u003cp>拆书家：我们投票一下，觉得学习行动比较难的举手\u003c/p>\u003cp>现场有5个学习者举手，5：1，选择第4步学习行动。\u003c/p>\u003cp>拆书家：是什么样的场景你们会觉得学习行动比较难？能否举个具体的案例？\u003c/p>\u003cp>学习者：我有个案例，学车这件事情，对晕车，我有恐惧，虽然知道，但没有想如何去克服，在执行层面有问题，比如说，要这么去做，我没有去做。\u003c/p>\u003cp>\u003cstrong>【明确问题】\u003c/strong>\u003c/p>\u003cp>拆书家：你的问题是，一件事情很难，怎么去做到是吗？\u003c/p>\u003cp>学习者：对，很难，没有把它去分解，比如你刚刚说的目标，再拖一拖吧！其实是拖延症。\u003c/p>\u003cp>拆书家：那我再确认下，你的问题是不是关于拖延症这个部分？\u003c/p>\u003cp>学习者：是的\u003c/p>\u003cp>拆书家：大家对这个话题感兴趣吗？你们有没有拖延，想不想解决拖延这个问题？\u003c/p>\u003cp>学习者：大家都是有惰性的，感兴趣，全部通过\u003c/p>\u003cp>拆书家：哪我们接下我要讨论的问题就是关于学车拖延如何解决？\u003c/p>\u003cp>\u003cstrong>【问题本质】\u003c/strong>\u003c/p>\u003cp>透过现象看本质，为什么学车会拖延？就得需要知道问题的根本原因是什么？表面看似是拖延，实际有它背后的原因，导致了我们没有行动力，接下来我们要做的是找到学车拖延背后的根源，如何找到问题的根源，我们给的工具是问5个为什么？我给大家做示范，你们来问我来答\u003c/p>\u003cp>拆书家：我想要成为演说家\u003c/p>\u003cp>学习者：为什么你要成为演说家？\u003c/p>\u003cp>拆书家：因为我想站到台上去演讲\u003c/p>\u003cp>学习者：你为什么想站到台上去演讲？\u003c/p>\u003cp>拆书家：因为我想得到别人的认同\u003c/p>\u003cp>学习者：你为什么想要得到大家的认同\u003c/p>\u003cp>拆书家：因为我缺少自信缺少价值感\u003c/p>\u003cp>学习者：为什么你会缺少自信和价值感？\u003c/p>\u003cp>拆书家：因为我站在台上的时候逻辑力不强\u003c/p>\u003cp>学习者：所以问题就在于逻辑力不强\u003c/p>\u003cp>拆书家：所以我根本原因是：逻辑不好，我需要解决的是，如何提升我的逻辑能力？\u003c/p>\u003cp>刚才我只是做个示范，我们来找到彪哥拖延背后真正的原因，请大家小组讨论，按照之前分好的小组，时间是5分钟\u003c/p>\u003cp>学习者问：我们讨论谁的问题？\u003c/p>\u003cp>拆书家：我们以彪哥的问题来讨论，也是大家的问题，因为大家都有拖延是吗？\u003c/p>\u003cp>学习者：是的\u003c/p>\u003cp>拆书家：注意我们只找原因，不讨论解决方案。\u003c/p>\u003cp>时间到，你们讨论出来的根本原因是什么？\u003c/p>\u003cp>小组1：自我期待太高\u003c/p>\u003cp>小组2：没有聚焦在最重要的事情上。\u003c/p>\u003cp>拆书家：现在出来两个根本原因，因为时间关系，我们只讨论一个，你们选一个吧！\u003c/p>\u003cp>同意选期待太高的举手，3个伙伴举手\u003c/p>\u003cp>同意选没有聚焦在最重要的事情上举手，3个伙伴举手\u003c/p>\u003cp>选出来的是3：3，怎么办？学员自发石头剪刀布，3局2胜，最后决定，自我期待太高。\u003c/p>\u003cp>问题本质：自我期待太高\u003c/p>\u003cp>\u003cstrong>【讨论解决方案】\u003c/strong>\u003c/p>\u003cp>拆书家：经过最终的讨论，我们要解决的问题是如何降低自己的期待？大家同意吗？\u003c/p>\u003cp>学习者：同意。\u003c/p>\u003cp>拆书家：现在，请伙伴在小组讨论出解决方案，分为两部分\u003c/p>\u003cp>1.这个问题解决到什么样子你们就满意了？解决目标是什么？\u003c/p>\u003cp>2.把所有能想到的解决方案都列下来，写在便签上\u003c/p>\u003cp>时间是5分钟\u003c/p>\u003cp>小组1：\u003c/p>\u003cp>1，以她人为参照\u003c/p>\u003cp>2，全方位评估自己\u003c/p>\u003cp>3，接纳自己\u003c/p>\u003cp>4，找个人来陪，各自做各自痛苦的事情（学习者自己说这是个好办法，拆书结束后看到两位伙伴已经在约一起陪伴的时间）\u003c/p>\u003cp>拆书家：解决到什么程度就满意了？\u003c/p>\u003cp>学习者：能够带着愉悦的心情，在3天内把感觉最痛苦的事情做完。\u003c/p>\u003cp>拆书家：如果有人一起陪伴你做事，你的心情会愉悦吗？\u003c/p>\u003cp>学习者：是的，我会开心很多，没有那么痛苦。\u003c/p>\u003cp>小组2：\u003c/p>\u003cp>学习者：我们是按照彪哥的实际案例来给出解决方案的，因为我之前有过这样的例子。\u003c/p>\u003cp>1.接纳自己有问题，不完美，不按照别人的节奏。\u003c/p>\u003cp>2.目标分解\u003c/p>\u003cp>我们来归纳和排序下\u003c/p>\u003cp>1，以他人为参照，全方位评估自己\u003c/p>\u003col>\u003cli>接纳自己，不按别人的节奏走。\u003c/li>\u003c/ol>\u003cp>3，目标分解\u003c/p>\u003cp>4.找个人来陪\u003c/p>\u003cp>请问：这个问题解决到现在可以了吗？你觉得这个问题得到解决了吗？\u003c/p>\u003cp>彪哥：就刚刚说的那几点，基本就能够解决我的问题，对目标根清晰了，接下来我也知道怎么做了。\u003c/p>\u003cp>拆书家：其他人觉得对于期待太高，这个问题解决到这里，可以了吗？\u003c/p>\u003cp>学习者：可以了。\u003c/p>\u003cp>谢谢大家的讨论，对解决方案做个说明，或许今天出来的方案，并不能够真正解决你们的问题，我们是用微行动的方式，带着大家去讨论和解决你们觉得难的卡点，希望能够带给大家一些启发和思考的方向。\u003c/p>\u003cp>\u003cstrong>【A2】催化应用】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【布置作业】\u003c/strong>\u003c/p>\u003cp>布置个作业，未来一天或者是几天内，你会和谁去分享我们今天学习的内容，已经临近年关了，你会给自己制定个什么样的目标？如果有遇到障碍，你会如何运用目标转换四步骤，实现目标的转换。你会怎么分享，我希望大家能够交作业给我。\u003c/p>\u003cp>以下是学员交的作业\u003c/p>\u003cp>\u003cstrong>【有力的结尾】：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>谢谢大家的陪伴，你们这么有耐心，我们在一起学习了一个多小时。我们今天分享的内容是，表现目标和进步目标没有好坏之分，了解了什么是进步目标，如何识别进步目标，第二片段我们学习了如何转换目标，也解决了一些相关的问题，希望大家能够把今天所学多多分享出去，多来参与我们的活动。谢谢大家。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>以终为始，不忘初心，持续行动，你的目标都能实现。祝大家心想事成，有美好幸福的人生！\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1608939254000,"updated_at":1608988022000,"ria":true},{"id":10668,"topic":"“如果…就…”的力量","learn_goal":"","remark":"如果制定了目标却执行不了，可能是在执行上方法需要改进。用“如果……就……”的句式，能制定出简单易执行的计划，并且有效，完成度更高。","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"yangzhuanfu","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":"\u003cp>大家晚上好，我是杨转福，一个终身学习者，教练技术践行者，模型思维深度研究者，坚持不可一日不读书，不可一周不跑步，很高兴认识大家。\u003c/p>\u003cp>今天我给大家带来的是《成功，动机与目标》这本书里边的一个片段，希望通过本次现场学习后，大家能够在早起、阅读、健身和减肥等存在行动困难的场景中，运用 “如果……就……”的句式，提高自己行动力和目标完成率。\u003cstrong>（学习目标）\u003c/strong>\u003c/p>\u003cp>下面介绍一下我今天带来的书籍和片段。\u003c/p>\u003cp>\u003cstrong>【F】\u003c/strong>《成功，动机与目标》作者格兰特·霍尔沃森，是美国哥伦比亚大学社会心理学博士，本书的内容来源成百上千篇学术报告，全书分为三个部分：如何制定目标、如何认识目标和如何落实行动。\u003c/p>\u003cp>\u003cstrong>【A】\u003c/strong>本书是研究动机与目标的上乘之作，世界顶级心理学家、斯坦福大学教授卡罗尔·德韦克为其作序推荐。本书最大的特点是操作性强--不需要复杂的理论，简单粗暴的按着作者说的去做，就可以达到很好的效果。\u003c/p>\u003cp>\u003cstrong>【B】\u003c/strong>这本书对我们有什么好处呢？ 如果你经常兴致勃勃地写下月初目标，但又对自己毫无所获地度过一个月感到丧气；如果你对如何制定合理的目标，以及如何有效地执行自己的目标毫无头绪，本书或许可以给你一些启发。\u003c/p>\u003cp>学习这个片段对我们有什么帮助呢？如果你在戒烟、减肥上经常反复，如果你在早起、健身和坚持阅读等方面有行动困难症，如果你工作上经常拖到最后一刻才交付任务，那么学习完本片段，你会提高自己的行动力。\u003c/p>\u003cp>\u003cstrong>分组：\u003c/strong>那么在正式开始前，我们先来分个组。在座的各位，我们以2个人为一个小组，以方便后续的练习。\u003c/p>\u003cp>下面跟随我一起来学习吧。请大家花2分钟的时间阅读我给大家提前准备的原书拆页。\u003c/p>","ratings_count":1,"texts":[{"id":14535,"quote":"\u003cp>\u003cstrong>“如果……就……”的力量\u003c/strong>\u003c/p>\u003cp>这些计划的美好在于简单。你\u003cstrong>找到一个想去实现的目标\u003c/strong>，\u003cstrong>说清达成它的具体时间、地点和方式\u003c/strong>。比如，就拿之前的减肥目标举例。第一步，应该把“少吃”改为“每天摄入热量不超过1500卡路里”；第二步，“多运动”应该变成“每周一、三、五上班前去健身房锻炼一个小时”。戈尔维策把这类计划叫做\u003cstrong>“建立执行意图”\u003c/strong>，听上去挺拗口，实际就是指一种\u003cstrong>“如果……就……”的计划方式\u003c/strong>：如果已经吃了1500卡路里的食物，我就不能再吃了；如果现在是星期一早晨，我就要上班前先去运动。\u003c/p>\u003cp>在听到圣诞作文这个例子的几年后，我有幸与彼得和他的妻子——纽约大学博士后研究员——加布里埃尔·奥丁根一起工作。参与研究的还有宾夕法尼亚大学的安杰拉·达克沃思。我们想\u003cstrong>对“执行意图”进行\u003c/strong>彻底\u003cstrong>测试\u003c/strong>。我们\u003cstrong>用\u003c/strong>了\u003cstrong>出名的缺乏纪律和自制力的人群进行实验\u003c/strong>——正在\u003cstrong>放暑假\u003c/strong>的\u003cstrong>十年级1学生\u003c/strong>。这些学生在即将开始的学期里都将\u003cstrong>面对“学业能力倾向初步测验”（PSAT）2的考验\u003c/strong>，而他们每个人的\u003cstrong>目标\u003c/strong>都\u003cstrong>是在暑假里为测验做准备\u003c/strong>。5月时，我们\u003cstrong>给\u003c/strong>了\u003cstrong>每个学生一本模考题\u003c/strong>——其中有10套题，让他们在暑假中完成，9月份开学时上交。我们\u003cstrong>让一半学生决定了暑假做题的时间和地点\u003c/strong>（比如“平日早餐后，在我的屋子里”)。学生们在暑假期间没有得到任何提醒，那些写下了时间地点的人也把纸片上交了，自己没有留底。9月份我们把习题收回来时发现，\u003cstrong>没有做时间地点计划\u003c/strong>的学生平均\u003cstrong>完成\u003c/strong>了\u003cstrong>100道习题\u003c/strong>，而\u003cstrong>做了计划的\u003c/strong>学生\u003cstrong>平均完成\u003c/strong>了\u003cstrong>250道题\u003c/strong>！我们再次看到了\u003cstrong>成倍的效应\u003c/strong>，尽管过程持续了一整个暑假。而这成效仅仅来自我们的干预实验占用学生的一点点时间。\u003c/p>","explains":"\u003cp>\u003cstrong>【What】\u003c/strong>我看大部分小伙伴都读完了。该片段讲述的是，针对我们想要实现的目标，如何制订简单有效的计划，以完成目标。\u003c/p>\u003cp>\u003cstrong>【Why Not】\u003c/strong>回顾我们过去制定目标的情况，我们常常遇到的困难是：经常无法正确评估实现目标的困难，过于乐观，喜欢思考为什么，可行性这方面考虑不够，于是导致了常常目标定得很漂亮，完成起来极其困难，最终拖延完成或完成不足。\u003c/p>\u003cp>我们实现目标过程中遇到的很多问题，其实都能被简单的“如果……就……”计划解决，安排达到目标所需的时间、地点、方式，可以显著提高成完成目标的概率。\u003c/p>\u003cp>\u003cstrong>【Where】\u003c/strong>这个片段方法适用于实现工作和生活方方面面的长短期目标，但不适用于具有重大的外部或者内部障碍目标。\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>具体我们可以怎么做呢？\u003c/p>\u003cp>\u003cstrong>1.明确目标。\u003c/strong>这个目标是你想要达成的，并且应该是清晰、精确的目标，我们要避免制订模糊不清的目标。拿减肥来举例，“少吃点”“多运动”就是模糊不清的目标，而应该转化为“每天步行一万步”“每天摄入不超过2000大卡能量”。\u003c/p>\u003cp>\u003cstrong>2.决定时间和地点。\u003c/strong>决定做每个步骤的时间和地点。请尽可能做到详细。这可以帮助你的大脑探测并抓住行动时机。这个时间和地点就是行动的触发基准，心理学上说是心锚，只要触发了，就自动采取行动。比如说我一直想养成做仰卧起做的习惯没有养成，我就设定了一个时间地点，如果我晚上躺在床上准备睡觉了，我就做20个仰卧起坐。\u003c/p>\u003cp>\u003cstrong>3.找出可能的障碍。\u003c/strong>这一步在片段里没有体现，是我结合上下文语境补充的。也是非常关键的一步。这个障碍可以是内心的障碍，如一种\u003cstrong>情绪\u003c/strong>，一个并非合理的\u003cstrong>想法\u003c/strong>，或者一个\u003cstrong>坏习惯\u003c/strong>。也可以是外部的障碍、实现目标的外部干扰。\u003c/p>\u003cp>\u003cstrong>4.\u003c/strong> \u003cstrong>整理出“如果……就……”计划。\u003c/strong>设想在预计的时间和地点，或者预想的障碍发生时，你会怎么做。即 \u003c/p>\u003cp>“如果时间X到了/抵达X地点，那么我就采取行动Y”。\u003c/p>\u003cp>“如果障碍X出现了，那么我就采取行动Y”。\u003c/p>\u003cp>举个片段中相关的例子：\u003c/p>\u003cp>现在是放暑假时间，我表妹今年高二，马上进入高三和参加高考了。放暑假前，英语班主任老师要求班上所有同学要在假期内完成10套《五年高考，三年模拟》题，以便在高三的时候取得好成绩。\u003c/p>\u003cp>刚好我和她分享了“如果…就…”计划这个方法，她马上用到了她的学习上。\u003c/p>\u003cp>\u003cstrong>第一步，明确目标。\u003c/strong>要在9月1号开学前，完成10套重庆市2009-2019年的英语高考题 。\u003c/p>\u003cp>\u003cstrong>第二步，决定时间和地点。\u003c/strong>要完成这个目标，今年只有不到1个月假期，每周要做三套左右，每套做题和对答案要做3小时左右。所以做题的时间和地点，可以决定为：每周一三五，下午3:00-6:00，在家里书房做题。\u003c/p>\u003cp>\u003cstrong>第三步，找出可能的障碍。\u003c/strong>仔细想想，最大的障碍可能是朋友约逛街、看电影或者打球等，导致不能完成计划。\u003c/p>\u003cp>\u003cstrong>第四步，整理出“如果……就……”计划。\u003c/strong>可以整理的计划是：\u003c/p>\u003cp>“如果到了每周一三五下午三点，就去书房做英语高考题”\u003c/p>\u003cp>“如果做题时间朋友找我逛街或者玩儿，就和他说改天再约”\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>大家对这个片段的理解有什么困惑没？可能会有小伙伴问，为什么要加上第三步？第三步的障碍有什么限制条件没？第三步是结合上下文语境做的添加，如果没有第三步，第四步的计划范围就会很受限制，我们既需要时间和地点触发我们的行为，也需要提前设想可能遇到的障碍，提前制订行动计划。这里所说的障碍，包括内心和外部环境障碍，但是这些障碍都是可以解决的。如果你找出的是一个超大的障碍，那就把他拆成小的障碍。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3：促动学习者现场演练】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A3】之场景设计\u003c/strong>\u003c/p>\u003cp>我们刚刚学习了用“如果……就……”来制订计划，提高行动力，提高目标的完成率。我们现在一起做一个演练，请大家认真听一下要演练的场景：\u003c/p>\u003cp>小明一直想养成早起的习惯，这样他就可以利用早上的时间来看书和健身了，这个目标对他来说很重要，因为小明觉得只有早上的时间才能掌控自己，早上读书和健身对他一天的状态很重要。小明立了很多次目标，但由于各种原因就是没有长久坚持下来，会出现各种情况导致不能早起，如头天晚上加班太晚、下雨了心情不好、晚上没睡好、想赖床、天气太热或太冷等等，总是有各种原因干扰小明早起目标的实现。\u003c/p>\u003cp>小明找到了自己的好朋友黄老师诉苦，黄老师是目标管理方面的专家，刚好最近也在看《成就，动机与目标》这本书，对书里面的“如果……就……”方法论有很深入的理解和研究。\u003c/p>\u003cp>\u003cstrong>【A3】之小组讨论\u003c/strong>\u003c/p>\u003cp>现在，请每两个人一组，在组内进行演练。一个人扮演小明，早起困扰者，你主动找黄老师寻求建议，说明你遇到的问题或困境，你可以丰富更多细节；一个人扮演黄老师，目标管理专家，你要在听完小明的困扰后，应用今天的学到的“如果…就…”方法，帮他梳理他的目标，提高他的行动力和目标完成率。\u003c/p>\u003cp>演练时间3分钟，现在开始。3分钟后，我会选一位“小明”和一位“黄老师”，大家一起听听他们是怎么应用“如果……就……”方法的。\u003c/p>\u003cp>\u003cstrong>【A3】之角色扮演（现场完整案例）\u003c/strong>\u003c/p>\u003cp>乙（黄老师）：小明好，接下来的几分钟，你最想探讨的话题是什么呢？\u003c/p>\u003cp>甲（小明）：我想养成早起的习惯，把早上的时间用来看书和健身。\u003c/p>\u003cp>乙（黄老师）：你谈到的早起，每天几点起来算是早起呢？\u003c/p>\u003cp>甲（小明）：我理解的每天早上6:30之前就可以算早起\u003c/p>\u003cp>乙（黄老师）：那你打算什么时候开始这样做呢？\u003c/p>\u003cp>甲（小明）：我打算从明天早上开始尝试。\u003c/p>\u003cp>乙（黄老师）：非常好的执行力。那你每天早上6:30起来，可能会遇到哪些障碍呢？\u003c/p>\u003cp>甲（小明）：目前想到的障碍是头天晚上睡的太晚，第二天起不来，如刷抖音视频刷的太晚，或者加班比较晚回家。\u003c/p>\u003cp>乙（黄老师）：还有哪些可能的障碍呢？\u003c/p>\u003cp>甲（小明）：还有就是如果天气比较冷，也不太想起来。\u003c/p>\u003cp>乙（黄老师）：还有吗？\u003c/p>\u003cp>甲（小明）：还想到一点，可能自己会想赖床。\u003c/p>\u003cp>乙（黄老师）：好的，那我们刚刚学习了“如果…就…的”力量这个片段，可以帮助你更好的养成早起这个习惯，假如说你刚刚设想的这些障碍发生了，你会怎制定什么样的“如果……就”计划呢？\u003c/p>\u003cp>甲（小明）：我想想……我能想到的如下：\u003c/p>\u003cp> 如果过了11点我还在用刷手机视频，就把手机放下来，去刷牙洗漱。\u003c/p>\u003cp> 如果头天晚上加班到很晚还没回家，就告诉自己早点回去，工作可以第二天早上起来做。\u003c/p>\u003cp> 如果内心出现了想赖床的想法，就马上起床洗个冷水脸。\u003c/p>\u003cp>乙（黄老师）：特别好，能看出小明想要养成早起习惯的决心。你现在困扰减轻了一点了吗？\u003c/p>\u003cp>甲（小明）：减轻了一些，谢谢黄老师。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1606101619000,"updated_at":1606720839000,"ria":true},{"id":9562,"topic":"如何达成目标","learn_goal":"见实录","remark":"《如何达成目标》，该书作者叫:海蒂·格兰特（Heidi Grant）她是一位社会心理学家，从事动机科学的研究，写作和演讲。在2017年，她被评为Thinkers50全球**影响力的管理思想家之一。她是神经领导力研究所的首席科学官，哥伦比亚大学动机科学中心的副主任，也是这本既源于严谨可信的科学成果，又具有极高的实用价值，能够帮助你打通达成目标的各个环节的畅销书作者。\r\n 该书是精选了国际**心理学家几十年来数百个心理学研究的心理学经典著作。安人心智董事长阳志平老师评论它是市面上**本将自我决定论、成长型心智与执行意图结合在一起写的好书。果壳CEO姬十三说：无论你的目标是一个亿还是早睡，本书都能助你","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"斑驳阳光","city":"上海市"},"club":{"name":"上海申展分舵","city":"上海市"},"prologue":"\u003cp>【备注】：拆书帮官网上没有所拆书籍《如何达成目标》，该书和《成功、动机与目标》是相同内容的不同版本，遂所建实录名有出入，特此说明。\r\n&nbsp;\u003c/p>\u003cp>【自我介绍】\r\n大家好，我叫周秧秧，是一名园林工程师。今天拆解2-4等级。我们先来分个组：组别就按照刚刚卢燕分好的组别。接下来我们正式进入拆书环节。&nbsp; &nbsp;\u003c/p>\u003cp>【图书介绍】&nbsp;\u003c/p>\u003cp>【F】今天我带来的拆页来自于书籍《如何达成目标》。该书作者叫:海蒂•格兰特（Heidi Grant）她是一位社会心理学家，从事动机科学的研究，是哥伦比亚大学动机科学中心的副主任，也是这本既源于严谨可信的科学成果，又具有极高的实用价值，能够打通实现目标各个环节的畅销书作者。\r\n&nbsp;\u003c/p>\u003cp>【A】该书荣获豆瓣千人9分好评。安人心智董事长阳志平老师评论该书是市面上第一本将自我决定论、成长型心智与执行意图结合在一起写的好书。果壳CEO姬十三评论说：无论你的目标是一个亿还是早睡，本书都能助你一臂之力。该书精选了国际顶尖心理学家几十年来数百个心理学研究,被业内公认为心理学经典著作。\r\n&nbsp;\u003c/p>\u003cp>【B1】当你看着无数个曾经雄心勃勃设下，又遮遮掩掩翻过的目标计划而否定自己的能力、深感自制力不足，你甚至一度怀疑这个目标是否是你真的想要的目标？这本书将给你配置对症的良方：无论是小到减肥、健身、大到升职、创业，这本书都能帮你一一解决。\r\n【B2】今天的拆页将引领你在设定目标时,通过心理对照的方法去设想障碍,把关注点放在必要的行动。\r\n在达成目标的道路上，学会关注过程而不是关注结果，在遇阻时做出一个积极的调整。\r\n【片段一学习目标】\r\n首先我们要学的这个片段的目的就是让大家在制定目标时，通过心理对照的方法，能够设想到并列出妨碍目标实现的障碍及应对方案。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":13390,"quote":"\u003cp>【引导语】接下面就请大家带着学习目标，花1分钟的时间来阅读下拆页。\u003c/p>\u003cp>【R：拆页原文1】\u003c/p>\u003cp>运用“心理对照确定目标\u003c/p>\u003cp>1.拿起笔记本或者一张纸，写下你最近产生的愿望或想法。这可以是一件你想要做或是已经开始做的事情（例如去加勒比海度假、搬到洛杉矶去当一名编剧，或者减掉四五千克体重）。\u003c/p>\u003cp>2.现在，想象一下愿望实现时的美好结局。写下这个美好结局一个方面的好处（比如你可以不去查收电子邮件，惬意地躺在沙滩上放松身心，该是多么的美好）。\u003c/p>\u003cp>3.接下来，想一想你现在的状况与这个美好结局之间还存在些什么障碍（比如，我现在有些胖，而我的美好结局是减掉四五千克体重，这两者之间的障碍是我格外喜欢吃奶酪）。\u003c/p>","explains":"\u003cp>【引导语】大家都阅读地差不多了，那就一起来理解下这个拆页。\u003c/p>\u003cp>【I：用自己的话重述原文】\u003c/p>\u003cp>【what】该拆页向我们清晰阐述了使用心理对照的三个步骤，所谓心理对照就是在你畅想已经达成自己目标场景的同时，还需要周全地思考妨碍目标实现的障碍及应对措施。\u003c/p>\u003cp>【why】通常情况下，人们总是认为:只要设定好速度、沿着既定轨道就能抵达目标终点。好比你开着时速400KM/时的子弹头列车，认为我只要一直保持速度，盯着目标就能驶向终点，殊不知过程中的天气情况、路况、车况等等都会成为阻碍目标达成的障碍，我们需要提前设想，并积极应对，才可能按时抵达。\u003c/p>\u003cp>【不那么做的坏处】\u003c/p>\u003cp>如果我们不按照心理对照的方法设定目标,容易把目标想得过于天真，错误地估计目标实现的难度，导致目标无法达成。\u003c/p>\u003cp>【反例】\u003c/p>\u003cp>【时间】 上周末。\u003c/p>\u003cp>【经过】 计划在周末完成2-4拆书稿，想着两天时间足够了。\u003c/p>\u003cp>【结果】&nbsp;家里来了亲戚，计划全泡汤了。\u003c/p>\u003cp>【反思】这个案例中,没有设想过程障碍、低估目标达成的难度,导致目标没法达成。\u003c/p>\u003cp>【how-细化步骤】那我们应该如何通过设想过程中的障碍来应用心理对照呢？\u003c/p>\u003cp>【确认目标】记录一件你有愿望想做或已经在做的事。\u003c/p>\u003cp>【畅想愿景】想象下出目标达成的美好画面，让这份美好激发和引领你不断向前。\u003c/p>\u003cp>【设想障碍】设想目标实现过程中的各种情况。\u003c/p>\u003cp>【匹配方案】根据设想的障碍情况去匹配具体的应对方案。\u003c/p>\u003cp>【正例】\u003c/p>\u003cp>【时间】 本周一一睁眼。\u003c/p>\u003cp>【经过】 突然想起周四要拆书,但拆书稿还是一片空白。怎么办呢?想到刚刚看完的《如何达成目标》中的心理对照概念，马上行动起来。\u003c/p>\u003cp>【确认目标】首先，确立目标：周一下班前要搞定拆书稿，发给师父审阅。\u003c/p>\u003cp>【畅想愿景】周四在舞台口若悬河后，观察家大笔一挥，说恭喜大侠通过。\u003c/p>\u003cp>【设想障碍】【匹配方案】\u003c/p>\u003cp>（1）周一是工作日，一大堆的事情等待去处理，哪来的时间写拆书稿呢。所以只能早上提早一个小时到单位，中午放弃休息时间。\u003c/p>\u003cp>（2）最近在练双拼，打字太慢，怎么办，特殊情况，破例一次，重新安装顺手的输入法。\u003c/p>\u003cp>（3）下午还要开例会：手上功课干不了，就换成脑力劳动：见缝插针思考下两个拆页的逻辑。\u003c/p>\u003cp>【结果】下班前完成拆书稿，发给师父审阅。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>适用于相对比较复杂，或有挑战的目标，特别简单的目标比如，下楼取个快递，这个完全能通过肌肉记忆或潜意识就能完成的目标就没必要使用心理对照了。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>你可能会说我这个目标很复杂，而且是第一次尝试，我没法预见障碍，这该怎么办呢？ \u003c/p>\u003cp>我想说，这个问题可以求助大牛、导师、网络、书籍等，站在巨人的肩膀上比独自用力要高效地多，同时想说明的是：事情是变化发展的，即便你设想了所有可能的障碍，依然会有不期然的意外，设置心理对照的目的，是让你明白：任何一个目标都不能随随便便成功，加入遇到情况，你将如何应对，这才是设置心理对照的初衷及关注要点。\u003c/p>","interaction":"\u003cp>【A1分步催化之激活应用场景】\u003c/p>\u003cp>现在请小伙伴们回想一下，在自己的过往制定目标的经历中，有没有只盯着目标，忽略了妨碍目标实现的障碍，而导致一路手忙脚乱，最终目标未能达成的场景呢？比如：你想得万无一失要在周末要完成的工作总结，因为家里来了个亲戚，最终全泡汤了。比如：你想加入某个大公司，但面试败给了另一位同行者；比如你计划每天早上6点起来跑步，但冬天太冷，所以目标未能达成，给大家2分钟在组内讨论，2分钟后我会邀请一位小伙伴分享。\u003c/p>\u003cp>【学习者陈祺分享】\u003c/p>\u003cp>【时间】前段时间。\u003c/p>\u003cp>【经过】接了个私单，报酬很可观，一开始以为三天就能搞定，很得意。\u003c/p>\u003cp>【结果】发现不好干，分了好多系统，每套系统还是不同语言，相同语言还采用了不同的框架，还没开始做，光研究框架、语言就花了3天。\u003c/p>\u003cp>【反思】过程障碍没考虑清楚，太高估自己的能力了。\u003c/p>\u003cp>【拆书家点评】非常感谢陈祺的分享，这是个非常匹配的忽略障碍的应用场景，分享地非常精彩，再次感谢。\u003c/p>\u003cp>【A1+反思加工】\u003c/p>\u003cp>假如还有再来一次的机会，你会如何运用今天学到的心理对照的方法的四个步骤来设定目标呢？请大家在小组内讨论，3分钟后请一位小伙伴来为大家分享！\u003c/p>\u003cp>【学习者陈祺反思分享】\u003c/p>\u003cp>【确认目标】干私单赚钱。\u003c/p>\u003cp>【畅想愿景】赚的钱可以入自己的小金库。\u003c/p>\u003cp>【设想障碍】在这个环节没有考虑过程可能会产生的障碍，只核算了研发时间，没去设想准备时间和测试时间。\u003c/p>\u003cp>【匹配方案】要充分考虑业务过程的每个环节，衡量好每个环节需要投入的时间，目前看下来，准备时间和测试时间需要花费70%，研发时间需要花费30%，跟操作预期出入非常大。\u003c/p>\u003cp>【案例点评】可以说这个分享版本接近教科书式的反思版本，非常感谢伙伴的分享。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":13391,"quote":"\u003cp>【过渡及片段二学习目标】\u003c/p>\u003cp>感谢小伙伴的精彩呈现，刚刚我们学习的是今天的第一个片段，在制定目标时，能够设想到并写出妨碍目标实现的障碍及应对方案。但在目标实现过程中，远比设想的要复杂，我们在奔向目标的同时，非常需要具备成长型心智，接下来给大家带来第二个片段。学习目标是：在达成目标的道路上，学会关注过程而不是关注结果，在遇阻时做出一个积极的调整。\u003c/p>\u003cp>【引导语】接下面就请大家带着学习目标，花1分钟的时间来阅读下拆页2。\u003c/p>\u003cp>【R：拆页原文2】\u003c/p>\u003cp>心理学家将这种谋求进步的意愿（也就是提升或增强某种技能与能力的意愿）称作精通目标。当人们在追求精通目标时，他们不会通过自己是否达到特定结果（例如成绩全A或超越销售目标）来评判自己。相反，他们用进步来评价自己我有进步吗？我在学习吗？我的前进步伐适当吗？进步并不是着眼于某一次的优异表现，而是着眼于长期的优异表现。这种目标以全然不同的方式与自我价值联系起来，因为它们侧重于自我提升而不是自我认可，侧重于做到最优异、最能干，而不是侧重于证明你已经做得怎么样。\u003c/p>\u003cp>当我们追求精通目标（谋求进步）时，不太可能将自己的困难和差劲的绩效归咎为自己缺乏能力，因为这样做没道理。现在的我当然缺乏能力了，因为我还没掌握它啊！相反，我们会为困难和不足寻找其他更加可控的原因。我有没有足够刻苦地学这门功课？是不是该换一种方法？是不是应该找个高手请教一下？当人们在“追求卓越”的路上遇到麻烦时，他们不会像“展示才华”的人那样沮丧和无助，他们会付诸行动。他们会问自己哪里错了，然后去纠正错误。假如我第一次考试只得了C，我会将学习时间增加一倍，并且尝试不同的学习方法，比如使用记忆卡或者列出大纲。倘若我没有完成销售目标，我会和公司中经验更丰富的销售人员一同坐下来，请他们指导我。如果我的邻居似乎对我不感兴趣，我会想着如何吸引他的注意以及怎样增进相互的了解。若我第一次没能考上法学院，我会向法学院教授或招生工作人员讨教，看看在下一次报考时怎样才能使自己更有竞争力。有时候，“谋求进步”的目标能造就最大的成功，因为人们若是把注意力集中在“让自己更加卓越”之上，几乎不会一遇到困难就放弃。\u003c/p>","explains":"\u003cp>【I：用自己的话重述原文】&nbsp;&nbsp; \u003c/p>\u003cp>【what】该拆页给了我们阐述了一个新的概念：精通目标。旨在引导我们把对目标的关注从结果转向过程，从短期转向更长的时间周期，从僵固型思维转向成长型思维。这样才能让我们应对这个世界的无常，本着比昨天的自己进步一点点的心态调整步伐，勇往直前。\u003c/p>\u003cp>【why】通常情况下，人们总是顾着于结果而无法自拔，但多个心理学实验研究证明：人类的幸福瞬间并不在拿到目标的刹那，拿到目标时的被试是一种如释重负之感，真正的幸福时刻来自于在实现目标过程中的每一个进步的阶梯上，所以，我们可以把对达成目标的焦虑转换到触摸自我的成长上，用更平和的心态和目标友好相处。\u003c/p>\u003cp>【不那么做的坏处】\u003c/p>\u003cp>如果不那么做的话，容易让我们活在自我怀疑和永不停止的挫败感中，最终丢失斗志。\u003c/p>\u003cp>【反例】\u003c/p>\u003cp>【时间】本年度8月的某一天。\u003c/p>\u003cp>【经过】我认真准备了拆书，信誓旦旦地和同事扬言要拿下那天的拆书级别，结果现场未能有效控场。\u003c/p>\u003cp>【结果】大侠再来一次，内心很难过，拆书一度停了好久。\u003c/p>\u003cp>【how】步骤提炼、细化\u003c/p>\u003cp>【识别情绪】识别当下的感受：自我怀疑？难受？\u003cbr>\u003c/p>\u003cp>【识别诱因】是什么导致了这样的情绪？\u003c/p>\u003cp>【转换视角】由关注结果到关注过程，重新审视自我的成长和收获。\u003c/p>\u003cp>【调整方案】直面问题，调整方案。\u003c/p>\u003cp>【A1+反思】\u003c/p>\u003cp>【识别情绪】要线下重拆，不开心。\u003c/p>\u003cp>【识别诱因】比较看中结果，没有按照既定目标实现，导致自我否认。\u003c/p>\u003cp>【转换视角】虽然需要重新来过，但我通过观察家以及小伙伴的反馈，知道了问题在哪里，知道了改进方向，可以让自己变得更加优秀，这比得到一个通过更有价值。\u003c/p>\u003cp>【调整方案】写下当日复盘，调整拆书稿，重新再来。 \u003c/p>\u003cp>【where】\u003c/p>\u003cp>该方法适用于个人自我成长，但企业等组织不负责员工个人成长，只注重绩效结果，就不适用这个方法了。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>可能有的小伙伴会说：我用这种方法就是说服不了自己，这是什么情况呢？那可能是因为你在实现目标的过程中没有真正用力，导致你没法和自己和解。如果你足够用心，当你把视角从结果转向过程时，一定会发现自己的闪光点，同时也能看到有待改进的方面。\u003c/p>","interaction":"\u003cp>【A3·促进参与】\u003c/p>\u003cp>听完上述讲解，相信大家对精通目标已经有点感觉了，接下来我们来演练一下。\u003c/p>\u003cp>让我们想象这样一个场景：圆圆最近在减肥，又是节食、又是运动，还是没减下计划的10斤肉，非常沮丧懊恼。正好碰到了学过精通目标，具备成长型思维的方方。方方打算好好开导下圆圆。\u003c/p>\u003cp>请一位伙伴扮演圆圆，一位伙伴扮演方方，基于圆圆计划减肥而未成的背景，运用拆页精通目标的方法，帮助圆圆转变思路，重新启程。给大家7分钟时间演练，7分钟以后，我会邀请一个小组进行分享。\u003c/p>\u003cp>【演练环节】学习者leah扮演方方，学习者卢燕扮演圆圆。&nbsp;&nbsp;\u003c/p>\u003cp>【方方】最近怎么没见你跑步了？\u003c/p>\u003cp>【圆圆】别提了，一直想减肥，减了快一年了，还没减下来，都没信心了。\u003c/p>\u003cp>【方方】你为什么要减肥呢？\u003c/p>\u003cp>【圆圆】感觉瘦的人穿什么衣服都好看，所以我想减肥。可是就是怎么都减不下来。\u003c/p>\u003cp>【方方】你不能只看体重这一个指标，你要看你腰围有没有更细、肌肉是不是更多了，皮肤是不是更紧致了。\u003c/p>\u003cp>【圆圆】这些我知道，可是我的困扰点就在于，我想减的10斤肉一直没减下去啊。\u003c/p>\u003cp>【方方】你想减肥，可是没减成，心情很懊恼，这个我们都很好理解，但我想了解下，在你的减肥过程中，你做了些什么？\u003c/p>\u003cp>【圆圆】我坚持锻炼。&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \u003c/p>\u003cp>【方方】是怎么锻炼的，能给大家分享下吗？\u003c/p>\u003cp>【圆圆】我每周锻炼2次，坚持了一个月。\u003c/p>\u003cp>【方方】后来有继续坚持吗？\u003c/p>\u003cp>【圆圆】后面感觉没效果，就断了。\u003c/p>\u003cp>【方方】对，你没有坚持下去，这个就是你在目标达成的过程中出现的一个问题。你能针对这个问题，寻找一个解决的方案吗？\u003c/p>\u003cp>【圆圆】可以加入一个减肥打卡群，通过同侪压力互相促进。\u003c/p>\u003cp>【案例点评】非常好，当目标在达成过程中，遭遇困难时，我们在识别因不利结果导致的负面情绪的同时，还需要提炼具体的做法，去切换视角，这样才能找到具体做法的调整和优化方案。再次感谢伙伴们的精彩演绎。\u003c/p>\u003cp>【A2·催化应用之分步催化1】\u003c/p>\u003cp>接下来请大家设想下在未来的一个月里，你有什么特别渴望推进的工作、学习或生活目标吗？比如一年阅读100本书、考试考第一、拿到先进工作者等等。请大家设想一个渴望推进的目标，给大家2分钟时间，2分钟以后，我会邀请一位伙伴进行分享。\u003c/p>\u003cp>【学习者佩奇分享】&nbsp;&nbsp; \u003c/p>\u003cp>本季度末，要把这本《如何达成目标》的书籍开发成内容更落地、更适合学生吸收和践行的知识产品，放到喜马拉雅等多个付费平台，赚取更多的收入。\u003c/p>\u003cp>【拆书家案例点评】感谢分享，这位小伙伴的目标是要把一本书开发成一个更落地的知识产品，获取更多的套利，非常好的一个目标，我们在点赞的同时，也肯定想到，这绝非易事。那么，在真正去达成这个目标的过程中，如果推进不尽如人意时，我们该怎么做呢？\u003c/p>\u003cp>【A2·催化应用之分步催化2】\u003c/p>\u003cp>接下来请大家设想当你的目标推进不尽如人意时，如何应用今天学习的精通目标的4个步骤去关注过程及应对，请大家给自己的目标规划一个行动步骤，要求注明未来的某个时间，以及具体可衡量、可实操的目标，给大家6分钟的时间，6分钟以后，我会邀请一位伙伴进行分享。\u003c/p>\u003cp>【学习者leah分享】\u003c/p>\u003cp>【目标】2020年3月，要学习弹奏乌克丽丽。\u003c/p>\u003cp>【设想应用背景】截止2020年3月，乌克丽丽的学习计划没有按预期推进。\u003c/p>\u003cp>【识别情绪】没有按计划推进，有些埋怨自己。\u003c/p>\u003cp>【识别诱因】着眼于没有推进的结果点。\u003c/p>\u003cp>【转换视角】原因是要带孩子，空闲时间少，做好时间管理，是我可以改进的问题。\u003c/p>\u003cp>【调整方案】我合理安排好带孩子的时间，见缝插针地进行学习。&nbsp; \u003c/p>\u003cp>【拆书家案例点评】感谢，当我们的目标推进受挫时，我们光盯着埋怨自己没法推进的结果，不利于破局，要把视角转换到没有推进的原因是要带孩子，时间少这个问题，所以调整方案的方向是时间管理。再次感谢小伙伴的分享。\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>非常感谢伙伴们的参与，我们再来回顾下今天我们学习的两个拆页：在制定目标时，能够想到并写出妨碍目标实现的障碍及应对方案；在达成目标的道路上，学会关注过程而不是关注结果，在遇阻时做出一个积极的调整。希望对大家有所帮助，今天的拆页分享就到这里，感谢大家的陪伴和聆听，谢谢。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (学习者分享案例根据语音整理)\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":true}}],"created_at":1577692717000,"updated_at":1577693921000,"ria":true},{"id":9524,"topic":"如何让愿望达成","learn_goal":"让愿望变成可实现目标","remark":"任何人都能够实现目标，看你有没有用对方法。用对方法，实现目标就变得容易了。","level":"TF3-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"天一","city":"绍兴"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"【自我介绍】\r\n大家好，我是天一，天天进步，知行合一。目前我是个二级拆书家，我今天给大家分享的主题是，如何让愿望变成可实现目标。\r\n【分组】\r\n为了让大家有更好的学习效果，我们进行分组，未闻和土豆一组，这边三个伙伴（俊杰，央央，燕飞）一组。\r\n【图书介绍】\r\n【场景】\r\n不知道你的身边有没有过类似的场景？有个闺蜜兴致勃勃的和我说，我长胖了，现在106斤了，我要瘦身了，我一定可以瘦身成功，我相信我可以轻松减到100斤。说这话时她的脸上发光，信心满满的样子。过了三个月，她告诉我，她现在是112斤。体重没有减轻，反而增加了6斤。她很懊恼\r\n【提问】\r\n明明定目标的时候很有把握的样子，结果却是离目标越来越远了，大家身边有没有发生过类似的事情？现在问下现场小伙伴们\r\n学习者：有\r\n想不想解决这样的问题？\r\n学习者：想\r\n【影响】\r\n大多数人目标年年定，年年没实现，慢慢的开始怀疑自己的能力有问题，时间再久一些，经过一次次的打击，连个想法都没有了，浑浑噩噩过日子，一辈子碌碌无为。\r\n【解决】\r\n难道任由自己天天混日子，被人看笑话？就没有解决方案吗？有，《成功，动机与目标？》这本书中解决你把梦想变成可实现目标，把实现目标的成功率大大提升。\r\n今天我们分享的拆页，让你从动机+行为，两个方面同时推进，让愿望和想法变成可实现的目标。\r\n【学习目标】\r\n通过现场RIA的学习，学习者能够辨别（行为）出什么是心理对照，并且能够运用心理对照策略（澄清）制定出一个达成目标的计划方案。（界定）","ratings_count":1,"texts":[{"id":13343,"quote":"\u003cp>\u003cp>来自巜成功，动机与目标》\u003c/p>\u003cp>主题:如何把愿望变成可实现目标\u003c/p>\u003cp>值得提出的一点是，\u003cstrong>心理对照\u003c/strong>只能助你致力于你真心相信可以实现的目标。(这里我们再次看到相信自己能成功的重要性。)如果你不相信自己能成功，那心理对照会让你从这个目标中解脱。其实就是说，它能使你抛开无法实现的幻想。这实际上也是使用此策略的另一个好处。考虑你想要什么以及障碍是什么可以使你头脑清楚地傲出好的决定一一当成功概率高时，你会更致力于这个目标，从而更有可能实现它，当成功概率不怎么乐观时，你能认清状况，放手前行。\u003c/p>\u003c/p>","explains":"\u003cp>\u003cp>\u003cstrong>【A1自测量表】\u003c/strong>\u003c/p>\u003cp> 在正式阅读原书片段之前， 我先邀请各位伙伴完成这份自测表 ：以下5个题目，请按照1~6分的标准给自己打分，1分代表完全不符合，6分代表非常符合，请你花1分钟的时间，将每道题打分，并汇总分数，做好的小伙伴可以示意我一下：\u003c/p>\u003cp>\u003cp>\u003cstrong>【I测试题讲解】\u003c/strong>\u003c/p>\u003cp> 好的，所有的小伙伴都已经完成。我们来看下大家的得分，得分在20分以上的伙伴请举手， 好的有3位小伙伴，特别棒 ，恭喜你们， 说明你是个善于把愿望变成目标的人 ，目标达成的概率相对比较高，希望今天的学习 可以 让你 更精进；得分在10-20分的伙伴请举手， 有两位伙伴，在这个得分范围说明 说明你们已经具备了把梦想变成目标的思维 ，在行为上还需要进一步的细化，可以通过 今天 学习有更大的提升 。 有没有10分以下的小伙伴，看来今天在场的小伙伴，对于目标的达成整体水平还是比较不错的\u003c/p>\u003cp>好，现在请伙伴们看下发下去的片段，可以找下关键词，时间是一分钟\u003c/p>\u003cp>\u003cp>\u003cstrong>【I内容讲解】\u003c/strong>\u003c/p>\u003cp>看到大家都已经看完了片段，进入我们的I环节\u003c/p>\u003cp>\u003cstrong>【简短互动，精准控场】\u003c/strong>\u003c/p>\u003cp>这个片段中出现了哪个关键词？\u003c/p>\u003cp>学习者：心理对照\u003c/p>\u003cp>\u003cstrong>【回应式反馈】\u003c/strong>\u003c/p>\u003cp>非常好，一下子就找到了我们今天要分享的核心关键词\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>\u003c/p>\u003cp>什么是心理对照？我们来看下这张图，\u003c/p>\u003cp>心理对照就像是一个人的两条腿，\u003c/p>\u003cp>左边这条腿代表&quot;想&quot;，想啥？（为什么的问题）\u003c/p>\u003cp>1.为什么要做这件事？2.你想要的是什么？3.美好的结果是哪些？解决的是动机问题\u003c/p>\u003cp>右边这条腿是&quot;做&quot;（是什么的问题）\u003c/p>\u003cp>为了达成目标，你现在需要做的是什么？解决的是行为的问题。\u003c/p>\u003cp>心理对照需要拥有两条腿，才更容易到达目的地。\u003c/p>\u003cp>\u003cstrong>【Why】\u003c/strong>\u003c/p>\u003cp>如果只是知道为什么要做，和想要什么，很多时候目标都在空中，落不了地。而如果只是知道要做什么，没有方向，遇到困难很容易就被打趴下，心理对照策略同时解决了为什么（动机）和是什么（行为）的问题，大大提高了达成目标的概率。\u003c/p>\u003cp>\u003cstrong>【概念对比讲解】\u003c/strong>\u003c/p>\u003cp>为了让大家对心理对照这个概念有更深的了解，我们来分析下最初的那个案例\u003c/p>\u003cp>闺蜜因为想身材好，因此要瘦身，这是不是心理对照？\u003c/p>\u003cp>学习者：不是\u003c/p>\u003cp>拆书家：是的，闺蜜知道自己为什么要瘦身，动机有了，而没有在行为上做好充分的准备。\u003c/p>\u003cp>如果闺蜜不仅知道为什么要瘦身，她也清楚自己在瘦身的过程中会遇到各种挑战。因此她制定了应对一系列挑战的解决方案，这时候，是不是心理对照？\u003c/p>\u003cp>学习者：是的\u003c/p>\u003cp>拆书家：是的，动机，知道自己为什么要做和想要的结果，行为上，做好了各种应对障碍的方案。符合了这两个条件，就是心理对照。\u003c/p>\u003cp>\u003cstrong>【How行动步骤】\u003c/strong>\u003c/p>\u003cp>明白了什么是心理对照？该如何运用呢？为大家总结了以下行动步骤\u003c/p>\u003cp>1.列出愿望：列出一个自己的愿望或者是想法，一直是自己想要没有去做的。\u003c/p>\u003cp>2想象结果：想象愿望达成时的美好结局\u003c/p>\u003cp>3.想象障碍：想象美好结局和现实之间的障碍（写出自己认为的关键一两点就好）\u003c/p>\u003cp>4.列出新好处：再想一个达成这个愿望的新好处\u003c/p>\u003cp>5.列出新障碍：再想象都有哪些障碍\u003c/p>\u003cp>6.总结目标：根据上面的障碍列出具体的行为目标（计划方案 ）。\u003c/p>\u003cp>\u003cstrong>【举例】\u003c/strong>\u003c/p>\u003cp>举个我自己的案例\u003c/p>\u003cp>第一步：.列出愿望：成为超级演讲大师\u003c/p>\u003cp>第二步.：想象美好的结局：如果愿望实现了，我认为最关键的是可以轻松的变现。\u003c/p>\u003cp>第三步：想象障碍：没有好产品，没有客户\u003c/p>\u003cp>第四步：想象好处：孩子的榜样\u003c/p>\u003cp>第五步：.想象障碍：影响力不够\u003c/p>\u003cp>第六步：.列出具体的行为目标（计划方案）：关于这个愿望的目标\u003c/p>\u003cp>1）.设计好自己系统的课程（好的产品）\u003c/p>\u003cp>2）.通过微信，通过合作平台，找到更多的精准客户。（客户主动来找我）\u003c/p>\u003cp>3）每天一次在快手直播2小时以上（扩大影响力）\u003c/p>\u003cp>4）.每天发相关内容的朋友圈\u003c/p>\u003cp>5）.和其他有资源的平台合作\u003c/p>\u003cp>这里有两个点提一下：\u003c/p>\u003cp>如果你觉得第三步已经能够解决你的问题了，你可以从第三步直接跳到第六步，如果第五步还不能够解决你的问题，你可以第四步和第五步多次循环。\u003c/p>\u003cp>你可以一次性把能想到的好处，障碍全部写下来，你也可以写一两个比较关键的，今天因为时间关系，就只选一两个大家认为比较关键的点就好，重点是大家会用这个方法了。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>你可能会说，这个策略有用吗？用了以后就一定能够实现目标吗？我的回答是，不一定，但是比起只幻想美好结局，盲目相信一定能成的目标，实现目标的概率大大提升了。因此，花点时间\u003c/p>\u003cp>提前做个计划还是非常值得的。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>心理对照适合个人把愿望变成可实现目标，也适合团队决策某个项目或者是某件事要不要做的时候，但是前提，不管个人还是团体，必须相信可以达成，如果自己都不相信，心理对照策略不适合。\u003c/p>\u003c/p>\u003c/p>\u003c/p>","interaction":"\u003cp>\u003cp>\u003cstrong>A学习者拆为己用\u003c/strong>\u003c/p>\u003cp>\u003cstrong>A3\u003c/strong>\u003c/p>\u003cp>\u003cstrong>光说不练假把式，现在是我们演练的时候了，现在我为大家准备好了一个场景\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【场景设计】\u003c/strong>\u003c/p>\u003cp>小王是你的朋友，在一家销售公司上班3年了，销售业绩平平，虽然业绩是中等，可他的愿望，就是当上所在部门的销售部经理，可是不知道怎么干？又到了年底，要定目标，这时候，他来向你请教。因为他知道你在实现目标这方面比一般人都做得好，现在请你用心理对照法引导小王，帮他把愿望变成可实现目标。\u003c/p>\u003cp>现在，请先在小组确定好角色，一个扮演小王，一个是厉害的你，你如何引导他用今天我们学习的心理对照法来制定目标。要有人物对话，先在小组分享，时间时5分钟。等一下请一组小伙伴上来演练。\u003c/p>\u003cp>可能伙伴会说，我没有做过销售，不知道销售经理要具备什么能力.请问大家，通常一个销售经理需要哪些能力？\u003c/p>\u003cp>学习者：沟通能力，管理能力\u003c/p>\u003cp>如果大家想不出障碍，可以往这些方面去想。\u003c/p>\u003cp>如果大家还是不知道怎么做，可以参考下拆页后面的做的范本，我把刚才自己的案例做成了一个范本，供大家参考\u003c/p>\u003cp>\u003cstrong>【现场场景演练】\u003c/strong>\u003c/p>\u003cp>未闻（小王）：你好，土豆，我最近有点困惑，有个愿望一直想实现\u003c/p>\u003cp>土豆：什么愿望呀？\u003c/p>\u003cp>未闻（小王）：我想当我们部门的销售部经理（列出愿望）\u003c/p>\u003cp>土豆：这个愿望挺好的，你觉得这个愿望实现了对你有什么好处？\u003c/p>\u003cp>未闻（小王）：收入会大幅增长（想象美好结局）\u003c/p>\u003cp>土豆：挺好的，哪你觉得实现这个目标得障碍在哪里？\u003c/p>\u003cp>未闻（小王）：业绩不是最好的，也欠缺管理经验，没有办法当（想象障碍）\u003c/p>\u003cp>土豆：你认识到了这些问题，现在有解决方案吗？\u003c/p>\u003cp>未闻（小王）：报班或者是向前辈学习，自己想办法去开拓业绩。\u003c/p>\u003cp>土豆：好的，你觉得这个目标实现后还有其他的好处吗？\u003c/p>\u003cp>未闻（小王）：平台和方向不一样，自己也比较有成就感（新好处）\u003c/p>\u003cp>土豆：那现在阻碍你的目标的困难是什么？\u003c/p>\u003cp>未闻（小王）：自己不够专注，会被别的事情分散精力。没有在这方面投入很多的时间。（新障碍）\u003c/p>\u003cp>土豆：你既然意识到这个问题，现在有什么解决方案吗？\u003c/p>\u003cp>未闻（小王）：给自己设立年，月，日目标，每天都提醒自己，在这件事上多做些努力。这样会离目标越来越近。\u003c/p>\u003cp>土豆：挺好，那你现在的行为目标是什么？\u003c/p>\u003cp>未闻(小王）：1.设定年。月。日计划，（总结目标）（计划方案）\u003c/p>\u003cp> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;2.找师父或者是专业人士学习\u003c/p>\u003cp> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 3.更努力，采取各种途径拓展业绩\u003c/p>\u003cp>\u003cstrong>【分享点评】\u003c/strong>\u003c/p>\u003cp>谢谢两位伙伴的分享，运用心理对照策略制定出来的目标，比起最上面的愿望更容易执行了，目标也更容易实现了。如果要更深入，需要自己背后下功夫，继续深挖。时间关系，我们今天就不继续往下深入了。\u003c/p>\u003cp>\u003cstrong> 【A2布置作业】\u003c/strong>\u003c/p>\u003cp>拆书帮有个传统，学了一定要用，最后给大家布置个作业，回去写下自己的一个愿望，用我们今天学习的心理对照法来制定目标，在二天内完成作业的前两位学习者送《买房可以很简单》的书籍\u003c/p>\u003cp>\u003cstrong>【学习者微信作业反馈】\u003c/strong>\u003c/p>\u003cp>我：土豆，我有一个愿望不知道如何实现？\u003c/p>\u003cp>土豆：什么愿望？\u003c/p>\u003cp>我：我想成为一个三级拆书家（列出愿望）\u003c/p>\u003cp>土豆：很好呀，这个愿望达成后能够给你带来什么呢？\u003c/p>\u003cp>我：我是做培训工作的，我觉得最关键的是可以提高我的培训引导技能（想象美好结局）\u003c/p>\u003cp>土豆：那你觉得现在的障碍是什么？\u003c/p>\u003cp>我：现在最大的障碍是还没有达到报名条件（想象障碍）\u003c/p>\u003cp>土豆：那你有什么解决方案吗？\u003c/p>\u003cp>我：我已经参加了三次线下活动，接下来要首先完成三个RIA便签文档，还要再重温一下赵周老师的《这样读书就够了》，最后去报名参加线上训练营\u003c/p>\u003cp>土豆：你的行动目标很清晰，达成后对你还有什么好处吗？\u003c/p>\u003cp>我：有，可以提高我的影响力。（新好处）\u003c/p>\u003cp>土豆：那现在的障碍是什么？\u003c/p>\u003cp>我：有点害怕公开表达（新障碍）\u003c/p>\u003cp>土豆：那你想到的方案是？\u003c/p>\u003cp>我：我能够想到的是①观看主持人大赛学习如何如何表达观点；②利用好每次发言机会多锻炼；③认真准备每次发言。\u003c/p>\u003cp>土豆：因此，你现在的行动目标是？\u003c/p>\u003cp>我：①完成三个RIA便签文档；②重温一下赵周老师的《这样读书就够了》；③报名参加线上训练营；④观看主持人大赛学习如何如何表达观点；⑤利用好每次发言机会多锻炼；⑥认真准备每次发言。（总结目标）\u003c/p>\u003cp>土豆：很好，你的目标很清晰。\u003c/p>\u003cp>我：谢谢土豆，我知道接下来要怎么做了。\u003c/p>\u003cp>【拆书家反馈】\u003c/p>\u003cp>谢谢你提交的作业，你能够运用今天学习的心理对照策略制定出了计划方案。非常赞！要成为三级拆书家，知道了当下该做什么。未来在训练营毕业后也可以用这个方法更深入和细化，规划出拆书过级中的行动计划。祝你早日愿望达成！\u003c/p>\u003cp>\u003cstrong>【结尾总结】\u003c/strong>\u003c/p>\u003cp>每个人都有达成目标的能力，只是你会不会用方法。这个方法可以让你把问题想的很透彻，通过自己内在的问，你也可以让他人来问你，到最后出来的方案不仅是象我们现场这样稍微细些，是可以细到真正可执行，不过这需要时间。今天我的拆书就告一段落，希望大家能够把今天的所学真正用起来。谢谢！\u003c/p>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1577023822000,"updated_at":1577023822000,"ria":true},{"id":9238,"topic":"“表现”与“进步“","learn_goal":"如何在生活中应用“表现”和“进步”两种目标？","remark":"","level":"TF3-3","duration":60,"status":30,"type":0,"chaishujia":{"username":"慎蓓","city":""},"club":{"name":"深圳智成分舵","city":"深圳"},"prologue":"\u003cp>开场提示：\u003c/p>\u003cp>用3个标签来介绍我自己：NLP这门学问的受益者、实践者及传播者。我今晚拆解的3-3这个级别，我会以提问的方式来与大家进行互动，希望大家积极的配合参与，谢谢~\u003c/p>\u003cp>一、图书介绍\u003c/p>\u003cp>我今晚拆解的片段是来自于《成功，动机与目标》这本书\u003c/p>\u003cp>\u003cstrong>事件场景：\u003c/strong>我上一家公司在去年，接了一个政府的项目，委派我作为项目负责人，我不是很喜欢，可是接下这个项目就会有一个升职的机会，我为了得到这个机会，为了获得公司的肯定，我就硬着头皮接下了这项任务。执行的过程中少不了许多麻烦事，时间久了，我是做的越来越累，越来越没成就感，于是我选择了调回原来的岗位。\u003c/p>\u003cp>\u003cstrong>提问：(需要学习者回复）\u003c/strong>\u003c/p>\u003cp>我想问问在座的伙伴们，你们在追求目标的时候，会偏向于哪一种呢：是为了证明我的能力，我有本事，还是能够有所进步和成长呢？\u003c/p>\u003cp>\u003cstrong>学习者回复：\u003c/strong>都有可能会有。为了钱。\u003c/p>\u003cp>\u003cstrong>影响：\u003c/strong>当我们将焦点放在证明自己的能力，赢得他人的肯定时，一旦遇到困难或挫折，尤其经历的次数多了，我们就容易垂头丧气，陷入自我怀疑与否定当中。\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>海蒂的这本《成功，动机与目标》就告诉我们，想要成功，先理解目标是什么，在何处容易失败。而我今天所带来的片段，就是教会大家面对困境，想要放弃的时候，如何将“表现”目标转变为“进步”目标。\u003c/p>\u003cp>二、\u003cstrong>片段1的学习目标：\u003c/strong>\u003c/p>\u003cp>在跟随我完成片段一的学习后，针对学习者自己或他人所追求的目标，运用2个步骤\u003cstrong>（澄清）\u003c/strong>，能够识别出\u003cstrong>（行为）\u003c/strong>追求的是否为“进步型”目标\u003cstrong>（界定）\u003c/strong>。\u003c/p>\u003cp>接下来，我想邀请大家用2分钟的时间，阅读手中的片段：\u003c/p>","ratings_count":1,"texts":[{"id":13010,"quote":"\u003cp>心理学家把发展或增强某种技术和能力的意愿称作“精熟目标”。当人们在追求精熟目标时，他们不因是否达到特定结果而评断自己——比如成绩全A或超越销售目标。取而代之，他们用“进步”来评断自己。我有进步吗?我在学东西吗?我前进的速度适当吗?重点不是一次的表现，而是长期表现。这种目标是以完全不同的方式与自我价值关联起来的，因为它们着重于自我提升而不是自我肯定。这种目标关系到你是否做出了最大努力成为最好最有能力的自己，而不是证明你已经是最好的了。\u003c/p>\u003cp>当我们追求精熟目标(“进步”)时，我们比较不会因为困难和差强人意的成绩而埋怨自己缺乏能力，因为这样做根本没有道理。我当然目前缺乏能力了一一我还没掌握它啊!我们会找更可控的原因。我学习够下功去吗?我是否应该换个战略?我是否应该找个高手请教一下?当人们在追求\u003cstrong>“进步\u003c/strong>”的路上遇到困难时，他们不会像追求\u003cstrong>“表现”\u003c/strong>的人那样沮丧和无助，他们会做出行动。他们问自己哪里出了错然后去修复。如果我的第一个考试只得了C，我会用双倍的时间并且换一种方式学习，比如用记忆卡或自己列大纲。如果我没有达到销售目标，我会认真向公司中资深的销售人员讨教。如果我的邻居对我不感兴趣，我会想想如何吸引他的注意并增强相互的了解。如果我第一次没有考进法学院，我会向法学院教授或招生办公室咨询意见，看看在重考时如何让自己更有竞争力。“进步”目标有时能带来最大的成就，因为把注意力集中在“进步”上的人很少会过早放弃。\u003c/p>\u003cp>心理学家在研究学习中一次又一次地发现追求“表现”的绩效目标和追求“进步”的精熟目标能带给人截然不同的面貌、感受和行为。\u003c/p>","explains":"\u003cp>四、【I】拆书家讲解引导\u003c/p>\u003cp>我看大部分的伙伴已经阅读完了，接下来我们一同来解读下这个片段。\u003c/p>\u003cp>\u003cstrong>【简短互动】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>片段中提到我们对于目标的追求有哪2种类型呢？\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>自我提升、自我肯定、证明自己，进步目标，表现目标\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>注重不同的目标结果，决定着我们的动机有多强烈，面对困难时能坚持多久。有些目标让我们无论遇到什么困难，都能持之以恒；有些目标注定是要失败。片段中最后提到的“精熟目标”是以追求“进步”为评判标准的。而“绩效目标”以追求“表现”为标准，为了简便，以下我们都简称为“进步”目标和“表现”目标。\u003c/p>\u003cp>\u003cstrong>【强化概念，对比说明】+\u003c/strong>\u003cstrong>【简短互动】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>下面我列举了一些场景，请大家与我互动，一起来判断哪些是追求“进步”的目标。\u003c/p>\u003cp>反例1：小明每次考试都是全班第一，有次考试失常，他就觉得自己能力不行。\u003c/p>\u003cp>请问小明的目标是追求“进步”的目标嘛？\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>不是。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>小明看重的是单次表现结果，以此来评判自己；那如果小明她有看到自己大部分的表现是优秀的，那小明此时追求的就是“进步”目标，因为更看重\u003cstrong>长期的表现\u003c/strong>。\u003cstrong>（关键点1）\u003c/strong>\u003c/p>\u003cp>反例2：小张的销售业绩再次没有排进前三，他认为别人会看不起他。\u003c/p>\u003cp>请问小张的目标是追求“进步”的目标嘛？\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>表现目标\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>是的。小张他更看重自己是否被认可，被人肯定，他以外在的结果来推动自己；那如果小张看到自己的业绩虽然没有进前三，可他或许收获了许多新客户，或者给原有的客户提供了更好的服务，那此时小张追求的就是“进步”目标，因为他\u003cstrong>更注重过程中自我的提升（关键点2）：例如能力的增长，全力以赴等等，以此来推动自己。\u003c/strong>\u003c/p>\u003cp>反例3：小李参加拆书过级5次都没有通过，感到很沮丧，于是放弃了拆书。\u003c/p>\u003cp>请问小李的目标是追求“进步”的目标嘛？\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>不是的\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>小李在追求目标的过程中遇到可困难与挫折，做出了放弃的行为；如果此时小李去向他人寻求帮助，或者努力学习优秀的文稿，或者思考如何行动，那小李追求的是“进步”目标，因为他会\u003cstrong>找出原因，并付诸行动（关键点3）\u003c/strong>，而不是过早放弃。\u003c/p>\u003cp>所以，从上面例子，我们可以归纳出追求“进步”目标的特征：\u003c/p>\u003cp>看重长期表现、注重自我的提升、找出原因付诸行动\u003c/p>\u003cp>也正因为这些特征，追求“进步”目标的人，更容易享受过程，并从中找到乐趣。\u003c/p>\u003cp>\u003cstrong>正例：\u003c/strong>\u003c/p>\u003cp>我给大家举个例子：\u003c/p>\u003cp>前几天，有个朋友想转行做心理咨询，来向我了解些情况。我就简单的跟她聊了一会。\u003c/p>\u003cp>我问：你为什么想要转做心理咨询？\u003c/p>\u003cp>朋友答：我觉得这是个可以长期发展的职业，沉淀时间越久，越能推动自己去成长，咨询功力也会越深\u003cstrong>（看重长期表现）\u003c/strong>。\u003c/p>\u003cp>我问：嗯，这需要经历1-2年才能有一丁点进展，同时还要不断的学习的哦。\u003c/p>\u003cp>朋友答：这个我知道，很长一段时间都是在积累与培养能力的过程。\u003cstrong>（自我的提升）\u003c/strong>\u003c/p>\u003cp>我问：这个行业可没那么好做哦\u003c/p>\u003cp>朋友答：这个我知道，我也找人了解过，许多人中间放弃了，我有了解他们放弃的原因。也问询了一些成功了的人的意见。现在我也想找你咨询下我走进这个行业可以如何发展，如何去做。\u003cstrong>（找出原因，付诸行动）\u003c/strong>\u003c/p>\u003cp>在我厘清朋友设定的目标是追求“进步”的目标时，我不仅给予了他鼓励与支持，也给予了他所想了解的一些信息。\u003c/p>\u003cp>\u003cstrong>HOW：\u003c/strong>根据上面的例子，我们可以归纳出识别追求的是“进步”的目标的步骤：\u003c/p>\u003cp>1、列出目标：\u003c/p>\u003cp>可以列出正在追求的目标；也可以列出曾经追求的目标来练习\u003c/p>\u003cp>2、辨别特征：\u003c/p>\u003cp>根据追求“进步”目标的3个特征：看重长期表现、注重自我的提升、找出原因付诸行动，来辨别\u003c/p>\u003cp>\u003cstrong>（适用边界）\u003c/strong>可在生活中不是所有的事情我们需要追求“进步”，比如有奖竞赛的游戏，事情很简单就想要结果等等，做这些比较简单的事，有些需要注重表现的，反而证明自己强大会更有效。所以在处理生疏、复杂或困难的任务遇到阻碍，容易让人放弃的时候，我们可以来看看我们的目标是否为“进步”目标。\u003c/p>\u003cp>我对第一个片段的解读就到这里。\u003c/p>\u003cp>接下来，我们现场做一个小练习。\u003c/p>","interaction":"\u003cp>五、【A2】催化应用\u003c/p>\u003cp>大家可以设想一下，未来一周或者是一个月内，也许是你设定了一个想追求的目标分享给朋友，又或者是你的朋友设定了一个新的目标，分享给到你；\u003c/p>\u003cp>指令：\u003c/p>\u003cp>1、请各位小伙伴结合你将面对的事情，应用今天所学的方法，设计出一个小剧本，识别出你设定的目标是不是追求“进步”的目标，这里只需要识别出来即刻（这里是否有说明白）\u003c/p>\u003cp>2、小剧本内容要包含：人物角色、事件的起因；事情的经过、结果需要以对话的形式（一问一答）呈现；剧本里要体现我们今天学到的方法步骤，大家可以参照我刚刚演示的例子来编写。\u003c/p>\u003cp>片段的空白处有小剧本的格式，大家可以参考一下。\u003cstrong>（独立完成，不讨论）\u003c/strong>\u003c/p>\u003cp>请大家将小剧本写下来，3分钟后，我将邀请一位伙伴上台表演一下。\u003c/p>\u003cp>好，现在可以开始了。&nbsp;\u003c/p>\u003cp>\u003cstrong>学习者：石晶\u003c/strong>\u003c/p>\u003cp>石晶：下周林文舵主要过来当观察家，我就会跟他说，我想在一年之内，让我的拆书完成3-3。\u003c/p>\u003cp>那么林舵主就会说：那这没那么容易哦，这需要一个长期发展的一个心理准备。\u003c/p>\u003cp>我会说：这个我是知道的。\u003cstrong>（长期发展）\u003c/strong>我也问过我身边很多的拆书家，都有很多次挂的经历，没有说一次就成功的。我已经做好了足够的心理准备。我就是想再咨询你，怎么样可以让自己慢慢的，稳当的去升级打怪，完成我这个目标。\u003cstrong>（如何行动）\u003c/strong>\u003c/p>\u003cp>当林文老师知道我这个目标有了足够的心理准备时，他就会给我鼓励和支持，他也会给我一些关于拆书帮拆书的一些事情。例如他会说：你需要提前准备一些拆书片段，去多学习优秀的拆书家的一些拆书经验，多向他们学习和请教，即使挂了和失败了，也不要气馁，从中学习成长的经历和经验，为下一次积累经验。\u003cstrong>（能力提升+付诸行动）\u003c/strong>\u003c/p>\u003cp>石晶：即使挂了，我也不会放弃，我会觉得这是我的一种收获，我觉得我这个是进步的目标。\u003cstrong>（目标判定）\u003c/strong>更着重强调自我的能力提升。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家反馈+简短互动\u003c/strong>\u003c/p>\u003cp>非常感谢石晶的一个分享。在她的分享里面我们可以看到，她的整个目标里面，她判断出进步型目标的3个特征，符不符合？\u003c/p>\u003cp>学习者：符合。\u003c/p>\u003cp>拆书家：是怎么样符合的呢？\u003c/p>\u003cp>学习者：长期发展\u003c/p>\u003cp>拆书家：一年之内，实现3-3，对吧。\u003c/p>\u003cp>学习者：嗯，是的。\u003c/p>\u003cp>拆书家：然后呢？她还提到了什么？\u003c/p>\u003cp>学习者：自我提升\u003c/p>\u003cp>拆书家：她说如果失败了会如何？\u003c/p>\u003cp>学习者：绝不气馁\u003c/p>\u003cp>拆书家：可以提升自己的抗挫折的能力，还给到了一些建议，可以如何去做的。所以从这些我们就可以判定出她的目标是进步型的目标。\u003c/p>\u003cp>\u003cstrong>过渡：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>在这里我们并不是说进步目标好，表现目标不好。在我们的工作和生活中，两种可能都会同时存在着，也都会推动着不断的往前进步。第一个片段中有提到，在我们追求目标的路上，遇到困难或者阻碍，尤其是经历的次数多了，追求“表现”的人，会出现什么样的状况？\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>沮丧、无助、埋怨自己，过早放弃\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>当你焦虑、无助，想要放弃的时候，你要如何进行转变呢？接下来进入我们第二个片段的学习。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":13011,"quote":"\u003cp>\u003cstrong>片段2的学习目标：\u003c/strong>\u003c/p>\u003cp>在追求目标的路上，遇到困难想要放弃时，学习者能够运用4个步骤\u003cstrong>（澄清）\u003c/strong>，将自己的目标转换成“进步”目标\u003cstrong>（行为）\u003c/strong>，更从容的面对困境\u003cstrong>（界定）\u003c/strong>。\u003c/p>\u003cp>六、【A1】请大家自测\u003c/p>\u003cp>在阅读片段前，先请大家做一套自测题，评估一下你如何应对生活、工作中发生的事\u003c/p>\u003cp>评分说明：共5个题目，请在1~6分的区间内给自己打分，1代表完全不符合，6代表完全符合。请仔细阅读题目中的每一句话，根据自己的实际情况评分，第一感觉来评分。\u003c/p>\u003cp>1、只要是我可以得到的，我从不放弃。\u003c/p>\u003cp>2、我总能很清晰的知道自己为了什么而做事。\u003c/p>\u003cp>3、我从不为了表现、证明自己而做事。\u003c/p>\u003cp>4、我总会寻找一切办法来解决自己所面对的问题。\u003c/p>\u003cp>5、在做事的过程中，我总能接受和面对自己的无能。\u003c/p>\u003cp>七、【I】解释自测题（2分钟）\u003c/p>\u003cp>完成评分的伙伴，请把1-5项的分数都加起来，算出总分。\u003c/p>\u003cp>（提问）总分有没有大于26分的伙伴？请举手。\u003c/p>\u003cp>没有。高于26分的伙伴，在日常生活中非常自律，倾向于追求“进步”目标\u003c/p>\u003cp>总分有没有低于13分的伙伴？\u003c/p>\u003cp>没有。恭喜大家。如果低于13分，需要不断刻意练习转换追求“进步”目标的能力；\u003c/p>\u003cp>那大部分的伙伴是13-26之间的，转换追求“进步”目标的能力还有提升的空间。\u003c/p>\u003cp>今晚的这个测试仅供拆解片段使用，大家做个参考。\u003c/p>\u003cp>\u003cstrong>（技能点：自测表及解析）\u003c/strong>\u003c/p>\u003cp>接下来，我想邀请大家用2分钟的时间，阅读手中的片段：\u003c/p>\u003cp>当我的第一个孩子，女儿安妮卡出生时，我第一次做家长的目标绝对都是“表现”型的。当然我读了很多育儿经，看了很多育儿节目、作为心理学家，我本身也懂得“依附理论”，懂得要积极回应孩子发出的信息。我本来想获得“世界上最伟大的母亲”的称号，我把前前后后上上下下都处理得完美无瑕。哈，我原以为如此。现实是如何给了我当头一棒啊!从一开始，安妮卡就被家人称作：“多事宝贝”(貌似现在产生了一种更官方更正确的叫法:高需求宝宝）。她从出生到18个月大的这段时间里，除了吃饭、睡觉(不常)以外都在尖叫。因为我太想当“世界上最伟大的母亲”了，我把她的种种需求和过激反应都当作我身为母亲无能和失败的体现。我什么都怪自己。我每天的心情在焦虑与抑郁中跌宕起伏。我梦到自己钻进车里踩足油门冲出悬崖，然后融入夕阳.......从所有的混乱与对自身能力的怀疑中解脱。\u003cbr>\u003c/p>\u003cp>之后，让人欣慰的事发生了。就在绝望的边缘，我蜷在卫生间的角落里诚实地面对自己，我发现我完全搞错了，因为我的目标从头到尾都是错的。(令人非常尴尬的是，心理学家遇到自己的问题时有可能反应非常愚钝。)根本没有完美家长这一说。相信可以在摸索中把每件事做对，完全征服当家长这个挑战是愚蠢的想法。每个孩子都不同，在你迎接一个新生命降生时，你根本无法期待需要面对的事。\u003c/p>\u003cp>所以我振作起来了。我接受了我不是什么都懂，也不可能什么都做对的事实。我把我的目标从“表现”转变为“进步”。我不再想证明我是“世界上最伟大的母亲”，我的目标变成了“在做妈妈这个角色中不断进步”，并试着学习具体问题所需的技巧和耐心。随着不断地学习，我的焦虑和抑郁症状也减轻了。\u003c/p>\u003cp>我觉得跟刚开始比，我是个更好的妈妈了。我确实是更有耐心了每次出现状况时我不再觉得天要塌了。据我丈夫所说，跟我在一起更有趣了。同时我的女儿也从一个极难伺候的婴儿(她的外号叫刺儿头)转变成一个甜美、友善、相对随和的小女孩，我不知道其中有多少是因为我家长目标的改变，抑或这就是正常的儿童成长过程。不论我的转变对她是否有益，都着实改变了我的世界。\u003c/p>","explains":"\u003cp>九、【I】拆书家讲解引导\u003c/p>\u003cp>我看大部分的伙伴已经阅读完了，接下来我带着大家一同来解读下这片段。\u003c/p>\u003cp>\u003cstrong>简短互动：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>在这个片段中，我们有看到作者追求“表现”目标时，呈现了哪些状态或者行为呢？\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>焦虑、抑郁、认为自己无能、失败\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>是的。其实在做事的过程中，很多时候我们都会不自觉的去追求“表现”目标。现在大家脑海中有没有浮现出一些自己也曾经追求“表现”目标的经历呢？\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>有\u003c/p>\u003cp>\u003cstrong>HOW：\u003c/strong>那当我们在追求目标的过程中，遇到困难或挫折想要放弃的时候，如果将“表现”目标转变为“进步”目标呢？我们从作者的经历中来提炼下行动步骤：\u003c/p>\u003cp>1、诚实面对：当我们为所遇到的问题所烦恼的时候，我们厘清一下到底发生了什么？我们现阶段追求的目标是哪种？\u003c/p>\u003cp>如果判定是“表现”目标，接着第2步，如果你遇到了烦恼和问题，却仍然是追求“进步”的目标，那可能只是缺少一些方法，去寻找新的方法就可以了。那当我们判定自己的目标是“表现”目标时，我们第2步要怎么做？\u003c/p>\u003cp>2、接受事实：接受目前我的目标是为了证明自己的“表现”目标\u003c/p>\u003cp>3、目标转变：证明我是。。。。转变为做这些是为了不断进步\u003c/p>\u003cp>4、学习行动：学习解决现有困境的方法、技巧并行动\u003c/p>\u003cp>\u003cstrong>例子：\u003c/strong>我刚进新公司时，人比较焦虑，整个人像闲不下来似的。好不容易等到一个周末，我放松自己，整理思绪看看到底发生了什么。结果我发现自己在那段时间特别害怕别人的眼神，害怕自己觉得自己做的不够好，我发现我的目标是为了想要证明自己，想要得到认可时（\u003cstrong>诚实面对）\u003c/strong>，我有一会是没缓过神来。后来我想我可能是初到新公司才会如此，也就此接受了自己的这个现状\u003cstrong>（接受事实）\u003c/strong>。那一刻，我修改了自己的目标，由要一个结果转变成了自己在新公司的每一天都要进步一点\u003cstrong>（目标转变）\u003c/strong>，同时我也去寻找自己那段时间以来进步的表现。我也发现了自己焦虑是因为自己对公司业务不熟悉，还是有许多找不到方向的地方，于是我拟定了公司可以咨询的同事，和相关熟悉行业的朋友去寻找解决方案\u003cstrong>（学习行动）\u003c/strong>，就这样度过了那段时间。\u003c/p>\u003cp>\u003cstrong>（适用边界）\u003c/strong>我们在使用这个方法前，首先要明确的是我们追求的方向是正确的，符合道德规范的。同时还要有目标感，只是在追求目标的过程中出现了阻碍。\u003c/p>\u003cp>这个片段的解读就到这里了。\u003c/p>","interaction":"\u003cp>十、【A3】促动参与\u003c/p>\u003cp>接下来，我们进入互动讨论（微行动）环节：\u003cstrong>（15-20分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分组：\u003c/strong>\u003c/p>\u003cp>因为今天的人数有限，那么我们今天大家一起来进行讨论\u003c/p>\u003cp>\u003cstrong>指令\u003c/strong>：在平日的工作、生活中，我们也常会遇到自己或者他人，在做事的过程中所追求的目标是“表现”目标或者做事的过程中，变成了“表现”目标的，例如得到上司的认可，或者彰显自己的能干等等；请大家结合自己的经历、经验，在刚刚学习到将“表现”目标转变为“进步”目标的4个步骤：1、诚实面对，2、接受事实，3、目标转变，4、学习行动4个步骤中，你们\u003cstrong>共同\u003c/strong>认为哪一步是比较难做到的，或者还有什么样的问题，给大家3分钟的时间进行讨论。\u003cstrong>（3分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>提问：\u003c/strong>\u003cstrong>明确问题：\u003c/strong>\u003c/p>\u003cp>学习者经过探讨出的难点和问题点：（每一位学习者都有发表）\u003c/p>\u003cp>1、诚实面对，工作之前，我是为了证明我比我弟强，但我从来不承认，一直标榜我是个好姐姐\u003c/p>\u003cp>2、行动，找不到办法解决，跟我所有的经验完全不同\u003c/p>\u003cp>3、总是在这4个步骤里反复来，每一步都很容易，但走着走着就卡住了，又重新来。\u003c/p>\u003cp>4、诚实面对自己\u003c/p>\u003cp>综合大家所有的反馈，“诚实面对”这一步有2位伙伴，觉得相对比较难一点，因为时间，我们就选择这个问题。那哪位伙伴能否提供一个案例，我们来共同探讨一下呢？简单的描述一下。\u003c/p>\u003cp>\u003cstrong>学习者丽影：\u003c/strong>\u003c/p>\u003cp>工作之前，我一直很努力学习是为了得到妈妈的肯定，当然工作之前，我是怎么也不会承认的，标榜是为了自己，其实为了从我妈那得到肯定。每次取得一点进步都要求妈妈表扬。我弟弟是别人家的孩子，我只是为了证明，我比我弟强，但我从来不承认，一直标榜我是个好姐姐。\u003c/p>\u003cp>\u003cstrong>指令：\u003c/strong>\u003cstrong>（选出问题后）讨论问题的本质：\u003c/strong>\u003cstrong>（4分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（根据学习者的提问来探讨）\u003c/strong>\u003c/p>\u003cp>接下来，我们4位伙伴再来探讨一下，根据场景，结合大家的经历与经验，讨论下没有办法诚实面对自己，是为了求肯定，标榜自己是个好姐姐，行为是不断求表扬，请大家一起来探讨下无法“诚实面对”的背后的原因会是什么？大家可以多问几个为什么，以找到本质的原因？\u003c/p>\u003cp>1、在探寻问题产生的原因时，可能会列举很多，请针对其中1个最重要的原因点，纵向的反复的多问几个为什么，直到你们小组认为找到了，就请记录下来。\u003c/p>\u003cp>2、请大家根据自己的具体情况和经验进行讨论，这里只讨论本质原因，不讨论解决方案。\u003c/p>\u003cp>讨论：1、自尊心强，活在别人的目光里；\u003cbr>2、想要得到别人的认可，想要一个完美形象，不愿意面对、承认失败；\u003c/p>\u003cp>3、失败让自己自卑，让自己心灰意冷，否定自己；\u003cbr>4、把别人的评价当做自己，不会评价自己\u003c/p>\u003cp>5、不会自己评价自己，不会正确评价自己\u003c/p>\u003cp>\u003cstrong>明确问题本质\u003c/strong>：\u003c/p>\u003cp>拆书家：不会自我评价，这算不算你们找到的本质原因？\u003c/p>\u003cp>学习者：是的。相信别人的评价多过于自己的评价，觉得别人更客观，自己更主观。没有自我评价的标准。已经习惯了被别人来评价。不会对自己来一个真实的评价。\u003c/p>\u003cp>拆书家：归纳一下，我们没有一套自我评价的机制。\u003c/p>\u003cp>学习者：就是没有自我评价的标准。\u003cstrong>（问题本质）\u003c/strong>\u003c/p>\u003cp>拆书家：那我们想要解决的问题是什么？如何构建自我评价的体系\u003c/p>\u003cp>学习者：可以。\u003c/p>\u003cp>\u003cstrong>指令：\u003c/strong>\u003cstrong>讨论解决方案：\u003c/strong>\u003cstrong>（3分钟）\u003c/strong>\u003c/p>\u003cp>1）先讨论出针对这个问题，你们每个组认为解决到什么程度，也就是达到什么样的目标；\u003c/p>\u003cp>2）再根据这个目标，讨论出具体可以行动的步骤。\u003c/p>\u003cp>每组分享的伙伴分享出的讨论结果，需要表达出解决的目标和行动步骤。\u003c/p>\u003cp>学习者：如何构建自我评价自我体系，这个有点难。\u003c/p>\u003cp>拆书家：如果大家觉得难，可以将这个切细来讨论，变成：如何准确的评价自己。\u003cstrong>（想要解决的问题）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>呈现解决方案：\u003c/strong>\u003c/p>\u003cp>讨论：1）抽样调查，根据亲疏关系来判断，同事、朋友，多方面多维度来了解；2）找专家，找拆书家；3）从失败中反省、反思，认识自己；4）多看书，懂得越多，越对自己客观剖析，什么都不懂，就会盲目觉得自己都懂；5）多去登山，多去接触自然；6）换个环境，换一拨新人；\u003c/p>\u003cp>拆书家引导：达到什么程度就算是准确评价自己。\u003c/p>\u003cp>学习者：不会为别人的观点所左右，有自己的主见。\u003c/p>\u003cp>拆书家引导：我们会不会一下子就不会为别人的观点所左右？\u003c/p>\u003cp>学习者：不会。更能包容其他人的声音。每一次听到不同声音的时候，我们都能区分一点点，哪些是我的，哪些是别人的。\u003cstrong>（解决的程度）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>根据大家所讨论的，我们来归纳一下方法和步骤：\u003c/p>\u003cp>1、从失败中反思，反省，从而更加认识自己\u003c/p>\u003cp>2、多看书，多学习，多拆书，多增加见闻\u003c/p>\u003cp>3、寻求专家的意见\u003c/p>\u003cp>4、多接触大自然，给自己创造一个不同的环境\u003c/p>\u003cp>5、从各个不同的维度和角度去看待别人对自己的评价，所有人的意见进行归总\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>丽影，刚刚的问题有没有得到基本解决。\u003c/p>\u003cp>学习者：有的。\u003c/p>\u003cp>我们整个讨论互动的环节就到这里了。我们可以回顾我们整个4个行动步骤中间，将“表现”\u003c/p>\u003cp>目标转变为“进步”目标的整个过程中，虽然我们今天讨论的比较难的是“诚实面对”，那今后在生活中我们有可能遇到其他步骤比较难的情况，同样我们也可以运用今天的方式来解决问题。\u003c/p>\u003cp>十一、【A2】催化应用（需要现场演练）\u003cstrong>（2分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【找人分享】\u003c/strong>今天的最后一个环节，我想邀请大家想一想，当你走出这个课堂，也许是明天，也许是下周，你可以和哪一位，分享下第二个片段我们所学习到的内容及应用呢？也相当于是复盘。请大家将你所想分享的内容，时间，人物简单的写在便签上，1分钟，我会邀请一位伙伴来分享一下。\u003c/p>\u003cp>学习者：丽影\u003c/p>\u003cp>我打算回去跟我一个朋友分享如何进行自我评价，首先要告诉她要反思，找相关的心理学方面的书看，找相关的心理学专家去咨询，去开辟一个新的环境，例如来和我拆书，在不熟悉的环境里，去认识一下。\u003c/p>\u003cp>\u003cstrong>拆书家\u003c/strong>：那同时你能否跟他分享下我们今天第二个片段学习到的内容呢？\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>可以。重新给自己设定一个进步型的目标的时候，首要要诚实的面对自己，再接受自己，接受一下事实，设定这个目标到底是为了什么，然后把目标进行转变一下，当然要去学习一下解决这个问题的技巧，一定要有耐心。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>那你大概什么时候会跟她分享呢？\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>这个周末，因为我们约了周末一块吃饭。\u003c/p>\u003cp>好的，非常谢谢丽影给我们的分享。\u003c/p>\u003cp>\u003cstrong>有力的结尾：\u003c/strong>在我们的工作中，生活中，我们在追寻目标的过程中，很多时刻会陷入到追求“表现”目标，我们只要能运用今天所学习到的方法，就可以将目标进行转变，从容面对困境与挫折。\u003c/p>\u003cp>我今天的拆书环节到此结束。希望能够对大家今后的生活有所帮助。感谢大家的参与，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1573388073000,"updated_at":1573400370000,"ria":true},{"id":7983,"topic":"目标实现1","learn_goal":"心理对照列举出目标实现的障碍；利用“精熟目标”的衍生步骤精进","remark":"","level":"TF3-3","duration":60,"status":29,"type":0,"chaishujia":{"username":"赵自力","city":""},"club":{"name":"上海羊角村分舵","city":"上海市"},"prologue":"大家好，我是Jack，稍后会有小组讨论，我们先分一下组。 \r\n【学习目标】学习者通过本次学习，可以在制定目标时，使用心理对照的方法，列举出目标实现的障碍，并制定应对计划。在目标进度或完成度不及预期时，利用“精熟目标”的衍生步骤，止住颓势持续精进。\r\n【场景法图书介绍】\r\n【事件场景】大家有没有这样的一些体验？看到别人和老外无缝交流羡慕不已，用两个月的工资报了“死贵”的英语学习班，现在捶死自己的心都有；接触到一个能带来不菲奖金的意向客户就开始筹划来一场说走就走的旅行，结果客户“说走就走”了；年初为定好的新年目标兴奋不已摩拳擦掌，年终唉声叹气责怪自己；5年前就想学的吉他现在还是不会，偶尔还会想起2年前脑袋一热办的3年期健身卡。\r\n【提问】工作生活中经常发生类似的目标场景，你尝试过什么样的方法呢？一次又一次老样子，还是觉着应该在某些环节能施加影响？\r\n【影响】面对目标我们满是憧憬，“哎呀想想太美了”忽视了实现过程，导致结果不及预期。落差很大、挫败，自我埋怨，个人颓废挣扎生活一团麻，领导看不上工作不如意，自怨自艾，自我价值感和自尊心饱受折磨。\r\n【解决】今天给大家带来的这本《成功动机与目标》能帮到你，书中介绍制定目标的原则，对目标不同维度的认识以及达成目标的策略方法，帮你将目标与现实链接在一起，在认知层面上做好实现目标的准备，在行动上制定相应策略，最终实现切实可行的目标。\r\n接下来我们进入到第一个片段的学习，在制定目标时，使用心理对照的方法，列举出目标实现的障碍，并制定应对计划。请大家用一分钟的时间阅读原文。","ratings_count":1,"texts":[{"id":11558,"quote":"\u003cp>那么怎样才能更好地树立并实现目标而不是活在白日梦中呢？最佳策略是用乐观的方式看待目标，同时用实际的方式思考具体需要做什么才能实现目标。奥丁根把它叫做“心理对照”——首先你得能想到目标的实现，然后再反思其中的障碍。如果你大学毕业想找份高薪的工作，首先要能想象自己被一家顶级公司录用，然后再考虑你和这个目标之间存在什么障碍——比如其他优秀应聘者。这就使你不得不寄出很多份申请，不是吗？这就叫做：感受“行动的必要性”——这是实现目标所需的关键心理状态。幻想找到份好工作或者与倾心以久的暗恋对象坠入爱河是件很有趣的事，只不过你不会因此取得任何实际进展。心理对照能引导我们聚焦于必要的行动，从而把愿望和白日梦转化为现实。\u003c/p>","explains":"\u003cp>【简短互动】【明确核心概念】\u003c/p>\u003cp>【WHY】\u003c/p>\u003cp>就像开场制定年度目标时的兴奋不已、还没搞定客户就说走就走的旅行。学英语、练健身，制定目标时我们一开始很容易对结果保持过于乐观的态度，这让我们处于一种愉悦轻松的状态，在这种状态里，不自觉地放松下来。大脑也被迷惑，感觉目标实现并不难，“哎呀，一切尽在掌握，早晚的事”。它扭曲了我们对周围世界的信息搜集和判断，无法对客观情况进行审视。感受不到行动的必要性和紧迫性。\u003c/p>\u003cp>【WHAT】\u003c/p>\u003cp>好在作者通过实验研究，提出了片段中的概念方法叫心理对照。【简短互动】请问大家片段中时如何定义这个概念的？（将目标愿景与现实障碍对峙）对，直中标靶，非常赞。我做一个具象的解读：它是指个体首先想象目标实现的愿景，比如超额完成年度业绩指标带全家老小马尔代夫游，然后思考现实过程中阻碍目标实现的因素，比如客户量小、转化率低等。通过对比目标实现的愿景和现实障碍，链接未来和现实，进一步将障碍和克服障碍的行动之间建立联系。接下来我们通过例子来看一下。\u003c/p>\u003cp>【简短互动】【概念举例往返】\u003c/p>\u003cp>1、 宅男小明今年目标完成全马，到时同事夸赞还能博女神关注想想就美，大家来看，关于心理对照，小明哪方面做到了？哪方面没做到？\u003c/p>\u003cp>学习者：有目标有愿景，没有预想现实中的障碍。\u003c/p>\u003cp>非常赞，大家理解的很到位，想想就美肯定有动力，但小明需要进一步感受到规律训练的必要性。\u003c/p>\u003cp>2、 我有位工作非常努力的朋友目标是再升一职，这样可以带团队、薪资增长还可以买车。他也想到了最坏的结果不升职被外派到子公司。大家注意这个是心理对照吗？\u003c/p>\u003cp>学习者：摇头，有的点头说是。\u003c/p>\u003cp>这里大家注意一下，这不是心理对照。【概念比对】\u003cstrong>这有一个非常容易混淆的概念叫“防御性悲观”\u003c/strong>个体在面临新的类似成功情境时反复思考事情的各种可能结果放低期望值。两者\u003cstrong>最大的区别是\u003c/strong>防御性悲观偏重对结果的低预期设想，心理对照强调过程实现中的障碍。如果我那位朋友想到了工作业绩还不太够份量，团队影响力小等阻碍因素，这就进入心理对照的轨道，进而可以在障碍和克服障碍的行动之间建立联系。\u003c/p>\u003cp>【HOW】刚才通过例子对比，我们更好理解了心理对照的概念，那么具体如何做呢？我细化到四个步骤分享给大家：\u003c/p>\u003cp>1、确认目标。想一个自己渴求的，虽有些挑战但可执行的。\u003c/p>\u003cp>2、描述愿景。描述出目标达成之后的结果，思想自由驰骋尽量生动形象，来激发自己的行动力和积极性。\u003c/p>\u003cp>3、设想障碍。对相关情况和经历展开想象，外部探寻，内部深挖，设想关键障碍。\u003c/p>\u003cp>4、执行意图。要克服或规避障碍的话，你能怎么做？想象障碍可能出现的时间地点和可能情况，制定出一个“如果……那么……”的计划。\u003c/p>\u003cp>【举例说明】\u003c/p>\u003cp>简单介绍背景：18年11月初我正式加入拆书帮开始拆书升级，希望能在19年5月份成为三级拆书家。一开始感觉还有七八个月呢不着急，就拖呀拖，拖到自己心里犯嘀咕。特别幸运的是，当时接触到这本书了解了这个概念，连接到自己拆书升级。得益于心理对照和衍生的四个步骤，感受到了紧迫感和必要性，一周一拆书，一直在行动.我是怎么做的呢？\u003c/p>\u003cp>1、写下目标。19年5月份成为三级拆书家。\u003c/p>\u003cp>2、描述愿景。逐步接触到培训这样我就覆盖到了人力的全模块为工作赋能，为HRD更进一步；小成本尝试自己各种可能性，发现人生志趣；打开了弱联系圈层，开拓视野格局等等。\u003c/p>\u003cp>3、设想障碍。2个关键障碍1）经常加班时间冲突，算时间抛去元旦春节时间并不多；2）被挂现场难堪要面子伤自尊不去了。\u003c/p>\u003cp>4、执行意图。如果晚上加班那么明天早起写预备表，早出发1小时避免拥挤利用好通勤时间；如果出现线下分享的机会，就积极报名线下活动，错过一次就错过一周。要面子不去了那么就关注过程中的收获和进步，突破了舒适区，是一个很好的学习机会。（第二个片段我们会进一步学习）\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>这个方法适用于较为明确的可执行的目标，同时也要有一定的挑战性和复杂性，对于几乎没有挑战性的目标可以用但意义不大。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>你可能会说有些目标是第一次设立和执行，对障碍是缺乏预见性的，也就没办法针对障碍制定应对计划，这个方法有BUG啊。\u003c/p>\u003cp>首先我们必须要承认的是：无论做到什么程度障碍因素是无法穷尽的，穷尽障碍因素不是心理对照的目的，目的是什么？是给梦中的你浇一浇冷水，凡事没那么容易，感受到行动必要性和紧迫性。换一个角度“障碍缺乏预见性” “没经验、不知道坑在哪” 也是你设想的一个障碍呀，针对这种情况你同样可以建立执行意图，如果碰到预料之外的障碍，那么我就……请教领导问导师等等。\u003c/p>","interaction":"\u003cp>在拆书帮我们提倡是学以致用，研究成果也表明在大脑中过一遍等于实际应用了一遍。接下来我们来演练一下。以小组为单位，展开充分的想象，编一个小剧本，描述一段发生于未来的小故事，设计出时间、地点、人物、情节（包括：起因、经过、结果）和双方的对话、动作等，其中部分对话使用心理对照四个步骤，时间5分钟，请讨论稍后我们请小伙伴做分享。\u003c/p>\u003cp>学习者Viki\\Lance分享：\u003c/p>\u003cp>时间：下午稍后发生\u003c/p>\u003cp>地点：博库书城\u003c/p>\u003cp>人物：Viki（想减肥）、Lance（减肥过来人）\u003cbr>\u003c/p>\u003cp>情节：两人聊到目标，Viki兴奋地告诉L要用一个月的时间减肥10斤，L作为过来人深知不容易，就此做一个引导。\u003c/p>\u003cp>对话：\u003c/p>\u003cp>L：你的目标是什么？\u003c/p>\u003cp>V：用一个月的时间减掉10斤。（确认目标）\u003c/p>\u003cp>L：你这么急迫的，你的动力是什么？\u003c/p>\u003cp>V：夏天来了，可以穿出漂亮的衣服。（描述愿景）\u003c/p>\u003cp>L：个人觉着一下子减10斤还是蛮难的，应该会有很多障碍吧？\u003c/p>\u003cp>V：想吃欲望强；毅力不强控制不住；聚餐多等（设想障碍）\u003c/p>\u003cp>L：这障碍克服并不容易，你打算怎么做？\u003c/p>\u003cp>V：如果在家想多吃饭，那么使用专用的减肥盘（容量更小）；控制不住就参加打卡群进行激励。（执行意图）\u003cbr>\u003c/p>\u003cp>感谢两位伙伴的分享，非常赞，给两位掌声。\u003c/p>\u003cp>【过渡】\u003c/p>\u003cp>还记得我们第一个片段的学习目标吗？在制定目标时，能够列举出实现目标的障碍，根据障碍制定应对计划。三个关键词：目标、障碍、计划。有了障碍和计划我们为之付诸行动。但在目标实现过程中，并非一帆风顺。接下来我们进入第二个片段的学习。学习目标是：在目标进度或完成度不及预期时，利用“精熟目标”的衍生步骤，止住颓势持续精进。两个片段是一种递进关系。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":11563,"quote":"\u003cp>心理学家把发展或增强某种技术和能力的意愿称作“精熟目标”（成长进步）。当人们在追求精熟目标时，他们不因是否达到特定结果而评断自己——比如成绩全A或超越销售目标。取而代之，他们用“进步”来评断自己。我有进步吗？我在学东西吗？我前进的速度适当吗？重点不是一次的表现，而是长期表现。这种目标是以完全不同的方式与自我价值关联起来的，因为它们着重于自我提升而不是自我肯定。这种目标关系到你是否做出了最大努力成为最好最有能力的自己，而不是证明你已经是最好的了。\u003c/p>\u003cp>当我们追求精熟目标（“成长进步”）时，我们比较不会因为困难和差强人意的成绩而埋怨自己缺乏能力，因为这样做根本没有道理。我当然目前缺乏能力了——我还没掌握它啊！我们会找更可控的原因。我学习够下功夫吗？我是否应该换个战略？我是否应该找个高手请教一下？当人们在追求“进步”的路上遇到困难时，他们不会像追求“表现”的人那样沮丧和无助，他们会做出行动。他们问自己哪里出了错然后去修复。如果我的第一个考试只得了C，我会用双倍的时间并且换一种方式学习，比如用记忆卡或自己列大纲。如果我没有达到销售目标，我会认真向公司中资深的销售人员讨教。如果我的邻居对我不感兴趣，我会想想如何吸引他的注意并增强相互的了解。如果我第一次没有考进法学院，我会向法学院教授或招生办公室咨询意见，看看在重考时如何让自己更有竞争力。“进步”目标有时能带来最大的成就，因为把注意力集中在“进步”上的人很少会过早放弃。\u003c/p>","explains":"\u003cp>在开始之前我们先做一个小测试，有5个题目，请按照1-6分的标准给自己打分，1分代表完全不符合，6分代表非常符合。仔细阅读，根据自己的实际情况为自己打分，并在最后计算总分，时间为1分钟。\u003c/p>\u003cp>通过这个测试可以观察到你注重成长进步的程度。大家有超过25分的吗？这个高分区间代表注重程度非常高，具备典型的成长进步型思维，关注能收获什么，在完成目标过程中能够坚韧不拔，持续精进；10-20分是中间区间，有一定成长进步的意识，但也有很大提升空间；5-10是低分区间多会倾向证明自己，而不是关注能学到什么，一旦失败落差会特别大，容易中途放弃。不管属于哪个区间，接下来的片段学习可以帮到你。好则强化不足则改进。接下来请大家用1分钟时间来阅读原文。\u003c/p>\u003cp>【WHY】\u003c/p>\u003cp>工作生活中有很多目标，比如完成100万销售业绩、考试年级第一、超过同事A、跑步打卡100天、年底成为3级拆书家等等，大家肯定都不陌生。有愿景有动力，我们付诸行动努力追寻。【简短互动】遗憾的是，总是有内外因的障碍和困难，导致这些特定目标或是进度或是完成度并不及预期，请问大家真实的感受是怎样的？（感觉很糟，焦虑、沮丧，难堪，自我怀疑，我不行）如果不加以干预，后果是什么？一蹶不振，停止尝试，“我不行我不适合”中途放弃。\u003c/p>\u003cp>【WHAT】\u003c/p>\u003cp>作者又提供给我们一个全新的视角：“精熟目标”。从要么达标要么不达标非成即败的状态转移到关注成长进步。它有三个维度的特征：从评判标准上注重成长进步而非某一个特定结果，从关注点上着重提升自己而非证明自己，从周期上注重长期表现而非短期某个时间段的优劣情况。将只盯结果转化为要结果但更关注过程，这让我们当事情变复杂时不会垂头丧气，更倾向于相信坚持就是胜利，当怀疑自己时，不会失去动力，虽然很难，但可以从过程中学习，进步也是完全可能的。\u003c/p>\u003cp>【how】\u003cbr>\u003c/p>\u003cp>1、 描述状态。当下感受是什么，自我怀疑、沮丧？情绪带来的行为结果是什么？\u003c/p>\u003cp>2、 识别诱因。是什么场景触发了这种状态，背后的诱因是什么？\u003c/p>\u003cp>3、 自我和解。两个维度句式：这种诱因下的状态是预警信号，感受到了“危险”。为了避害让你赶紧回到舒适区，本意在保护你，只是还没有找到更好办法来做到这一点。XX人（自己身边敬佩的成功了的）也并非一蹴而就一步到位。\u003c/p>\u003cp>4、 转换视角。由注重结果到享受过程，重新审视有没有成长进步，有没有提升自己，长期来看会怎样？\u003cbr>\u003c/p>\u003cp>5、应对方案。针对实际情况，制定下一步行动。\u003c/p>\u003cp>【举例说明】\u003c/p>\u003cp>上个片段我提到5月份成为三级拆书家。但是在付诸行动的过程中，拆书的难度超出预期。去年11月份现场进行2-1拆书分享时，现场有位伙伴特别有感受，提出了好多他的见解，拉也拉不回，措手不及我懵了，我还用了最糟糕的应对方法：不懂装懂硬回答，你来我往又落了所谓的“下风”。你知道吗？当时在回家的地铁上我忽然感觉祥林嫂附体精神萎靡，碰到人我就想说：“唉……你不知道今晚……唉”。就不想拆了，如果不建立“精熟目标”的意识，很难拆到现在。怎么做的呢？\u003c/p>\u003cp>1、描述状态。尴尬、难堪，诅丧，不想去参加活动了。\u003c/p>\u003cp>2、识别诱因。场景就是我刚才讲的，背后的诱因自尊心的敏感，在意别人的看法。\u003c/p>\u003cp>3、 自我和解。这种诱因下的状态是预警信号，感受到了“危险”。为了避害让你赶紧回到舒适区，本意在保护你，只是还没有找到更好办法来做到这一点。身边的三级拆书家多多少少都会碰到类似情况，也并非一蹴而就一步到位。\u003c/p>\u003cp>3、转换视角。从结果到过程，有没有成长进步，有没有在提升自己，长期会怎样？\u003c/p>\u003cp>4、应对方案。面对现场的问题，下一步行动去和师父讨教学习，寻求建议。\u003c/p>","interaction":"\u003cp>【微行动步骤】\u003c/p>\u003cp>\u003cstrong>1、明确问题\u003c/strong>\u003c/p>\u003cp>【提问1】针对这个拆页片段，大家还有哪些疑问？现场学习者较为沉默，没有问题反馈。\u003c/p>\u003cp>【提问2】那结合你们的过往经验，最不容易做到的是哪一个环节？\u003c/p>\u003cp>viki:应对方案；lance：自我和解；betty：自我和解；L转换视角。经过举手示意，\u003cstrong>大家统一认可讨论:\u003c/strong>\u003c/p>\u003cp>在上述步骤环节中最不容易做到的是“自我和解”。\u003cbr>\u003c/p>\u003cp>\u003cstrong>2、引导分组讨论问题本质\u003c/strong>\u003c/p>\u003cp>好，我们有了问题，我们带着问题进一步探讨。下面请大家小组讨论一下这个问题的本质。分析一下为什么自我和解最不容易做到。过程中大家可以各自分享自己的一些实际情况进行说明。\u003c/p>\u003cp>viki组：自我和解很容易变成自我原谅，就接受现状了。（案例周边人也没成功都差不多）\u003c/p>\u003cp>引导确认：习惯了自我原谅模式，自我和解和自我找借口在操作过程中容易混淆，搞不清边界就容易接受现状，停止不前。\u003c/p>\u003cp>引导确认：自我原谅的界定是自我找借口。\u003cbr>\u003c/p>\u003cp>betty组：很难接纳已经发生的事实。\u003c/p>\u003cp>\u003cstrong>3、 明确问题本质\u003c/strong>\u003c/p>\u003cp>刚才大家针对自我和解不容易做的本质原因提出了自己的观点，进行意见统一：\u003c/p>\u003cp>本质是区分清楚自我找借口和自我和解。\u003cbr>\u003c/p>\u003cp>\u003cstrong>4\u003c/strong>\u003cstrong>、 引导分组讨论解决方案\u003c/strong>\u003c/p>\u003cp>现在我们进行下一步，请大家就这个问题的本质讨论一下，该如何解决这个问题？想想有哪些解决办法呢？给大家3分钟的时间，看可以写出来多少不同的解决方案。\u003c/p>\u003cp>\u003cstrong>5\u003c/strong>\u003cstrong>、 学习者讲解自己的成果\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>viki组：1）在外界衡量时找准参照系（比上不比下）；2）责任归属；3）固定句式（自我和解的句式）\u003cbr>\u003c/p>\u003cp>betty组：1）看是否从内因找问题；2）对发生的事情进行客观的描述（看清责任）；3）事实进行复盘\u003cbr>\u003c/p>\u003cp>邀请学习者Lance做总结：\u003c/p>\u003cp>1 找准参照系（成功的）\u003c/p>\u003cp>2 从内部找问题，明确责任归属\u003c/p>\u003cp>3 用好复盘\u003c/p>\u003cp>4 第三视角，跳出事情看问题\u003c/p>\u003cp>5 列举找借口的显性特征清单进行审视\u003cbr>\u003c/p>\u003cp>好的，非常感谢小伙伴们的群策群力，不断地深挖问题背后的原因，大家非常棒。那我们微行动学习就讨论到这里。\u003c/p>\u003cp>相信大家较好的掌握了这个方法。不过话又说回来，即便你认同了心理对照这个概念，并掌握了方法。但由于这并不是你的习惯，你还是无法很好建立精熟目标的意识。有一个方法叫事后复盘，帮助我们逐步化为己用。给大家布置一个课后作业（事后复盘）：接下来的一周刻意回顾目标不及预期的情况，把它记录下来，然后套用今天精熟目标的衍生步骤，做出积极调整。\u003cbr>\u003c/p>\u003cp>学习者Betty：\u003c/p>\u003cp>背景：上周开始坚持6点早起在朋友圈打卡，周五有位朋友在朋友圈开玩笑评论“哈哈，打完卡还能接着睡”，虽然是笑脸回复，但心里特别不舒服，这两天就没有打卡，中断了就不想继续。利用精熟目标的步骤：\u003cbr>1、描述状态：内心有些生气，比较消极不开心，就不想打卡了。\u003cbr>2、识别诱因：玩笑评论打击了积极性受，诱因可能是成就感。\u003cbr>3、自我和解：这种状态是预警信号，身体感受到了“危险”。为了不再经受类似情况，就不让你早起打卡了，本意在保护你，只是还没有找到更好办法来做到这一点。朋友圈瞎评论的多了，之前同事还提到过，何况对方可能就是随口一说并无它意。\u003cbr>4、转换视角：早起打卡是好事情，多读了2本书，是在成长进步，也是提升自己，如果坚持时间长了，这也就没啥了。\u003cbr>5、应对方案 ：下一步行动，就是继续打卡调整朋友圈可见群组缩减为家人、好朋友。\u003c/p>\u003cp>接下来我们回顾一下：今天我们的学习目标是：学习者在制定目标时，能够列举出实现目标的障碍，根据障碍制定应对计划，在目标实现过程中，建立“精熟目标”的意识，转换思维持续精进。我们写了剧本，一起解决了问题，还制定了特定的任务。期待大家能有收获和行动，以上是我今天的分享，谢谢大家。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1558876430000,"updated_at":1558876430000,"ria":true},{"id":7923,"topic":"明确目标制定行动","learn_goal":"见实录","remark":"","level":"TF3-3","duration":60,"status":30,"type":0,"chaishujia":{"username":"王蒙","city":"上海市"},"club":{"name":"上海羊角村分舵","city":"上海市"},"prologue":"\u003cp>大家好，我是王蒙。今天是我的3-3的拆书。今天的分享是目标相关，而我今天的\u003cstrong>学习目标是\u003c/strong>：\u003cstrong>学习者在制定目标是：制定目标时，能够使用执行意图,将计划转换为如果...就...句式。在执行目标时，能够使用心理对方法，列举出目标实现的障碍和愿景。\u003c/strong>&nbsp;\u003c/p>\u003cp>\u003cstrong>【事件场景】&nbsp;\u003c/strong>\u003c/p>\u003cp>&nbsp;不知道大家有没有遇到这种情况？\r\n&nbsp;\u003c/p>\u003cp>1、说好的要读半小时的书，看了下手机，结果这半个小时就交给手机了。\u003c/p>\u003cp>2、制定的节食计划，可是到了餐桌前就开始放飞自我了。\u003c/p>\u003cp>\u003cstrong>【提问】&nbsp;\u003c/strong>\u003c/p>\u003cp>大家有没有思考过，你的计划为什么难以达成呢？是因为意志力不够，还是行动力不强？为什么你会是一直是在原地打转呢？&nbsp;\u003c/p>\u003cp>\u003cstrong>【影响】&nbsp;&nbsp;\u003c/strong>\u003c/p>\u003cp>我们总是对未来有所期待，但是却总是难以达到那种期待。慢慢的我们更多的都在沉溺于制定计划的憧憬的快感中，可是面对现实的时候，却是充满了焦虑、沮丧甚至是甚至是陷入到自我怀疑。&nbsp;\u003c/p>\u003cp>\u003cstrong>【解决】&nbsp;&nbsp;\u003c/strong>\u003c/p>\u003cp>今天给大家带来的这本《成功动机与目标》能帮到你，书中介绍了制定计划的原则，对目标不同维度的认识以及达成目标的策略方法。它能帮助你找到目标的动机，以及执行目标的行动方法，让你能够制定出最终切实可行的目标。接下来我们进入到第一个片段的学习，\u003cstrong>学习目标是：在制定目标时，能够使用制定意图的方法，\u003cstrong>把行动计划转换为如果...就...句式行动计划。\u003c/strong>\u003c/strong>&nbsp;&nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":11471,"quote":"\u003cp>接下来请大家用一分钟时间阅读下拆页\u003c/p>\u003cp>在听到圣诞作文这个例子的几年后，我有幸与彼得和他的妻子——纽约大学博士后研究员——加布里埃尔·奥丁根一起工作。参与研究的还有宾夕法尼亚大学的安杰拉·达克沃思。我们想对“\u003cstrong>执行意图\u003c/strong>”进行彻底测试。我们用了出名的缺乏纪律和自制力的人群进行实验——正在放暑假的十年级学生。这些学生在即将开始的学期里都将面对“学业能力倾向初步测验”（PSAT）的考验，而他们每个人的目标都是在暑假里为测验做准备。5月时，我们给了每个学生一本模考题——其中有10套题，让他们在暑假中完成，9月份开学时上交。我们让一半学生决定了暑假做题的时间和地点（比如“平日早餐后，在我的屋子里”）。学生们在暑假期间没有得到任何提醒，那些写下了时间地点的人也把纸片上交了，自己没有留底。9月份我们把习题收回来时发现，\u003cstrong>没有做时间地点计划的学生平均完成了100道习题，而做了计划的学生平均完成了250道题\u003c/strong>！我们再次看到了成倍的效应，尽管过程持续了一整个暑假。而这成效仅仅来自我们的干预实验占用学生的一点点时间。\u003c/p>\u003cp>摘录来自: 海蒂·格兰特·霍尔沃森。《成功，动机与目标》P166-P167.\u003c/p>","explains":"\u003cp>\u003cstrong>【Why】\u003c/strong>\u003c/p>\u003cp>如果看家看完了，可以抬头示意下我。上面的片段很短。\u003c/p>\u003cp>【拆书家】：大家平常都会是制定怎么样的目标？\u003c/p>\u003cp>【学习者】：读书、写作\u003c/p>\u003cp>【拆书家】：再具体点呢？比如说量化些\u003c/p>\u003cp>【学习者】：想写5篇文章\u003c/p>\u003cp>【拆书家】：对，大多数人在制定目标的时候都是在说：我要做/要实现...，但是没有说要怎么做。比如说我要在21天学会编程，我要减肥等。而执行意图所解决的就是这个问题。\u003c/p>\u003cp>【拆书家】：大家有没有想过拆页中的实验为什么会成功呢？\u003c/p>\u003cp>【学习者】：有做时间和地点\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>是的，有了时间、地点就建立起了执行意图。那执行意图是什么呢？简单来讲就是确定完目标后，明确出它的时间、地点和行动方式。 \u003c/strong>用一个条件语句—— 为了达到这个目标，“如果…X…就…Y…”。\u003c/p>\u003cp>\u003cstrong>【澄清概念】\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>那么怎么才是好的执行意图呢？\u003c/strong>\u003c/p>\u003cp>下面我们以减肥为例：\u003c/p>\u003cp>如果只是说：我要减肥，那是执行意图吗？不是，它是目标意图。因为它没有具体的场景和事项。\u003c/p>\u003cp>如果说：要每天少吃多动，管住嘴，迈开腿去减肥。那它是执行意图吗？不是，因为计划没有包含具体的时间。\u003c/p>\u003cp>那如果说：我每周一三五，要锻炼半个小时，这是一个执行意图吗？也不是，因为没有具体的地点因素。\u003c/p>\u003cp>从上面，我们可以看出执行意图有3个很显著的特点：时间，地点和具体事项。\u003c/p>\u003cp>\u003cstrong>【HOW】【引出行动建议】\u003c/strong>\u003c/p>\u003cp>那么我们怎么来建立自己的执行意图呢？\u003c/p>\u003cp>1、 明确实现目标。\u003cstrong>(想要实现的目标) &nbsp;\u003c/strong>\u003c/p>\u003cp>2、找到关键行为。\u003cstrong>(哪些行为能达成目标)\u003c/strong>\u003c/p>\u003cp>3、转为具体方式。\u003cstrong>(行为达成的具体方式) &nbsp;\u003c/strong>\u003c/p>\u003cp>4、整理如果..就..。\u003cstrong>(针对具体行为，整理如果就...)\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【举例说明】\u003c/strong>\u003cbr>\u003c/p>\u003cp>接下来我们就举个例子吧。\u003c/p>\u003cp>在去年的时候我做了一次减肥的计划，在21天里减重了14斤。那么我是怎么做的呢？\u003c/p>\u003cp>首先我在最开始给自己制定了一个目标，减重12斤。然后继续去找减肥的关键行为有哪些？\u003c/p>\u003col>\u003cli>\u003cp>少吃\u003c/p>\u003c/li>\u003cli>\u003cp>多运动\u003c/p>\u003c/li>\u003cli>\u003cp>多喝水。\u003c/p>\u003c/li>\u003c/ol>\u003cp>紧接着我会把关键行为转为具体方式。例如少吃变为：\u003c/p>\u003cp>每天摄入热量不超过1 500卡路里。\u003c/p>\u003cp>多运动变为每周一、三、五上班前去锻炼一个小时。\u003c/p>\u003cp>多喝水变为：每天摄水量不低于1.8L。\u003c/p>\u003cp>最后把具体方式转变为如果就的句式：\u003c/p>\u003cp>如果已经吃了1 500卡路里的食物，我就不能再吃了；\u003cbr>\u003c/p>\u003cp>如果现在是星期一，我就要上班前先去运动。\u003c/p>\u003cp>如果今天下班后，我会在吃完饭后，去(黄浦江边跑半小时的步/公园20分钟跳绳)。\u003c/p>\u003cp>这样通过把大的目标进行拆解成一个小的行动，又对行为举行了具象化，从而完成了我的减重大业。\u003cstrong>【这样做的好处】\u003c/strong>\u003cbr>\u003c/p>\u003ch3>\u003cp>那么问题来了，执行意图为什么会有效呢？其实就是提前设定大脑的场景行动模式，让你一旦你进入了某个场景或者达到某种程度，就会自动启动预设的行动模式，你就只管去执行就好，你无须再与意志力搏斗也就做到了从想到做的转变。\u003c/p>\u003c/h3>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>有的小伙伴可能会问，关键行为和具体方式有些分不清楚。其实关键行为是为了达到目标你会做的一些行为，而具体方式则是指，把关键行为具象化。比如多运动，改为每天锻炼30分钟。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>当然这个方法适用于较为明确可以执行的目标，同时能够让你预设好场景，这样才能更适合执行意图。\u003c/p>","interaction":"\u003cp>在拆书帮我们提倡是学以致用，今天我们会进行一次挺有挑战的练习，也就是请大家变身为一个小编剧。接下来请大家编一段小故事。因为有一些方法，我们在实际生活中可能不太容易一下去运用，这个时候，我们可以通过编故事的方式来练习，因为在故事中一切皆有可能。接下来请大家编写一个\u003cstrong>发生在未来的小故事\u003c/strong>。\u003cstrong>请注意剧本需要包含时间、地点、人物、事件和对话情节\u003c/strong>。\u003cstrong>其中部分对话要使用上今天所学到的四个步骤\u003c/strong>。 现在请大家花5分钟的时间构思一下，并写到纸上。后面我们邀请一位同学进行分享。\u003c/p>\u003cp>【学习者】\u003c/p>\u003cp>时间：未来一个月\u003cbr>\u003c/p>\u003cp>地点：公司\u003c/p>\u003cp>人物：我和同事\u003c/p>\u003cp>情节：最近一个月听完《得到》上买的课程，由此引发的讨论\u003c/p>\u003cp>\u003cstrong>对话：\u003c/strong>\u003c/p>\u003cp>我：我想要在一个月里听完得到里买的一门课程，感觉有点难\u003c/p>\u003cp>同事：那想要听完这个课程你要做哪些事情呢？(找到关键的行为)\u003c/p>\u003cp>我：那得去听和去读专栏的文章\u003c/p>\u003cp>同事：那怎么听课程和去读专栏呢？量化点，比如说每天听多少节，读几篇专栏文章呢？(转为具体方式)\u003c/p>\u003cp>我：听两节课，读两篇文章\u003c/p>\u003cp>同事：那怎么具体去做呢？\u003c/p>\u003cp>我：如果我上班在地铁上的时候，就带上耳机听两节课程。如果晚上下班后，吃完饭我就会在书桌边读两篇专栏文章。(整理如果..就...)\u003c/p>\u003cp>\u003cstrong>【过渡】\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>执行意图是一个很好用的工具，可是这个工具真的是万能的吗？比如说我刚刚打开了一本书，可是手机响了，聊了一会天半个小时没了。想要去运动，可是下班后很累，不想去动了。这个时候，好像执行意图就不太灵了。\u003c/p>\u003cp>那要怎么解决这个问题呢？接下来我们进入第二个拆页。\u003c/p>\u003cp>\u003cstrong>学习目标是：\u003c/strong>\u003cstrong>在执行目标时，能够使用心理对方法(澄清)，\u003c/strong>\u003cstrong>列举出（行为）目标实现的障碍（界定）。\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>两个片段是一种\u003cstrong>递进关系\u003c/strong>。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":11472,"quote":"\u003cp>在开始之前，我们先做一个小测试。这里有5个题目，请按照1-5分的标准进行打分。1分代表完成不符合，5分非常符合，下面请仔细阅读，根据自己的实际情况进行打分，并在最后计算总分。时间为1分钟。\u003c/p>\u003cp>通过这个测试可以观察到我们对目标的可执行程度\u003c/p>\u003cp>大家有超过20分的吗？这个区间代表可执行的程度非常高，具备非常强的行动力；10-20分，有哪些小伙伴？这个区间代表目标具备一定的执行程度，但也有很大提升空间；5-10是低分区间的目标属于很低的执行度，很容易造成行动瘫痪。今天的片段学习可以在这方面帮到你，接下来请大家用1分钟时间来阅读原文。\u003c/p>\u003cp>\u003cstrong>【原文片段】\u003c/strong>\u003c/p>\u003cp>心理学家加布里埃尔·奥丁根大量研究了“相信自己能成功”与“相信自己能轻而易举成功”这两种不同信念对动力所产生的不同影响，屡次发现它们对成功起着极为不同的作用。比如在一项调查里，一些得肥胖症的女士参加了一个综合减肥计划，一开始奥丁根让每个人告诉她自己对成功减肥的期望值。读过我之前写的有关正面思考的内容，你听到结果一定不会惊讶：那些相信自己能减肥成功的女士比相信自己会失败的平均多减掉26磅。\u003c/p>\u003cp>不仅如此，奥丁根还调查了每个人对减肥过程的想象——她们认为怎样才能实现减肥计划。比如说，她问大家是否觉得自己可以对公司午餐室里躺着的半盒甜甜圈轻松说不。结果那些认为减肥之途会很轻松的人比认为道路崎岖的人平均少减掉24磅。奥丁根和她的同事们在各式各样的情况中都找到相同的规律：寻求高薪工作的应届毕业生、寻找伴侣建立长久关系的单身人士，还有正从髋关节置换手术康复的老人们。我们发现不论他们是谁、试图做什么，成事之人不但有信心获得成功，而且还同样相信着成功之路不会是一帆风顺的。\u003c/p>\u003cp>摘录来自: 海蒂·格兰特·霍尔沃森。《成功，动机与目标》 P24 - P25\u003c/p>","explains":"\u003cp>\u003cstrong>【why】\u003c/strong>\u003c/p>\u003cp>在上一个拆页里我们提到了执行意图，执行意图让我们从想到做。但即便运用了了如果..就的方法，可是在执行的时候依然会遇到障碍和诱惑。那么我们要怎么做呢？在拆页中提到了一个很棒的方法叫做：心理对照。\u003c/p>\u003cp>\u003cstrong>【what】\u003c/strong>\u003c/p>\u003cp>那什么是心理对照呢？\u003c/p>\u003cp>心理对照是指人们在思维过程中首先想象目标实现后的收获,然后思考现实中阻碍实现目标的因素,通过对比目标实现后的收获和现实中的障碍,使未来和现实同时通达,在未来和现实之间建立起心理联结,激活个体达成目标的期望。简单来讲就是想要的事情，要先成功了是有多爽，想过后再想想想成功会有啥影响成功。\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>\u003c/p>\u003cp>那我们如何来做好心理对照呢？\u003c/p>\u003cp>1、确认目标。想一个自己渴求的，虽有些挑战但可执行的。\u003c/p>\u003cp>2、描述愿景。目标达成的场景是什么，场景越详细越好最好要有画面感，可能是一个也可能是多个\u003c/p>\u003cp>3、罗列障碍。实现的过程中，你最担心发生的障碍有哪些。\u003c/p>\u003cp>\u003cstrong>【举例】\u003c/strong>\u003c/p>\u003cp>我们还是拿减肥为例子吧。在减肥期间，我需要每天都要进行锻炼。那么我要怎么做呢？\u003c/p>\u003cp>目标：今天的锻炼愿望：我想去锻炼半小时\u003c/p>\u003cp>结果：它能够让我明天瘦一些，体重秤会显示的很轻，可以在打卡群里收到点赞\u003c/p>\u003cp>障碍：下班后很累，加班，无法瘦下来\u003c/p>\u003cp>通过针对障碍和结果的对比，在我遇到障碍的使用，激发我的行动力，让我对目标的实施充满了信心。也就瘦了下来。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>可能会有小伙伴会问：为什么要描述愿景呢？其实描述愿景的目的是明确为什么要做这个目标，它是你的动力，也是诱惑你完成目标，克服障碍的动力。而把画面感描述的更为清晰，也同样为如此。\u003c/p>\u003cp>那么结果的诱惑不足以克服障碍怎么办呢？如果是这种情况，我建议你来修订目标，因为它不属于心理对照的适用范围。\u003c/p>","interaction":"\u003cp>【A3微行动步骤】\u003c/p>\u003cp>刚刚都是我在说，接下来希望和大家一起来开始我们的探索和分析。\u003c/p>\u003cp>1 、明确问题\u003c/p>\u003cp>【拆书家】在刚刚的心理对照的方法中，大家有什么问题吗？或者说那么大家觉得结合到大家的过往经验中，大家觉得这个方法中哪一个步骤最难呢？\u003c/p>\u003cp>【学习者】：明确目标\u003c/p>\u003cp>\u003cstrong>2、讨论问题的本质\u003c/strong>\u003c/p>\u003cp>【拆书家】：大家都赞同吗？\u003c/p>\u003cp>【学习者】：赞同\u003c/p>\u003cp>【拆书家】我们难以达成这个目标，它的本质的问题是什么\u003c/p>\u003cp>【拆书家】接下来，请大家在小组内讨论，难以达成这个目标的原因是什么？即这个问题的本质是什么？讨论时请结合自己过往的经验。\u003c/p>\u003cp>【学习者】明确目标比较难的本质：\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;1、目标设计的不是很清晰，就是不知道我为甚要做和怎么去做\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;2、目标是不是有弹性，比如说完成到70%是不是就可以了。\u003c/p>\u003cp>\u003cstrong>3、 明确问题本质\u003c/strong>\u003c/p>\u003cp>【拆书家】：我们得到了两个本质的原因，一个是不清晰，一个是否有弹性。那是不是可以总结为不知道做什么和怎么做以及做到什么程度。那么大家是否认为这都属于目标不清晰呢？大家赞同吗？\u003c/p>\u003cp>【学习者】：赞同\u003c/p>\u003cp>【拆书家】：这个本质问题大家都认同么？有没有补充？\u003c/p>\u003cp>【学习者】：没有\u003c/p>\u003cp>\u003cstrong>4、 分组讨论解决方案\u003c/strong>\u003c/p>\u003cp>【拆书家】现在我们进行下一步，请大家就这个问题的本质讨论一下，运用到今天我们所学习到的方法，该如何解决这个问题？会有哪些的解决方案。请大家把各组的方案写在便签上。给大家5分钟的时间。\u003c/p>\u003cp>\u003cstrong>5、 展示学习成果\u003c/strong>\u003c/p>\u003cp>【学习者】：\u003c/p>\u003cp>我的之前的目标是要早起，可是我不知道早晨起来要做什么？所以我会想我为什么想要早起，是因为有了宝宝后没有了个人时间，通过愿景找到我早起是为了多一些个人时间。那我的障碍是我想要更多的睡眠，所以我的解决方法是约朋友到小花园去跑操，所以我会写下如果今天早晨6点起来，我就会去小花园跑操。\u003c/p>\u003cp>所以我的方法是根据上面两个拆页的结合是不是可以这样：\u003c/p>\u003cp>1、先找到想要做的目标\u003c/p>\u003cp>2、再写下做这件事的愿景，通过愿景来找到为什么做它\u003c/p>\u003cp>3、然后再写下做这件事情会有什么障碍\u003c/p>\u003cp>4、最后再用如果...就...的去完成它。\u003c/p>\u003cp>【拆书家反馈】感谢你的分享，我们要先想明白自己为什么做，清晰怎么去做，非常棒的一个分享。\u003c/p>\u003cp>\u003cstrong>【A2：布置任务】（特定任务）\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>谢谢大家的互动，接下来我给大家布置一个任务。心理对照个非常好用的工具，在我们的生活中也非常的适用。在接下来的一周里，你会把这个方法分享给谁，从而让他更好的达成他的目标呢？\u003c/p>\u003cp>【学习者】：会分享给我老公\u003cbr>\u003c/p>\u003cp>【拆书家】：谢谢，也希望这个方法能够帮助到他。\u003c/p>\u003cp>\u003cstrong>【总结】\u003c/strong>\u003c/p>\u003cp>好的，我们总结今天的内容。我们在第一个拆页学习到了执行意图，用来帮助我们从想到做的转变。在第二个拆页中，我们解决了在执行目标当中的遇到诱惑或者障碍的问题，从而帮助我们更好的达成目标。我们经常说，人要仰望星空，才会觉得生活有奔头，也要脚踏实地，才不至于让自己迷失在幻想中。今天的分享就是希望帮助大家能够既能仰望天空，又能脚踏实地。希望今天的分享能对大家有所收获。谢谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1558247926000,"updated_at":1558248102000,"ria":true},{"id":7879,"topic":"目标实现。","learn_goal":"见实录内","remark":"","level":"TF3-3","duration":60,"status":29,"type":0,"chaishujia":{"username":"王蒙","city":"上海市"},"club":{"name":"上海申展分舵","city":"上海市"},"prologue":"\u003cp>今天是我的3-3的拆书，分享是目标相关，学习目标是：\u003cstrong>学习者在制定目标时，把行动计划转换为如果...就...句式行动计划。在执行实施目标的时候，能够列举出实现目标的的愿景和障碍。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【事件场景】\u003c/strong>\u003c/p>\u003cp>不知道大家有没有遇到这种情况？\u003c/p>\u003cp>1. 说好的要读半小时的书，看了下手机，结果这半个小时就交给手机了。\u003c/p>\u003cp>2. 制定的节食计划，可是到了餐桌前就开始放飞自我了。\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>\u003c/p>\u003cp>大家有没有思考过，你的计划为什么难以达成呢？是因为意志力不够，还是行动力不强？为什么你会是一直是在原地打转呢？\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>\u003c/p>\u003cp>我们总是对未来有所期待，但是却总是难以达到那种期待。慢慢的我们更多的都在沉溺于制定计划的憧憬的快感中，可是面对现实的时候，却是充满了焦虑、沮丧甚至是甚至是陷入到自我怀疑。\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>\u003c/p>\u003cp>今天给大家带来的这本《成功动机与目标》能帮到你，书中介绍了制定计划的原则，对目标不同维度的认识以及达成目标的策略方法。它能帮助你找到目标的动机，以及执行目标的行动方法，让你能够制定出最终切实可行的目标。接下来我们进入到第一个片段的学习，学习目标是：学习者在制定目标时，把行动计划转换为如果...就...句式行动计划。\u003c/p>","ratings_count":1,"texts":[{"id":11422,"quote":"\u003cp>这些计划的美好在于简单。你找到一个想去实现的目标，说清达成它的具体时间、地点和方式。比如，就拿之前的减肥目标举例。第一步，应该把“少吃”改为“每天摄入热量不超过1 500卡路里”；第二步，“多运动”应该变成“每周一、三、五上班前去健身房锻炼一个小时”。戈尔维策把这类计划叫做“建立执行意图”，听上去挺拗口，实际就是指一种“如果……就……”的计划方式：如果已经吃了1 500卡路里的食物，我就不能再吃了；如果现在是星期一早晨，我就要上班前先去运动。\u003c/p>\u003cp>摘录来自: 海蒂·格兰特·霍尔沃森。《成功，动机与目标》P165-P166.\u003c/p>","explains":"\u003cp>\u003cstrong>【Why】\u003c/strong>\u003c/p>\u003cp>如果看家看完了，可以抬头示意下我。上面的片段很短。\u003c/p>\u003cp>【拆书家】：大家平常都会是制定怎么样的目标？\u003c/p>\u003cp>【小美】：减肥、读书\u003c/p>\u003cp>【拆书家】：再具体点呢？比如说量化些\u003c/p>\u003cp>【小美】：比如今年我想读10本书。\u003c/p>\u003cp>嗯，是的。其实大多数人在制定目标的时候，使用的是目标意图，也就是说：我想要做/要实现...，但是没有说要怎么做。比如说我要在21天学会编程，我要减肥等。而执行意图所解决的就是这个问题。\u003cbr>\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>\u003c/p>\u003cp>那执行意图是什么呢？简单来讲就是确定完目标后，明确出它的时间、地点和行动方式。 用一个条件语句—— 为了达到这个目标，“如果…X…就…Y…”。\u003c/p>\u003cp>那么什么才是好的执行意图呢？\u003cstrong>【澄清概念】\u003c/strong>\u003c/p>\u003cp>下面我们以减肥为例：\u003c/p>\u003cp>如果只是说：我要减肥，那是执行意图吗？不是，它是目标意图。因为它没有具体的场景和事项；如果说：要每天少吃多动，管住嘴，迈开腿去减肥。那它是执行意图吗？不是，因为计划没有包含具体的时间；那如果说：我每周一三五，要锻炼半个小时，这是一个执行意图吗？也不是，因为没有具体的地点因素。\u003c/p>\u003cp>从上面，我们可以看出执行意图有3个很显著的特点：时间，地点和具体事项。\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>\u003c/p>\u003cp>那么我们怎么来建立自己的执行意图呢？\u003c/p>\u003cp>1、 明确实现目标。(想要实现的目标)&nbsp;\u003c/p>\u003cp>2、找到关键行为。(哪些行为能达成目标)\u003c/p>\u003cp>3、转为具体方式。(行为达成的具体方式)&nbsp;\u003c/p>\u003cp>4、整理如果..就..。(针对具体行为，整理如果就...)\u003c/p>\u003cp>\u003cstrong>【举例说明】\u003c/strong>\u003c/p>\u003cp>接下来我们就举个例子吧。\u003c/p>\u003cp>在去年的时候我做了一次减肥的计划，在21天里减重了14斤。那么我是怎么做的呢？\u003c/p>\u003cp>首先我在最开始给自己制定了一个目标，减重12斤。然后继续去找减肥的关键行为有哪些？\u003c/p>\u003cp>少吃\u003c/p>\u003cp>多运动\u003c/p>\u003cp>多喝水。\u003c/p>\u003cp>紧接着我会把关键行为转为具体方式。例如少吃变为：\u003c/p>\u003cp>每天只能吃蔬菜;多运动变为每周一、三、五上班前去锻炼一个小时;多喝水变为：每天摄水量不低于1.8L。\u003c/p>\u003cp>最后把具体方式转变为如果就的句式：\u003c/p>\u003cp>如果今天的中午在公司吃饭的时候，菜里有肉，那我就只吃蔬菜；如果今天是星期一，下班后，我会在吃完饭后，去(黄浦江边跑半小时的步/公园20分钟跳绳)。；\u003c/p>\u003cp>这样通过把大的目标进行拆解成一个小的行动，又对行为举行了具象化，从而完成了我的减重大业。\u003c/p>\u003cp>\u003cstrong>【这样做的好处】\u003c/strong>\u003c/p>\u003cp>那么问题来了，执行意图为什么会有效呢？其实就是提前设定大脑的场景行动模式，让你一旦你进入了某个场景或者达到某种程度，就会自动启动预设的行动模式，你就只管去执行就好，你无须再与意志力搏斗也就做到了从想到做的转变。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>有的小伙伴可能会问，关键行为和具体方式有些分不清楚。其实关键行为是为了达到目标你会做的一些行为，而具体方式则是指，把关键行为具象化。比如多运动，改为每天锻炼30分钟。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>当然这个方法适用于较为明确可以执行的目标，同时能够让你预设好场景，这样才能更适合执行意图。\u003c/p>","interaction":"\u003cp>在拆书帮我们提倡是学以致用，今天我们会进行一次挺有挑战的练习，也就是请大家变身为一个小编剧。接下来请大家编一段小故事。因为有一些方法，我们在实际生活中可能不太容易一下去运用，这个时候，我们可以通过编故事的方式来练习，因为在故事中一切皆有可能。接下来请大家编写一个发生在未来的小故事。请注意剧本需要包含时间、地点、人物、事件和对话情节。其中部分对话要使用上今天所学到的四个步骤。 现在请大家花5分钟的时间构思一下，并写到纸上。后面我们邀请一位同学进行分享。\u003c/p>\u003cp>【学习者：文哥】\u003cbr>\u003c/p>\u003cp>时间：未来一个月\u003cbr>\u003c/p>\u003cp>地点：家中\u003c/p>\u003cp>人物：我和老婆\u003c/p>\u003cp>情节：最近一个月老婆想要考项目经理，但是老婆没有信心完成，由此引发的讨论\u003c/p>\u003cp>对话：\u003c/p>\u003cp>老婆：马上就要考试了，可是我现在还没准备好。不知道能不能考过\u003c/p>\u003cp>我：那你是不是该想想要做些什么，才能帮助你考试呢？(找到关键行为)\u003c/p>\u003cp>老婆：必须得要听课程和做题。\u003c/p>\u003cp>我：好，现在知道听课和做题了，那怎么听课和做题呢？量化点，比如说每天听多少课，做多少题(转为具体方式)\u003c/p>\u003cp>老婆：看现在时间，每天得上3节课也要做1套题。\u003c/p>\u003cp>我：那怎么具体去做呢？\u003c/p>\u003cp>老婆：如果今天是周x，我就会在上班通勤路上看两节课程。如果今天下班后，我到家里晚上十点我就做一套试题。(整理如果..就...)\u003c/p>\u003cp>\u003cstrong>【过渡】\u003c/strong>\u003c/p>\u003cp>执行意图是一个很好用的工具，可是这个工具真的是万能的吗？比如说我刚刚打开了一本书，可是手机响了，聊了一会天半个小时没了。想要去运动，可是下班后很累，不想去动了。这个时候，好像执行意图就不太灵了。\u003c/p>\u003cp>那要怎么解决这个问题呢？接下来我们进入第二个拆页。\u003c/p>\u003cp>学习目标是：在执行目标的时候，能够列举出实现目标的障碍，根据障碍制定对应的对策。\u003c/p>\u003cp>两个片段是一种递进关系。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":11423,"quote":"\u003cp>在开始之前，我们先做一个小测试。这里有5个题目，请按照1-5分的标准进行打分。1分代表完成不符合，5分非常符合，下面请仔细阅读，根据自己的实际情况进行打分，并在最后计算总分。时间为1分钟。\u003c/p>\u003cp>通过这个测试可以观察到我们对目标的可执行程度\u003c/p>\u003cp>大家有超过20分的吗？这个区间代表可执行的程度非常高，具备非常强的行动力；10-20分，有哪些小伙伴？这个区间代表目标具备一定的执行程度，但也有很大提升空间；5-10是低分区间的目标属于很低的执行度，很容易造成行动瘫痪。今天的片段学习可以在这方面帮到你，接下来请大家用1分钟时间来阅读原文。\u003c/p>\u003cp>那么怎样才能最好地树立并实现目标而不是活在白日梦中呢？最佳策略是用乐观的方式看待目标，同时用实际的方式思考具体需要做什么才能实现目标。奥丁根把它叫做“心理对照”——首先你得能想到目标的实现，然后再反思其中的障碍。如果你大学毕业想找份高薪工作，首先要能想象自己被一家顶级公司录用，然后再考虑你和这个目标之间存在什么障碍——比如其他优秀的应聘者。这就使你不得不寄出很多份申请，不是吗？这就叫做：感受“行动的必要性”——这是实现目标所需的关键心理状态。幻想找到份好工作或者与倾心已久的人坠入爱河是件很有趣的事，只不过你不会因此取得任何实际进展。心理对照能引导我们聚焦于必要的行动，从而把愿望和白日梦转化为现实。\u003c/p>\u003cp>摘录来自: 海蒂·格兰特·霍尔沃森。《成功，动机与目标》 P24 - P25\u003c/p>","explains":"\u003cp>【what】\u003c/p>\u003cp>在上一个拆页里我们提到了执行意图，执行意图让我们从想到做。但即便运用了了如果..就的方法，可是在执行的时候依然会遇到障碍和诱惑。那么我们要怎么做呢？在拆页中提到了一个很棒的方法叫做：心理对照。\u003c/p>\u003cp>心理对照是指人们在思维过程中首先想象目标实现后的收获,然后思考现实中阻碍实现目标的因素,通过对比目标实现后的收获和现实中的障碍,使未来和现实同时通达,在未来和现实之间建立起心理联结,激活个体达成目标的期望。简单来讲就是列出可能障碍，遇到的时候想想为啥做，然后再解决障碍。\u003c/p>\u003cp>那么我们要怎么来做心理对照呢？\u003c/p>\u003cp>【HOW】\u003c/p>\u003cp>那我们如何来做好心理对照呢？\u003c/p>\u003cp>1、确认目标。想一个自己渴求的，虽有些挑战但可执行的。\u003c/p>\u003cp>2、描述愿景。目标达成的场景是什么，场景越详细越好最好要有画面感，可能是一个也可能是多个\u003c/p>\u003cp>3、罗列障碍。实现的过程中，你最担心发生的障碍有哪些。\u003c/p>\u003cp>【举例】\u003c/p>\u003cp>我们还是拿减肥为例子吧。在减肥期间，我需要每天都要进行锻炼。那么我要怎么做呢？\u003c/p>\u003cp>目标：今天的锻炼愿望：我想去锻炼半小时\u003c/p>\u003cp>结果：它能够让我明天瘦一些，体重秤会显示的很轻，可以在打卡群里收到点赞\u003c/p>\u003cp>障碍：下班后很累，加班，无法瘦下来\u003c/p>\u003cp>通过针对障碍和结果的对比，在我遇到障碍的使用，激发我的行动力，让我对目标的实施充满了信心。也就瘦了下来。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>可能会有小伙伴会问：为什么要描述愿景呢？其实描述愿景的目的是明确为什么要做这个目标，它是你的动力，也是诱惑你完成目标，克服障碍的动力。而把画面感描述的更为清晰，也同样为如此。\u003c/p>\u003cp>那么结果的诱惑不足以克服障碍怎么办呢？如果是这种情况，我建议你来修订目标，因为它不属于心理对照的适用范围。\u003c/p>","interaction":"\u003cp>刚刚都是我在说，接下来希望和大家一起来开始你们的探索和分析。\u003c/p>\u003cp>1 、明确问题\u003c/p>\u003cp>在刚刚的心理对照的方法中，大家有什么问题吗？或者说那么大家觉得结合到大家的过往经验中，大家觉得这个方法中哪一个步骤最难呢？\u003c/p>\u003cp>【学习者】：描述愿景\u003c/p>\u003cp>2、讨论问题的本质\u003c/p>\u003cp>【拆书家】：大家都赞同吗？\u003c/p>\u003cp>【学习者】：赞同\u003c/p>\u003cp>好，既然大家都赞同。那么下面请大家一起来讨论一下这个问题的本质。请大家各自在小组内讨论。给大家的3分钟的时间。\u003c/p>\u003cp>【文哥】：我们组的结论是：愿景很虚，不够量化。\u003c/p>\u003cp>【小美】：我们组的结论是：愿景可能会随目标而变化。\u003c/p>\u003cp>3、 分组讨论解决方案\u003c/p>\u003cp>我们得到了两个本质问题，一个是不够量化，一个是会变化。这个本质问题大家都认同吗？有没有补充？\u003c/p>\u003cp>【学习者】：没有\u003c/p>\u003cp>4、分组讨论解决方案\u003cbr>\u003c/p>\u003cp>现在我们进行下一步，请大家就这个问题的本质讨论一下，该如何解决这个问题？想想有哪些解决办法呢？给大家3分钟的时间，看可以写出来多少不同的解决方案。\u003c/p>\u003cp>5、 展示学习成果\u003c/p>\u003cp>【文哥】：\u003cbr>\u003c/p>\u003cp>我们认为愿景不够量化，所以我们的出发点就是让它尽量量化出来。所以我们的提出以下几个：\u003c/p>\u003cp>1、明确目标，也就是我们真正想做的是什么？\u003c/p>\u003cp>2、描述好处，知道为什么要做，做了它能我们带来哪些好处。\u003c/p>\u003cp>3、做出承诺，把愿景说出来，保证能做到。\u003c/p>\u003cp>4、找人监督，对承诺的进行监督。\u003c/p>\u003cp>5、细化方法，根据上面提到方法再计划。\u003c/p>\u003cp>【拆书家反馈】感谢文哥的分享，很棒的方法，希望这个方法能够解决你的问题。\u003c/p>\u003cp>\u003cstrong>【A2：布置任务】（特定任务）\u003c/strong>\u003c/p>\u003cp>谢谢大家的互动，接下来我给大家布置一个任务。心理对照个非常好用的工具，在我们的生活中也非常的适用。在接下来的一周里，你会把这个方法分享给谁，从而让他更好的达成他的目标呢？\u003c/p>\u003cp>【一梅】：会分享给团队里的核心成员和我的舍友。\u003cbr>\u003c/p>\u003cp>【拆书家】：谢谢，也希望这个方法能够帮助到他们。\u003c/p>\u003cp>\u003cstrong>【总结】\u003c/strong>\u003c/p>\u003cp>好的，我们总结今天的内容。我们在第一个拆页学习到了执行意图，用来帮助我们从想到做的转变。在第二个拆页中，我们解决了在执行目标当中的遇到诱惑或者障碍的问题，从而帮助我们更好的达成目标。我们经常说，人要仰望星空，才会觉得生活有奔头，也要脚踏实地，才不至于让自己迷失在幻想中。今天的分享就是希望帮助大家能够既能仰望天空，又能脚踏实地。希望今天的分享能对大家有所收获。谢谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1557740532000,"updated_at":1557971896000,"ria":true},{"id":7551,"topic":"目标实现~","learn_goal":"见开场部分","remark":"","level":"TF3-3","duration":60,"status":0,"type":0,"chaishujia":{"username":"赵自力","city":""},"club":{"name":"上海申展分舵","city":"上海市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，我是Jack，稍后会有小组讨论，我们先分一下组。 \r\n【学习目标】学习者在制定目标时，能够列举出实现目标的障碍，根据障碍制定应对计划，在目标实现过程中，建立“精熟目标”的意识，转换思维持续精进。\r\n【场景法图书介绍】\r\n【事件场景】大家有没有这样的一些体验？想搞定大客户证明自己结果临门一脚客户说走就走，备受打击；想要考取资格证书结果一拖再拖，用到时后悔不已。年初为定好的新年目标兴奋不已摩拳擦掌，年终唉声叹气责怪自己；5年前就想学的吉他现在还是不会，偶尔还会想起2年前脑袋一热办的3年期健身卡。\r\n【提问】有没有太扎心了？有没有想过，都说心想事成，目标明明是自己的渴求况且并非不可实现，为什么到现在还未曾拥有？\r\n【影响】我们对目标实现的状态满是憧憬，这可以给我们带来十足的动力和干劲，却又时常感受不到行动的必要性和紧迫性，成为“思想上的巨人，行动上的矮子”。更严重的是当我们付诸行动却发现离预期结果相去甚远，沮丧，中途放弃，想要却得不到满是焦虑。\r\n【解决】今天给大家带来的这本《成功动机与目标》能帮到你，书中介绍制定目标的原则，对目标不同维度的认识以及达成目标的策略方法，帮你将目标与现实链接在一起，在认知层面上做好实现目标的准备，在行动上制定相应策略，最终实现切实可行的目标。\r\n接下来我们进入到第一个片段的学习，学习目标是学习者在制定目标时，能够列举出实现目标的障碍，根据障碍制定应对计划。请大家用一分钟的时间阅读原文。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":0,"texts":[{"id":11028,"quote":"\u003cp>那么怎样才能更好地树立并实现目标而不是活在白日梦中呢？最佳策略是用乐观的方式看待目标，同时用实际的方式思考具体需要做什么才能实现目标。奥丁根把它叫做“心理对照”——首先你得能想到目标的实现，然后再反思其中的障碍。如果你大学毕业想找份高薪的工作，首先要能想象自己被一家顶级公司录用，然后再考虑你和这个目标之间存在什么障碍——比如其他优秀应聘者。这就使你不得不寄出很多份申请，不是吗？这就叫做：感受“行动的必要性”——这是实现目标所需的关键心理状态。幻想找到份好工作或者与倾心以久的暗恋对象坠入爱河是件很有趣的事，只不过你不会因此取得任何实际进展。心理对照能引导我们聚焦于必要的行动，从而把愿望和白日梦转化为现实。\u003c/p>","explains":"\u003cp>【简短互动】【明确核心概念】\u003c/p>\u003cp>1、请问大家片段中有一个概念，它是什么？\u003c/p>\u003cp>学习者：心理对照\u003c/p>\u003cp>回应：直中标靶，非常赞。\u003c/p>\u003cp>2、作者介绍这个概念是为了解决什么问题？\u003c/p>\u003cp>学习者：目标的实现\u003c/p>\u003cp>回应：重复学习者发言（目标的实现）更好树立目标感受行动必要性。\u003c/p>\u003cp>3、针对这种问题，作者介绍的方法是什么？\u003c/p>\u003cp>学习者：首先你得能想到目标的实现，然后再反思其中的障碍。\u003cbr>\u003c/p>\u003cp>回应：是。也就是将目标实现和现实阻碍对峙。\u003c/p>\u003cp>以上是整个片段的核心，我稍微做个具象的解读，它是指个体首先想象目标实现的愿景，比如超额完成年度业绩指标带全家老小马尔代夫游，然后思考现实过程中阻碍目标实现的因素，比如客户量小、转化率低等。通过对比目标实现的愿景和现实障碍，链接未来和现实，进一步将障碍和克服障碍的行动之间建立联系。\u003c/p>\u003cp>【概念举例往返】接下来我们通过例子来看一下。\u003c/p>\u003cp>员工被洗脑边挥拳头边跺脚扯着嗓子喊“相信自己我可以！我可以！！可以…”这种口号式目标能做出心理对照吗？学习者：不能，回应：对的，目标不具象，愿景也无从谈起。\u003c/p>\u003cp>小明去年跑半程马拉松今年目标完成全马，到时同事夸赞还能博女神关注想想就美，有目标有愿景，但这算是心理对照吗？学习者：没有，没有预想现实中的障碍。回应：是的，只有愿景没有障碍，以为很轻松感受不到规律训练的必要性。\u003c/p>\u003cp>我有位工作非常努力的朋友目标是再升一职，这样可以带团队、薪资增长还可以买车。他也想到了最坏的结果不升职被外派到子公司。大家注意这个是心理对照吗？（部分学习者摇头，部分点头）。【概念比对】这有一个非常容易混淆的概念叫“防御性悲观”个体在面临新的类似成功情境时反复思考事情的各种可能结果放低期望值。两者最大的区别是防御性悲观偏重对结果的低预期设想，心理对照强调过程实现中的障碍。如果我那位朋友想到了工作业绩还不太够份量，团队影响力小等阻碍因素，这就进入心理对照的轨道，进而可以在障碍和克服障碍的行动之间建立联系。\u003c/p>\u003cp>【HOW】【引出行动建议】\u003c/p>\u003cp>那我们如何来做好心理对照呢？和大家分享四个步骤总结为WOOP：\u003c/p>\u003cp>1、W：确认目标。想一个自己渴求的，虽有些挑战但可执行的。\u003c/p>\u003cp>2、O：描述愿景。描述出目标达成之后的结果，思想自由驰骋尽量生动形象。\u003c/p>\u003cp>3、O：设想障碍。对相关情况和经历展开想象，外部探寻，内部深挖。\u003c/p>\u003cp>4、P：执行意图。要克服或规避障碍的话，你能怎么做？想象障碍可能出现的时间地点和可能情况，制定出一个“如果……那么……”的计划。\u003c/p>\u003cp>【举例说明】\u003c/p>\u003cp>简单介绍背景：18年11月初我正式加入拆书帮开始拆书升级，希望能在19年5月份成为三级拆书家。一开始感觉还有七八个月呢不着急，就拖呀拖，拖到自己心里犯嘀咕。特别幸运的是，当时接触到这本书了解了这个概念，连接到自己拆书升级。得益于心理对照和衍生的四个步骤，感受到了紧迫感和必要性，一周一拆书，一直在行动.我是怎么做的呢？\u003c/p>\u003cp>1、W：写下目标。19年5月份成为三级拆书家。\u003c/p>\u003cp>2、O：描述愿景。逐步接触到培训这样我就覆盖到了人力的全模块为工作赋能，为HRD更进一步；小成本尝试自己各种可能性，发现人生志趣；打开了弱联系圈层，开拓视野格局等等。\u003c/p>\u003cp>3、O：设想障碍。3个关键障碍1）经常加班时间冲突；2）要通关手册近40个技能点；3）被挂现场难堪要面子伤自尊不去了。\u003c/p>\u003cp>4、P：执行意图。如果晚上加班那么明天早起写预备表，早出发1小时避免拥挤利用好通勤时间；如果碰到技能点问题就结合实录理解学习还有请教师父；要面子不去了那么就关注过程中的收获和进步，突破了舒适区，是一个很好的学习机会。（第二个片段我们会进一步学习）\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>这个方法适用于较为明确的可执行的目标，同时也要有一定的挑战性，对于几乎没有挑战性的目标意义不大。\u003c/p>","interaction":"\u003cp>【学习者编剧本】\u003c/p>\u003cp>在咱们拆书帮提倡是学以致用，研究成果也表明在大脑中过一遍等于实际应用了一遍。接下来我们来演练一下。以小组为单位，展开充分的想象，编一个小剧本，描述一段发生于未来的小故事，设计出时间、地点、人物、情节（包括：起因、经过、结果）和双方的对话、动作等，其中部分对话使用心理对照四个步骤，时间5分钟，请讨论稍后我们请小伙伴做分享。\u003c/p>\u003cp>学习者祥凯：\u003c/p>\u003cp>时间：未来两三年（此处对时间理解有误）\u003cbr>\u003c/p>\u003cp>地点：家中\u003c/p>\u003cp>人物：我和老婆\u003c/p>\u003cp>情节：因为目前做体制内公务员比较清闲，不想一直这么虚耗下去，未来两三年通过司法考试，所以和老婆进行讨论\u003c/p>\u003cp>对话：\u003c/p>\u003cp>老婆：你为什么要确认这个目标？\u003c/p>\u003cp>我：有律师资格证在未来职业选择上更有选择权\u003c/p>\u003cp>老婆：目标达成后能做什么？（询问愿景）\u003c/p>\u003cp>我：职业选择性更大，不做公务员可以做销售可以做培训更可以做律师，另一个角度还在做公务员方便考取在职研究生（描述愿景）\u003c/p>\u003cp>老婆：那你会有什么障碍呢？（询问障碍）\u003c/p>\u003cp>我：现在有小宝宝要放很大精力，工作忙起来会有时间冲突（描述障碍）\u003c/p>\u003cp>老婆：既然你有这么多障碍怎么去执行呢？（询问计划）\u003c/p>\u003cp>我：如果时间不够用那么就利用午休的2个小时，回家可以分配时间和老婆互相分工。（应对计划执行意图）\u003c/p>\u003cp>【过渡】\u003cbr>\u003c/p>\u003cp>还记得我们第一个片段的学习目标吗？在制定目标时，能够列举出实现目标的障碍，根据障碍制定应对计划。三个关键词：目标、障碍、计划。有了障碍和计划我们为之付诸行动。但在目标实现过程中，并非一帆风顺。接下来我们进入第二个片段的学习。学习目标是：在目标实现过程中，完成度不及预期时，建立“精熟目标”的意识，转换思维持续精进。两个片段是一种递进关系。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":11029,"quote":"\u003cp>心理学家把发展或增强某种技术和能力的意愿称作“精熟目标”（成长进步）。当人们在追求精熟目标时，他们不因是否达到特定结果而评断自己——比如成绩全A或超越销售目标。取而代之，他们用“进步”来评断自己。我有进步吗？我在学东西吗？我前进的速度适当吗？重点不是一次的表现，而是长期表现。这种目标是以完全不同的方式与自我价值关联起来的，因为它们着重于自我提升而不是自我肯定。这种目标关系到你是否做出了最大努力成为最好最有能力的自己，而不是证明你已经是最好的了。\u003c/p>\u003cp>当我们追求精熟目标（“成长进步”）时，我们比较不会因为困难和差强人意的成绩而埋怨自己缺乏能力，因为这样做根本没有道理。我当然目前缺乏能力了——我还没掌握它啊！我们会找更可控的原因。我学习够下功夫吗？我是否应该换个战略？我是否应该找个高手请教一下？当人们在追求“进步”的路上遇到困难时，他们不会像追求“表现”的人那样沮丧和无助，他们会做出行动。他们问自己哪里出了错然后去修复。如果我的第一个考试只得了C，我会用双倍的时间并且换一种方式学习，比如用记忆卡或自己列大纲。如果我没有达到销售目标，我会认真向公司中资深的销售人员讨教。如果我的邻居对我不感兴趣，我会想想如何吸引他的注意并增强相互的了解。如果我第一次没有考进法学院，我会向法学院教授或招生办公室咨询意见，看看在重考时如何让自己更有竞争力。“进步”目标有时能带来最大的成就，因为把注意力集中在“进步”上的人很少会过早放弃。\u003c/p>","explains":"\u003cp>在开始之前我们先做一个小测试，有5个题目，请按照1-6分的标准给自己打分，1分代表完全不符合，6分代表非常符合。仔细阅读，根据自己的实际情况为自己打分，并在最后计算总分，时间为1分钟。\u003c/p>\u003cp>通过这个测试可以观察到你注重成长进步的程度。大家有超过25分的吗？这个高分区间代表注重程度非常高，具备典型的成长进步型思维，关注能收获什么，在完成目标过程中能够坚韧不拔，持续精进；10-20分是中间区间，有一定成长进步的意识，但也有很大提升空间；5-10是低分区间多会倾向证明自己，而不是关注能学到什么，一旦失败落差会特别大，容易中途放弃。不管属于哪个区间，接下来的片段学习可以帮到你。好则强化不足则改进。接下来请大家用1分钟时间来阅读原文。\u003cbr>\u003c/p>\u003cp>【WHAT】【简短互动】\u003c/p>\u003cp>片段中提到注重成长进步的精熟目标，我们从它的特征入手来理解它。\u003c/p>\u003cp>大家看追求精熟目标的人有什么特征？\u003c/p>\u003cp>（不因是否达到特定结果而评断自己，而是用“进步”来）还有吗？（自我提升而不是自我肯定）（长期）此处现场一起分步骤填表格。非常不错。这个时候我们看另外一个概念叫“绩效目标”是指注重表现的意愿，它有什么特征呢，同样的一个表格我们一起区分看一下。\u003c/p>\u003cp>请问销售100万业绩、考试年级第一、超过同事A，这是在注重什么？（表现）工作生活中有太多这样的目标，有的是外界强加，有的是自身诉求。在这种非赢即输的情况，如果不及预期大家真实的感受是怎样的？\u003c/p>\u003cp>（感觉很糟，焦虑、沮丧，难堪，耻辱，自我价值感和自尊心受到折磨。自我怀疑，我不行）特别看重“表现”后果是什么？一蹶不振，停止尝试，中途放弃，注定失败。建立了“精熟目标”意识呢？看重成长进步，关注自己在过程中的收获与提升，然后做出行动。你会发现具备精熟目标意识能带来许多积极的结果，比如说正向看待失败，在失败面前坚持不懈，喜欢有挑战性的任务，激发内部动机。那么如何建立“精熟目标”也就是成长进步这种意识呢？\u003c/p>\u003cp>【how】\u003c/p>\u003cp>1、描述感受。当下感受是什么？是不是自我埋怨，沮丧，自我怀疑？\u003c/p>\u003cp>2、宽慰自己。参考句式“我只是个凡人，凡事都要有个过程，我尊敬的XX也都经历过同样的挣扎，这很正常。”\u003c/p>\u003cp>3、转换视角。有没有成长进步，有没有提升自己，长期来看会怎样？\u003c/p>\u003cp>4、应对方案。发现问题，制定下一步行动方案。\u003c/p>\u003cp>【举例说明】\u003c/p>\u003cp>上个片段我提到5月份成为三级拆书家。但是在付诸行动的过程中，拆书的难度超出预期，找拆页，被打回，重找。写预备表，被打回，重写。关键还有现场忘词等等一系列临时情况，经常被批的一无是处，多没面子啊很难堪，技不如人算了算了\u003c/p>\u003cp>如果不建立“精熟目标”的意识，很难拆到现在。怎么做的呢？\u003c/p>\u003cp>1、描述感受：找拆页被打回，自我埋怨找个拆页都这么费劲，忘词尴尬有些难堪，自尊心像容嬷嬷连扎了几下。\u003c/p>\u003cp>2、宽慰自己。我只是个凡人，凡事都要有个过程，我接触到的三级拆书家也都经历过同样的挣扎，这很正常。\u003c/p>\u003cp>3、转换视角。有没有成长进步，有没有在提升自己，长期会怎样？\u003c/p>\u003cp>4、应对方案。我发现学习者对案例不太感冒，我要向师父讨教一下如何讲好故事。\u003c/p>","interaction":"\u003cp>【微行动步骤】\u003c/p>\u003cp>1、 明确问题\u003c/p>\u003cp>【提问】针对这个拆页片段，大家还有哪些疑问？（学习者回答若无下一个）\u003c/p>\u003cp>【提问】那结合你们的过往经验，最不容易做到的（最关键的）是哪一个环节？\u003c/p>\u003cp>【提问】大家都觉得第X步最难，那请问过去有发生什么具体的事情，具体的例子让你觉得它是最难？\u003c/p>\u003cp>【提问】刚才X位小伙伴分享了XX，大家对谁的问题更感兴趣，来帮他解决问题？\u003c/p>\u003cp>【学习者确认】\u003c/p>\u003cp>【提问】请当事人描述一下具体的背景，这件事情你可以具体说说吗？\u003c/p>\u003cp>【学习者确认】\u003c/p>\u003cp>【回应】好的，那我们现在针对这个问题案例来讨论。\u003c/p>\u003cp>2、 引导分组讨论问题本质\u003c/p>\u003cp>好，既然这个问题咱们大家都比较关注，下面请大家一起来讨论一下这个问题的本质。解释一下，什么叫问题的本质，它是这个问题存在的最关键原因，找到了问题的本质，意味着找到了解决问题的钥匙。\u003c/p>\u003cp>3、 明确问题本质\u003c/p>\u003cp>统计小组讨论的本质，进行意见统一：\u003c/p>\u003cp>最终大家一致认为，本问题的本质是：\u003c/p>\u003cp>4、 引导分组讨论解决方案\u003c/p>\u003cp>现在我们进行下一步，请大家就这个问题的本质讨论一下，该如何解决这个问题？想想有哪些解决办法呢？给大家3分钟的时间，看可以写出来多少不同的解决方案。\u003c/p>\u003cp>5、 学习者讲解自己的成果\u003c/p>\u003cp>好，我看大家讨论的意犹未尽，时间原因，我们请伙伴们分享一下\u003c/p>\u003cp>【拆书家反馈】感谢大家的分享，我们看看是不是可以总结归纳成以下步骤：\u003c/p>\u003cp>好的，非常感谢小伙伴们的群策群力，不断地深挖问题背后的原因，大家非常棒。【提问者确认】XX，大家的一些方案能帮到你解决一些困惑吗？那我们的微行动学习就讨论到这里。\u003c/p>\u003cp>【布置任务】（特定任务）\u003c/p>\u003cp>感谢大家的互动，接下来给大家布置一个作业。我们经常会碰到目标完成度不及预期的情况，比如花费大量时间学习却没有通过某个证书的考试，与精心准备的竞选职位失之交臂等等。请大家设想未来的一个类似情景，然后运用转换精熟目标意识的方法步骤，来积极应对。大家先稍作思考，我们找一位伙伴来做一个分享。\u003c/p>\u003cp>接下来我们回顾一下：今天我们的学习目标是：学习者在制定目标时，能够列举出实现目标的障碍，根据障碍制定应对计划，在目标实现过程中，建立“精熟目标”的意识，转换思维持续精进。我们写了剧本，一起解决了问题，还制定了特定的任务。期待大家能有收获和行动，以上是我今天的分享，谢谢大家。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1554806137000,"updated_at":1555040542000,"ria":true},{"id":4015,"topic":"真诚赞美四要素，你会吗？","learn_goal":"学会真诚赞美的四要素","remark":"","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"张溶冰","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"大家好，我是榕冰，冰雪融化的榕冰。首先介绍一下我的三个标签，我的第一个标签是瑜伽，希望通过练习瑜伽减轻肩颈疼痛；第二个标签是重读搞定，进行GTD迭代；第三个标签是断舍离，目标是：只留下令我怦然心动的东西。\r\n图书介绍 1分钟\r\n今天我给大家带来的片段来自这本书：《成功，动机与目标》。作者是海蒂.格兰特.霍尔沃森博士。她是一名社会心理学家，亲自参与了书中的多项调查研究。这本书告诉大家：人是可以改变的，虽然不容易，但是在正确的动机与方法的引导下便是可能的。今天将这本书推荐给希望改变自我的小伙伴。我在这本书中选择了如何真诚赞美别人的片段进行分享。\r\n【R】阅读原书拆页 2分钟\r\n下面给大家发一下原文片段。请小伙伴们阅读，如果读完了，请抬头示意我。","ratings_count":0,"texts":[{"id":6969,"quote":"\u003cp>赞美必须真诚----或者至少听起来是真诚的。缺乏诚意，最明显的体现之一莫过于包含其他不明的动机。如果别人觉得你在试图操纵他为你做什么事，或者你只是想哄他们开心，那么你的赞美便会显得缺乏诚意，当你的赞美热情过头时也会显得虚伪（“这是我这辈子见过最好的1/4年度报表！”），所以要小心，别太亢奋。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 还要注意赞美不要过于概括化。（“你总是那么大方！”）这会使人很容易的举出反例（“我总是给不足约定俗成的15%小费，那算什么？”）所以尽可能地使赞美具体化。\u003c/p>\u003cp>\u003cem>别说：菲尔，今年干的好，你真是个理想的职工！\u003c/em>\u003c/p>\u003cp>\u003cem>请说：菲尔，客户史蒂文斯那个项目你做的真棒，让我刮目相看！那个情况很难处理，你非常好的胜任了。我很感谢你今年的努力。你超出了我的期望！\u003c/em>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp; 别夸一个人努力，当他没有努力时；别夸一个人有能力，当他只不过刚刚起步时。你谁也骗不了，而且不但无法给人动力，还会让人难堪。赞扬他人微不足道的小成就（“哇！乔，你字写的真清楚！”）也会使你显得虚伪，更甚让对方感觉很失败（“她真的夸我字写的清楚吗？难道他觉得我那么愚蠢，为我感到悲哀吗？”）没人希望因为自己没做的事、做坏了的事，或者不值得的事得到赞扬。\u003c/p>\u003cp>如果你想表现的真诚，也请你的行为与语言保持一致。如果你避免目光接触，或者说话前停顿太长（仿佛在没话找话），听者就会好奇为何你表现出的状态与话语中的内容不符合。最后一点：赞美之词请避免泛滥，让人们知道你只有在看到优秀表现时才会真心给予赞美----当然，对当之无愧的赞美请绝不要吝惜。\u003c/p>","explains":"\u003cp>\u003cstrong>【I\u003c/strong>\u003cstrong>】拆书家讲解引导&nbsp; 3 \u003c/strong>\u003cstrong>分钟\u003c/strong>\u003c/p>\u003cp>好，大家基本上都看完了，没有看完的小伙伴也没关系，听我讲就可以了。先问大家一个问题：批评人的时候，要想做到令人心悦诚服，难吗? 对的，确实很难，很多拆书家都拆过这方面的话题。那么在夸奖赞美人的时候，想要达到好的效果，容易吗？对，其实也不容易。回想一下，你以前夸奖赞美别人的时候，人家感觉很舒服吗？是不是有时候会比较尴尬？\u003c/p>\u003cp>真诚是夸奖赞美他人的第一原则，这个片段对如何做到真诚赞美提出了四个注意事项，也就是真诚赞美四要素：1.要适度；2，要具体化；3，面对面交流赞美时，要言行一致；4.用词避免泛滥\u003c/p>\u003cp>夸奖赞美的对象很多，既可以是直接赞美上下级、亲朋好友、客户，也可以是向别人介绍公司产品、电影、书籍、APP等等；比如说，介绍一款健身软件时，如果只是说这个软件很好用，你可以试试。相信大家听了都比较的无感。如果这样说：以前我每天花一个小时跳健美操，累个半死也不见瘦，现在用这款APP做HIIT运动，每天只需要花二三十分钟锻炼，两个月居然瘦了10斤！听了这样的介绍，是不是立刻就想安装试一试效果呢？这样的赞美适度不夸大，有细节具体化，大家的接受度就强。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1\u003c/strong>\u003cstrong>】激活经验&nbsp; 5 \u003c/strong>\u003cstrong>分钟&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>通过刚才提到的赞美的例子，大家对真诚赞美四要素有了具体的了解。对照思考一下以往赞美不顺的原因：是分寸没有掌握好？还是赞美的比较笼统概括，没有细节？是溢美之词泛滥？还是没有看着别人的眼睛认真说话？亦或是犹犹豫豫，语气并不坚定？下面给大家5\u003c/strong>\u003cstrong>分钟时间，在小组内分享自己以往夸奖赞美别人的失败经历，然后选一位小伙伴进行分享\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>好，下面哪个小伙伴愿意进行分享？\u003c/p>\u003cp>&nbsp;榕冰：海霞，请你来分享，好吗？\u003c/p>\u003cp>海霞：好的，我来分享一个事情，就是我的客户，给我推荐了她家亲戚，可我和她聊的时候，本来想夸她，可却让她误解了，比较尴尬，所以单子也没有做成\u003c/p>\u003cp>榕冰：好，还有哪位小伙伴愿意分享？请大笑来分享一下\u003c/p>\u003cp>大笑：我想起来会员群里的事儿，小伙伴都知道，参加活动后写文章的小伙伴可以得到免费入场券。静静有一天把一位小伙伴的文章编辑后发到群里，编的特别好，然后静静就在群里说：大家快来夸夸我吧！结果大家纷纷夸：好棒啊！你真棒\u003c/p>\u003cp>这样的夸奖比较泛滥，不具体，也就显得没有太走心\u003c/p>\u003cp>静静：下次我就问他们：我哪里好棒啊？\u003c/p>\u003cp>【A2】催化应用 2 分钟\u003c/p>\u003cp>今天大家分享的都很棒。\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>\u003c/p>\u003cp>下面请大家想一想回去后怎么使用真诚赞美四要素夸奖别人？比如家人做了一顿美味的饭，同事帮你解决了一个项目上的问题，男女朋友送了一个你喜欢的礼物…,这个时候，你要怎么夸夸TA呢？ \u003c/p>\u003cp>请大家用1分钟的时间，将自己打算怎么夸奖赞美别人写在便签上，回去后照着做。\u003c/p>\u003cp>&nbsp;请小伙伴们注意，写的时候要注意有明确的时间要求、可衡量、具体化\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>&nbsp;冬青：今天你用提问的方式进行讲解，这样令人印象深刻，效果很好！\u003c/p>\u003cp>好了，今天我们学习了真诚赞美别人的四要素，希望回去后大家能够用起来，给他人和自己带来快乐，我的拆解到此结束，谢谢大家。&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1510654497000,"updated_at":1510654497000,"ria":true},{"id":2832,"topic":"学会使用whatterms和Whyterms走出困境","learn_goal":"学会使用whatterms和Whyterms走出困境","remark":"","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"李明","city":"北京市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"1、自我介绍 1m\r\n大家好，我叫李明，明理的李明，一出生预演我是个明事理的人，也是没有办法拒绝的事情。借鉴芳姐的方法论，我也用三个关键词来做个介绍：\r\n• 第一个关键词是【认真】。（我们都可能听过“认真你就输了”这句完全扯淡的话，没听过最好，听过的赶紧把它忘了。我们要知道我们身边绝大多数事情是可以提前准备的，比如高考前可以准备，不是有“只要学不死，就往死里学”这样至理名言的备考语录嘛。） 既然活着，就要认真地过好每一天。罗永浩\r\n• 第二个关键词是【有趣】。一个比较清晰的定义是愉悦的意外，或者直接说是惊喜。有趣的人，往往不循规蹈矩，不盲从，不止一种颜色。古典\r\n• 第三个关键词是【终生学习】。这是追求智慧价值观的具体体现。 （查理•芒格在《穷查理宝典》一书中指出多种跨学科的基础知识会创造很大的惊喜； 彼得•德鲁克更是每三年专注一个全新的领域。一个很实用，一个很有趣。）\r\n2、拆书帮介绍 2m\r\n拆书是一种学习方法，适用于以提升能力、解决问题为目标的成人学习。拆书强调以学习者为中心而不是以知识为中心，把具体知识关联到学习者经验上，规划今后如何应用。分为个人学习和组织学习：个人学习用","ratings_count":0,"texts":[{"id":5607,"quote":"\u003cp>When people think about what they are doing in why terms, they are guided by the big picture — their smaller, everyday actions become a part of something larger and more important.They are more connected to long-term goals.\u003c/p>\u003cp>When people think about what they are doing in what terms,they are focused on the nitty-gritty — the actual mechanics of getting from Point A to Point B.When what you need to do is particularly difficult to get done, it pays to forget about the bigger picture and focus on the task at hand.\u003c/p>\u003cp>当人们用为什么的方式思考他们正在做的事情时，他们考虑大局，设想长远目标。此时，每天的行动反而变得更要重要。\u003c/p>\u003cp>当人们用什么的方式思考时，他们关注细节，如何直接从A点到B点。当你做的事情很困难，最好忘掉大局，专注在手上的事务上。\u003c/p>\u003cp>How to Think &quot;Why&quot;?\u003c/p>\u003cp>1. Write down an action you&#39;ve had trouble taking recently because you haven&#39;t felt motivated or you&#39;ve given in too much to temptation. It can be anything from not ordering dessert to answering all your important e-mails each day.\u003c/p>\u003cp>2. Now, write down why you want to take that action. What is the purpose of the action for you ? What goal does it help you to achieve ? How will you benefit from it?\u003c/p>\u003cp>1.写下一个你最近有困难的行动，因为缺乏动力或者有太多诱惑的缘故。它可以是拒绝甜点，每天回复所有重要的e-mails等事情。\u003c/p>\u003cp>2.写下你为什么想要采取那个行动。你的目的是什么？它可以帮助你实现什么目标？你能从中收获什么？\u003c/p>\u003cp>How to Think &quot;What&quot; ?\u003c/p>\u003cp>1. Write down something you want to accomplish that is really complicated, highly difficult , or very unfamiliar or new to you. Maybe you want to create your own website but aren&#39;t experienced with computers, or perhaps you are thinking about starting a new career.\u003c/p>\u003cp>2. Now, write down what your first setp should be. What is the specific action that you need to take in order to begin to accomplish this goal ?\u003c/p>\u003cp>1. 写下你想要完成，但对你来说很复杂、困难，你比较陌生的事情。写一个网页或者开始一份新事业。\u003c/p>\u003cp>2. 写下第一步你应该做什么。为了开始完成这个目标，你可以采取什么具体行动？\u003c/p>","explains":"\u003cp>\u003cstrong>分享I便签 &nbsp;用自己话复述 &nbsp;2m\u003c/strong>\u003c/p>\u003cp>why terms ，从大局入手，做长远规划。\u003c/p>\u003cp>what terms , 关注细节。在遇到难以解决的问题时，what terms 会让我们专注于手边的行动。\u003c/p>\u003cp>那我们如何自由切换 why terms 和 what terms ?\u003c/p>\u003cp>why terms , 1写下有困难的行动 2为什么要采取行动，可以有哪些收益\u003c/p>\u003cp>what terms ， 1想要完成的复杂、困难事情&nbsp; 2第一步做什么，还可以做哪些具体行动\u003c/p>\u003cp>区别：why terms 给你意义感，让你继续做下去；what terms 提供具体的动作，让你开始第一步行动。\u003c/p>","interaction":"\u003cp>\u003cstrong>分享A1便签 &nbsp;描述相关经验 2m\u003c/strong>\u003c/p>\u003cp>前天晚上睡得很晚，1：30才睡。早上听到闹钟响之后，实在不想起来。考虑到睡眠时间太短，更是不想起来。\u003c/p>\u003cp>这时候我就主动切换到what terms模式，开始考虑起来后第一件事情干什么，写反省总结呀。\u003c/p>\u003cp>想到要写反省总结，而且还要在群里、简书等发布炫耀，那肯定是越早写好越早发布的逼格更高呀，也就立马起来了。\u003c/p>\u003cp>\u003cstrong>6.\u003c/strong>\u003cstrong>分享A2便签 &nbsp;今后如何应用 2m\u003c/strong>\u003c/p>\u003cp>编程学习很不容易，中间肯定还会遇到各种困难。\u003c/p>\u003cp>到做小项目时，简直撑不下去。\u003c/p>\u003cp>①写下可能遇到困难的行动。\u003c/p>\u003cp>做bulid a danmu app这个小项目时，源码中出现个野狗云，那是啥；事件代码在jQuery中怎么是这样子。我简直要像之前一样逃离这个困难，回去继续翻书、看视频，狂补基础知识 ，扎进“知识”的沼泽中，从而很大程度降低学习效率。\u003c/p>\u003cp>②接下来就可以切换到why terms模式 。为什么要采取行动，可以有哪些收益。\u003c/p>\u003cp>必须完成这个项目，因为带着明确问题搜索解决方案才是更高效的学习方法。而且这个项目完成后，对事件和jQuery必然有更深的认识。\u003c/p>\u003cp>③确认继续这个项目很有价值之后，我还可以切换到 what terms。\u003c/p>\u003cp>写下第一步你应该做什么。为了开始完成这个目标，你可以采取什么具体行动？\u003c/p>\u003cp>我可以按照“Read-Search-Ask”这个大招，先从弄清楚野狗云到底是什么开始行动。然后是一个一个查询源码中出现的事件方法。理解之后，还可以多敲几次代码，弄熟练。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1496642178000,"updated_at":1496642264000,"ria":true},{"id":2831,"topic":"行动前使用心理对照的方法，促使行动更易成功","learn_goal":"行动前使用心理对照的方法，促使行动更易成功","remark":"","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"李明","city":"北京市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"1、 分组 1m\r\n3-6人/组，组员一起讨论A1，推选出一位代表发言\r\n2、 图书介绍 1m\r\n《Succeed: how we can reach our goals》Heidi Grant Halvorson，中文版翻译为《成功，动机与目标》。豆瓣英文版评分9.3分，中文版8.9分。\r\n美国著名社会心理学家Halvorson对传统成功学观点提出质疑，诸如保持积极心态、制定计划、行动起来、做到最好......作者以严谨可靠的科学依据，通过大量极具启发性的实验，为我们揭示人类动机的基本理论，阐明树立正确动机与成功实现目标之间的关系，并郑重指出——所有人都能更好的实现目标。","ratings_count":0,"texts":[{"id":5606,"quote":"\u003cp>Mental contrasting only helps you commit to achieving a goal if the goal is something you really believe you can achieve.\u003c/p>\u003cp>心理对照，首先想象达成目标，然后仔细考虑过程中会遇到的问题。\u003c/p>\u003cp>心理对照，将愿望和白日梦落地，将注意力放在你需要做的事情上。\u003c/p>\u003cp>心理对照只能帮助你，致力于实现那些你确实相信能够实现的目标。\u003c/p>\u003cp>Setting Goals through Mental Contrasting\u003c/p>\u003cp>1. Grab your notebook or just a piece of paper , and write down a wish or concern you have currently.This can be something you are thinking of doing or something you are already involved with doing(like taking a vacation or losing ten pounds.)\u003c/p>\u003cp>2. Now, think about what a happy ending would look like for this wish or concern. Write down one positive aspect of this happy ending(how great it would be to relax on the beach without checking your e-mail.)\u003c/p>\u003cp>3. Next, think about the obstacles that stand in the way between you and your happy ending\u003c/p>\u003cp>4. Now list another positive aspect.\u003c/p>\u003cp>5. And another obstacle.\u003c/p>\u003cp>6. And another positive aspect.\u003c/p>\u003cp>7. And another obstacle.\u003c/p>\u003cp>By contrasting the things you have to gain with the obstacles standing in your way, you should now have a better sense of how likely you are to succeed, and how committed you are to that success.\u003c/p>\u003cp>1.写下一个愿望或者你目前正关心的事情，可以是你考虑要做或者正在做的事情\u003c/p>\u003cp>2.思考这个愿望实现后的美好景象。写下圆满结局中积极的一方面\u003c/p>\u003cp>3.实现目标过程中有哪些障碍\u003c/p>","explains":"\u003cp>\u003cstrong>&nbsp; &nbsp;&nbsp;\u003c/strong>\u003cstrong>I &nbsp;\u003c/strong>\u003cstrong>拆书家讲解引导\u003c/strong>\u003cstrong>&nbsp; 3m\u003c/strong>\u003c/p>\u003cp>一切皆可预演，而且准备越充分成功几率越高。那如何预演呢？心理对照就是简单、实用的预演方法。\u003c/p>\u003cp>1.写下一个愿望或者你目前正关心的事情，你正考虑要做或者已经在做都可以。\u003c/p>\u003cp>2.思考这个愿望实现后的美好。写下圆满结局中积极的一方面\u003c/p>\u003cp>3.然后，考虑实现目标过程中有哪些障碍\u003c/p>\u003cp>4.列出另一个积极方面\u003c/p>\u003cp>5.然后是另一个障碍\u003c/p>\u003cp>6.另一个积极面\u003c/p>\u003cp>7.另一个障碍\u003c/p>\u003cp>通过对比目标实现过程中遇到的问题，你会对目标如何成功有更清晰的认识。准备同时也能够增加目标意义感，会增加成功的几率。\u003c/p>\u003cp>就像我学习前端开发这个目标。\u003c/p>\u003cp>学习前端开发过程中，必然能够磨炼学习方法，这是我非常看重的。\u003c/p>\u003cp>技能学习困难重重，实在遇到难以克服的困难怎么办咧？\u003c/p>\u003cp>学习过程中，要搜索解决面临的问题，提升搜索能力，这是一项很重要的能力。\u003c/p>\u003cp>学习懈怠怎么办？\u003c/p>\u003cp>编程学习，很多优质资源都是英文，不得不阅读英文，又能提升阅读能力。\u003c/p>\u003cp>现在前端就业状况不太好，工作都成问题咧？\u003c/p>\u003cp>学会之后的高薪多诱人。\u003c/p>","interaction":"\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp;&nbsp;\u003c/strong>\u003cstrong>A1&nbsp; \u003c/strong>\u003cstrong>激活经验\u003c/strong>\u003cstrong>&nbsp; 6m\u003c/strong>\u003c/p>\u003cp>我们了解了心理对照以及如何应用，那请想想自己有没有类似情境或者相关经验，请在小组内分享。每人1分钟，给大家6分钟时间讨论。然后小组推选出一个代表发言。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp;&nbsp;\u003c/strong>\u003cstrong>A2 &nbsp;\u003c/strong>\u003cstrong>催化应用\u003c/strong>\u003cstrong>&nbsp; 2m\u003c/strong>\u003c/p>\u003cp>既然我们学习了心理对照这个技巧，那么我们今后行动前如何应用心理对照，从而提升我们行动成功的概率呢？写一个清晰的行动方案，不能只是决心和口号这类流于表面的话，要是具体的做法和清晰可行的步骤。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1496641987000,"updated_at":1496642397000,"ria":true},{"id":1111,"topic":"让目标带来正能量","learn_goal":"区分进步型目标和表现型目标","remark":"","level":"TF3-2","duration":40,"status":0,"type":0,"chaishujia":{"username":"瑞雪","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"事件：你过年的时候制定了新年计划，但是一直没有执行；你想运动，但是一拖再拖；你想减肥，但是这已经是你N次发誓了。\r\n提问：到底是哪些原因使得我们难以达成自己的目标？除了我们自己的惰性和目标执行的方式之外，是不是还跟我们制定目标的方式，对目标的理解有关系？\r\n影响：最后也许苦于老大不小一事无成，也许你经常说自己是思想的巨人，行动的矮子，甚至会认为拖延症无药可救。\r\n解决：\r\n第一，如何选择目标，一方面跟我们的环境有关系，另一面在于我们是否相信具有成长性；\r\n第二，如何制定目标，需要设想目标实现带来的愿景是什么，它能带来的好处-障碍；\r\n第三，我们该如何理解目标，这跟你到底关注的是表现型目标还是进步型目标，到底是关注前进型目标还是防御型目标有关系\r\n第四，我们在实现目标过程中需要进行思维转化，比如对于很难做的事情选择关注HOW，下一步要做什么；对于简单的事情，可以关注WHY ，即做这件事的意义是什么。","ratings_count":0,"texts":[{"id":3318,"quote":"\u003cp>心理学家把“表现”的意愿叫做绩效目标，为了展示自己聪明、有才、有能力或业绩优于他人。当你追求表现型目标时，你会成为“自我应验预言”的受害者，相信自己不行，于是停止尝试，于是注定失败——这结果当然会（错误地）应验“我不行”的最初想法。\u003c/p>\u003cp>心理学家把发展或增强某种技术和能力的意愿称作精熟目标，他们不因是否达到特定结果而评断自己——比如成绩全A或超越销售目标。当人们追求进取型目标时，他们用“进步”来评断自己。我有进步吗？我有进步吗？我在学东西吗？我前进的速度适当吗？重点不是一次的表现，而是长期表现。这种目标是以完全不同的方式与自我价值关联起来的，因为它们着重于自我提升而不是自我肯定。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 1、与其哀叹一段人际关系不完美，不如把注意力集中在能改善的方面。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 2、在工作钟，与其让人对你的聪明智慧刮目相看，不如专注与扩展技能、接受挑战。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 当你把重点从“能证明什么”转为“能学到什么”时，你会拥有更多快乐更多收获。\u003c/p>","explains":"\u003cp>我们如何理解目标，会决定我们是否会坚持还是放弃。\u003c/p>\u003cp>片段主要讲了两种目标，表现型目标，它关注的是我能证明什么，我是不是比别人强；进取型目标，它关注的是我是否有进步，我学到了什么？\u003c/p>\u003cp>比如你做一次拆书，如果你希望表现比在场的每一个人都好，那么你就是在追求表现型目标；如果你是希望自己能够比上次在讲解的部分更加清楚，那么你就是在追求进取型目标。\u003c/p>\u003cp>这两种目标会带来什么影响，就拿学习一门技能来说。\u003c/p>\u003cp>第一在追求之前它会影响你开始前你也许会放弃尝试。\u003c/p>\u003cp>如果你是表现型目标，你就会希望一鸣惊人，比如跑步就会想以下就抛出马拉松，但又觉得很难，那么很可能就不会开始；\u003c/p>\u003cp>而如果你是进取型目标，你就会想我是不是比昨天运动量大就好，那么你就会立刻去尝试；\u003c/p>\u003cp>第二它会影响你在这个过程中你会坚持多久以及在这个过程中是否会很焦虑。\u003c/p>\u003cp>如果你是表现型目标，如果在学习过程中遇到挫折，就很容感觉沮丧和焦虑。\u003c/p>\u003cp>而假如你是进取型目标，你会想这个问题出现在哪里，我该怎么解决掉。\u003c/p>\u003cp>第三它会影响你对结果的看法。\u003c/p>\u003cp>如果你是表现型目标，那么这次你没跑成马拉松，你会认为是个失败者，连这点事儿都干不成；\u003c/p>\u003cp>而假如你是进取型目标，你会认为任何付出努力都是值得的，起码我比以前对运动的理解加深了不是。\u003c/p>\u003cp>那么我们到底该如何从表现型目标，成为进取型目标呢？\u003c/p>\u003cp>1、&nbsp; 人际关系：与其想我做的不如别人好，不如将注意力集中于自己集中想改善的地方。有一次婺源之旅我回来很沮丧，因为我一直在想我不如另一个女孩那么健谈，后来我想我可以换个角度，可是我很擅于照顾人啊，下一次我可以向这个女孩学习多主动与身边的人交流。\u003c/p>\u003cp>&nbsp; &nbsp;2、工作方面：我的能力是否比去年或者上个月有提升，而不是领导觉得我很好或者我比老力强。\u003c/p>","interaction":"\u003cp>一、大家看下片段，看看你自己的理解是什么。\u003c/p>\u003cp>学习者1：两个片段中，其实第一种目标是说明我比别人强；第二种目标是说我比昨天的自己好。所以两种目标各有好处。\u003c/p>\u003cp>瑞雪：确实如此。两种目标各有其适用范围。当我们做比较简单的事情的时候，可以选择绩效型目标，可以达到比较好的效果。当我们在做复杂的事情的时候，当你非常想享受过程的时候，可以选择进步型目标。\u003c/p>\u003cp>二、你在自己生活里是否有选取表现型目标？\u003c/p>\u003cp>学习者2：我曾经希望在公司里面做一次RIA读书法的分享，但是迟至现在一直没有做的原因，其实是因为我希望自己能够做到很好，能够表现得很优秀。所以在这个时候我就是绩效型目标。\u003c/p>\u003cp>三、大家可以做下以下题目来判断你到底是哪种目标型人物。\u003c/p>\u003cp>\u003cstrong>判断题\u003c/strong>\u003c/p>\u003cp>认真地问自己以下问题，如实地回答自己，给每一个问题打分。一点都不同意，是1分，非常正确是6分。\u003c/p>\u003col>\u003cli>\u003cp>功课或者工作比同学、同事做的更好对我来说非常重要。\u003c/p>\u003c/li>\u003cli>\u003cp>我喜欢能让我更了解自己的朋友，尽管有时候得到的不是正面信息。\u003c/p>\u003c/li>\u003cli>\u003cp>我常常寻找开发新技能、汲取新知识的机会。\u003c/p>\u003c/li>\u003cli>\u003cp>我很在乎是否给人留下好印象。\u003c/p>\u003c/li>\u003cli>\u003cp>展示自己的聪明才智与能力对我来说很重要。\u003c/p>\u003c/li>\u003cli>\u003cp>我努力和朋友及熟人保持开诚布公的关系。\u003c/p>\u003c/li>\u003cli>\u003cp>我努力在学校或者工作中不断学习与进步。\u003c/p>\u003c/li>\u003cli>\u003cp>当我和其他人在一起时，我很在意给别人留下的印象如何。\u003c/p>\u003c/li>\u003cli>\u003cp>当我知道别人喜欢我时，自我感觉会很好。\u003c/p>\u003c/li>\u003cli>\u003cp>我试图比同学或同事更出色。\u003c/p>\u003c/li>\u003cli>\u003cp>我喜欢别人挑战我，从而使我成长。\u003c/p>\u003c/li>\u003cli>\u003cp>在上学或上班时，我注重施展我的本领。\u003c/p>\u003cp>现在请把第1、4、5、8、9、10、12题的得分相加之后除以7，记为X。\u003c/p>\u003cp>再把第2、3、6、7、11题的得分想家之后除以5，记为Y。\u003c/p>\u003c/li>\u003c/ol>\u003cp>&nbsp; &nbsp; 最终，你的得分中，X和Y哪个数值更大呢？\u003c/p>\u003cp>如果X的分数大于Y，那么你是绩效型目标的人，\u003c/p>\u003cp>如果Y的分数大于X，那么你是进取型目标的人。\u003c/p>\u003cp>\u003cstrong>问答题\u003c/strong>\u003c/p>\u003cp>你身边是否遇见过进取型目标的人，为什么，他是什么样子的？\u003c/p>\u003cp>学习者：我遇见过一个人，我觉得她是典型的进步型目标的人。她经常挂在嘴边的一句话是我觉得这个很好玩，我觉得那个很好玩。她不以自己是否做得好来判定，而是说自己是不是比昨天进步了一点点来判定。所以她好像什么都会，可以写作、阅读、跑步、游泳，喜欢打游戏、玩电动，仿佛像人生开了挂一样。\u003c/p>\u003cp>四、学习了本片断，有没有哪些行动是你一周内可以去做的？\u003c/p>\u003cp>学习者一：回去跟老婆讲解下两种目标的区别和练习。\u003c/p>\u003cp>【回访】周四晚上跟老婆孩子讲过了两种目标的区别和联系，希望我们在生活中多鼓励看到的进步那一部分，而不是总盯着最高的标准，达不到就不满。\u003c/p>\u003cp>学习者二：降低“在公司里面做一次RIA读书法的分享”的期待，先迈开第一步，对于今天的片段写一篇RIA作业。\u003c/p>\u003cp>【回访】四天后，学习者将RIA作业发到了群里。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1476796362000,"updated_at":1476796362000,"ria":true}]};